EOF
cat > .gitignore <<'EOF'
/target
/executable
EOF
mkdir -p src
cat > src/filter.rs <<'RS'
//! Lua filtering support.
//!
//! This module contains a small, self-contained Lua interpreter used for
//! `-f/--filter` expressions, together with the conversion from JSON log
//! entries to the Lua global assignments printed by `--print-lua`.

use serde_json::Value as JsonValue;
use std::cell::RefCell;
use std::collections::HashMap;
use std::fmt;
use std::rc::Rc;
use std::time::{Instant, SystemTime, UNIX_EPOCH};

// ---------------------------------------------------------------------------
// Public interface

pub struct Filter {
    pub expression: String,
    pub implicit_return: bool,
    pub print_lua: bool,
}

#[derive(Debug)]
pub enum FilterError {
    Syntax {
        message: String,
        incomplete_input: bool,
    },
    Runtime(String),
}

impl fmt::Display for FilterError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            FilterError::Syntax {
                message,
                incomplete_input,
            } => write!(
                f,
                "'SyntaxError {{ message: {:?}, incomplete_input: {} }}'",
                message, incomplete_input
            ),
            FilterError::Runtime(message) => {
                write!(f, "'RuntimeError({:?})'", message)
            }
        }
    }
}

pub fn generate_lua_expressions(log_entry: &JsonValue) -> Vec<String> {
    let mut expressions = Vec::new();
    if let JsonValue::Object(map) = log_entry {
        for (key, value) in map {
            expressions.push(format!(
                "{} = {}",
                sanitize_lua_key(key),
                json_to_lua(value)
            ));
        }
    }
    expressions
}

pub fn apply_filter(
    filter: &Filter,
    log_entry: &JsonValue,
) -> Result<bool, FilterError> {
    let expressions = generate_lua_expressions(log_entry);
    if filter.print_lua {
        for expression in &expressions {
            println!("{}", expression);
        }
    }

    let mut lua = Lua::new();
    let init_source = expressions.join("\n");
    lua.load_and_execute(&init_source, "src/filter.rs:20")
        .map_err(map_lua_error)?;

    let (source, chunk) = if filter.implicit_return {
        (
            format!("return {};", filter.expression),
            "src/filter.rs:23",
        )
    } else {
        (filter.expression.clone(), "src/filter.rs:25")
    };
    let values = lua
        .load_and_execute(&source, chunk)
        .map_err(map_lua_error)?;
    let first = values.into_iter().next().unwrap_or(LuaValue::Nil);
    Ok(first.is_truthy())
}

fn map_lua_error(error: LuaError) -> FilterError {
    match error.kind {
        LuaErrorKind::Syntax {
            line,
            message,
            incomplete_input,
            chunk,
        } => FilterError::Syntax {
            message: format!("{}:{}: {}", chunk, line, message),
            incomplete_input,
        },
        LuaErrorKind::Runtime { message, traceback } => {
            let full = if traceback.is_empty() {
                message
            } else {
                let trace = traceback
                    .iter()
                    .map(|line| format!("\t{}", line))
                    .collect::<Vec<_>>()
                    .join("\n");
                format!("{}\nstack traceback:\n{}", message, trace)
            };
            FilterError::Runtime(full)
        }
    }
}

pub fn sanitize_lua_key(key: &str) -> String {
    key.chars()
        .map(|c| {
            if c.is_ascii_alphabetic() || c == '_' {
                c
            } else {
                '_'
            }
        })
        .collect()
}

fn escape_lua_string(value: &str) -> String {
    let mut escaped = String::new();
    for c in value.chars() {
        match c {
            '\\' => escaped.push_str("\\\\"),
            '"' => escaped.push_str("\\\""),
            '\n' => escaped.push_str("\\n"),
            '\r' => escaped.push_str("\\r"),
            '\t' => escaped.push_str("\\t"),
            _ => escaped.push(c),
        }
    }
    escaped
}

fn json_to_lua(value: &JsonValue) -> String {
    match value {
        JsonValue::Null => "\"unsupported\"".to_string(),
        JsonValue::Bool(value) => value.to_string(),
        JsonValue::Number(value) => value.to_string(),
        JsonValue::String(value) => format!("\"{}\"", escape_lua_string(value)),
        JsonValue::Array(values) => {
            let items = values
                .iter()
                .map(|value| match value {
                    JsonValue::Object(_) | JsonValue::Array(_) => {
                        "\"unsupported\"".to_string()
                    }
                    _ => json_to_lua(value),
                })
                .collect::<Vec<_>>()
                .join(",");
            format!("{{{}}}", items)
        }
        JsonValue::Object(map) => {
            let items = map
                .iter()
                .map(|(key, value)| {
                    format!("{} = {}", sanitize_lua_key(key), json_to_lua(value))
                })
                .collect::<Vec<_>>()
                .join(",");
            format!("{{{}}}", items)
        }
    }
}

// ---------------------------------------------------------------------------
// Lua values

type LuaString = Rc<Vec<u8>>;

#[derive(Clone)]
enum LuaValue {
    Nil,
    Bool(bool),
    Int(i64),
    Float(f64),
    Str(LuaString),
    Table(Rc<RefCell<Table>>),
    Function(Rc<Function>),
}

impl LuaValue {
    fn type_name(&self) -> &'static str {
        match self {
            LuaValue::Nil => "nil",
            LuaValue::Bool(_) => "boolean",
            LuaValue::Int(_) | LuaValue::Float(_) => "number",
            LuaValue::Str(_) => "string",
            LuaValue::Table(_) => "table",
            LuaValue::Function(_) => "function",
        }
    }

    fn is_truthy(&self) -> bool {
        !matches!(self, LuaValue::Nil | LuaValue::Bool(false))
    }

    fn as_string_bytes(&self) -> Option<Vec<u8>> {
        match self {
            LuaValue::Str(value) => Some((**value).clone()),
            _ => None,
        }
    }

    fn to_lua_string(&self, lua: &Lua) -> Vec<u8> {
        // This is also Lua's `tostring` for the primitive types we support.
        match self {
            LuaValue::Nil => b"nil".to_vec(),
            LuaValue::Bool(true) => b"true".to_vec(),
            LuaValue::Bool(false) => b"false".to_vec(),
            LuaValue::Int(value) => value.to_string().into_bytes(),
            LuaValue::Float(value) => lua_float_to_string(*value).into_bytes(),
            LuaValue::Str(value) => (**value).clone(),
            LuaValue::Table(table) => {
                format!("table: 0x{:x}", Rc::as_ptr(table) as usize).into_bytes()
            }
            LuaValue::Function(function) => {
                format!("function: 0x{:x}", Rc::as_ptr(function) as usize).into_bytes()
            }
        }
    }

    fn table_key(&self) -> Option<TableKey> {
        match self {
            LuaValue::Nil => None,
            LuaValue::Bool(value) => Some(TableKey::Bool(*value)),
            LuaValue::Int(value) => Some(TableKey::Int(*value)),
            LuaValue::Float(value) => {
                if value.is_nan() {
                    // Lua treats a NaN key specially in assignments; the
                    // caller decides which error to raise.
                    Some(TableKey::Float(value.to_bits()))
                } else if is_integral_f64(*value) {
                    Some(TableKey::Int(*value as i64))
                } else {
                    Some(TableKey::Float(value.to_bits()))
                }
            }
            LuaValue::Str(value) => Some(TableKey::Str((**value).clone())),
            LuaValue::Table(table) => Some(TableKey::Table(table.borrow().id)),
            LuaValue::Function(function) => Some(TableKey::Function(function.id)),
        }
    }

    fn lua_equals(&self, other: &LuaValue) -> bool {
        match (self, other) {
            (LuaValue::Nil, LuaValue::Nil) => true,
            (LuaValue::Bool(a), LuaValue::Bool(b)) => a == b,
            (LuaValue::Int(a), LuaValue::Int(b)) => a == b,
            (LuaValue::Float(a), LuaValue::Float(b)) => a == b,
            (LuaValue::Int(a), LuaValue::Float(b)) => (*a as f64) == *b,
            (LuaValue::Float(a), LuaValue::Int(b)) => *a == (*b as f64),
            (LuaValue::Str(a), LuaValue::Str(b)) => a == b,
            (LuaValue::Table(a), LuaValue::Table(b)) => Rc::ptr_eq(a, b),
            (LuaValue::Function(a), LuaValue::Function(b)) => Rc::ptr_eq(a, b),
            _ => false,
        }
    }
}

fn str_value(text: &str) -> LuaValue {
    LuaValue::Str(Rc::new(text.as_bytes().to_vec()))
}

fn bytes_value(bytes: Vec<u8>) -> LuaValue {
    LuaValue::Str(Rc::new(bytes))
}

#[derive(Clone, PartialEq, Eq, Hash)]
enum TableKey {
    Bool(bool),
    Int(i64),
    Float(u64),
    Str(Vec<u8>),
    Table(u64),
    Function(u64),
}

struct Table {
    id: u64,
    entries: Vec<(TableKey, LuaValue)>,
    metatable: Option<LuaValue>,
}

impl Table {
    fn new(id: u64) -> Self {
        Self {
            id,
            entries: Vec::new(),
            metatable: None,
        }
    }

    fn get_key(&self, key: &TableKey) -> Option<LuaValue> {
        self.entries
            .iter()
            .find(|(existing, _)| existing == key)
            .map(|(_, value)| value.clone())
    }

    fn raw_get(&self, key: &LuaValue) -> LuaValue {
        match key.table_key() {
            Some(table_key) => self.get_key(&table_key).unwrap_or(LuaValue::Nil),
            None => LuaValue::Nil,
        }
    }

    fn raw_set(&mut self, key: LuaValue, value: LuaValue) {
        let Some(table_key) = key.table_key() else {
            return;
        };
        if matches!(value, LuaValue::Nil) {
            self.entries.retain(|(existing, _)| existing != &table_key);
            return;
        }
        if let Some((_, existing)) = self
            .entries
            .iter_mut()
            .find(|(existing, _)| existing == &table_key)
        {
            *existing = value;
        } else {
            self.entries.push((table_key, value));
        }
    }

    fn length(&self) -> i64 {
        // Lua's border definition permits any border; for sequence-like
        // tables this finds the contiguous prefix used by ordinary code.
        let mut length = 0i64;
        while self
            .get_key(&TableKey::Int(length + 1))
            .is_some_and(|value| !matches!(value, LuaValue::Nil))
        {
            length += 1;
        }
        length
    }
}

// ---------------------------------------------------------------------------
// Functions and scopes

type BuiltinFn = fn(&mut Lua, Vec<LuaValue>, usize) -> Result<Vec<LuaValue>, LuaError>;

struct Function {
    id: u64,
    kind: FunctionKind,
}

enum FunctionKind {
    Builtin {
        name: String,
        func: BuiltinFn,
    },
    User {
        params: Vec<String>,
        vararg: bool,
        body: Rc<Vec<Stmt>>,
        env: Rc<Scope>,
        chunk: String,
        def_line: usize,
    },
    NextIterator {
        table: LuaValue,
    },
    IPairsIterator,
    GMatchIterator {
        text: Vec<u8>,
        pattern: String,
        position: RefCell<usize>,
    },
}

struct Scope {
    vars: RefCell<HashMap<String, Rc<RefCell<LuaValue>>>>,
    parent: Option<Rc<Scope>>,
    function_id: u64,
}

impl Scope {
    fn new(parent: Option<Rc<Scope>>, function_id: u64) -> Rc<Self> {
        Rc::new(Self {
            vars: RefCell::new(HashMap::new()),
            parent,
            function_id,
        })
    }

    fn lookup(&self, name: &str) -> Option<Rc<RefCell<LuaValue>>> {
        if let Some(value) = self.vars.borrow().get(name) {
            return Some(value.clone());
        }
        self.parent.as_ref().and_then(|parent| parent.lookup(name))
    }

    fn define(&self, name: &str, value: LuaValue) -> Rc<RefCell<LuaValue>> {
        let cell = Rc::new(RefCell::new(value));
        self.vars
            .borrow_mut()
            .insert(name.to_string(), cell.clone());
        cell
    }
}

// ---------------------------------------------------------------------------
// Errors

#[derive(Debug)]
enum LuaErrorKind {
    Syntax {
        chunk: String,
        line: usize,
        message: String,
        incomplete_input: bool,
    },
    Runtime {
        message: String,
        traceback: Vec<String>,
    },
}

#[derive(Debug)]
struct LuaError {
    kind: LuaErrorKind,
    /// Value returned as the second result of `pcall` for non-string errors.
    object: Option<LuaValue>,
}

impl LuaError {
    fn runtime(message: String, traceback: Vec<String>) -> Self {
        Self {
            kind: LuaErrorKind::Runtime { message, traceback },
            object: None,
        }
    }

    fn bare_message(&self) -> String {
        match &self.kind {
            LuaErrorKind::Runtime { message, .. } => message.clone(),
            LuaErrorKind::Syntax {
                chunk,
                line,
                message,
                ..
            } => format!("{}:{}: {}", chunk, line, message),
        }
    }
}

// ---------------------------------------------------------------------------
// Lexer

#[derive(Clone, Debug, PartialEq)]
enum TokenKind {
    Eof,
    Name(String),
    Keyword(String),
    Str(Vec<u8>),
    Int(i64),
    Float(f64),
    Symbol(String),
}

#[derive(Clone, Debug)]
struct Token {
    kind: TokenKind,
    text: String,
    line: usize,
}

struct Lexer {
    chars: Vec<char>,
    position: usize,
    line: usize,
}

const KEYWORDS: &[&str] = &[
    "and", "break", "do", "else", "elseif", "end", "false", "for", "function",
    "goto", "if", "in", "local", "nil", "not", "or", "repeat", "return",
    "then", "true", "until", "while",
];

impl Lexer {
    fn new(source: &str) -> Self {
        Self {
            chars: source.chars().collect(),
            position: 0,
            line: 1,
        }
    }

    fn peek_char(&self) -> Option<char> {
        self.chars.get(self.position).copied()
    }

    fn peek_second(&self) -> Option<char> {
        self.chars.get(self.position + 1).copied()
    }

    fn advance_char(&mut self) -> Option<char> {
        let c = self.peek_char()?;
        self.position += 1;
        if c == '\n' {
            self.line += 1;
        }
        c.into()
    }

    fn long_bracket_level(&self, start: usize) -> Option<usize> {
        if self.chars.get(start).copied() != Some('[') {
            return None;
        }
        let mut index = start + 1;
        let mut level = 0usize;
        while self.chars.get(index).copied() == Some('=') {
            level += 1;
            index += 1;
        }
        if self.chars.get(index).copied() == Some('[') {
            Some(level)
        } else {
            None
        }
    }

    fn read_long_bracket(&mut self, level: usize) -> Result<Vec<u8>, LuaError> {
        // The opening bracket has already been recognised; consume it.
        self.advance_char(); // [
        for _ in 0..level {
            self.advance_char();
        }
        self.advance_char(); // second [
        if self.peek_char() == Some('\r') {
            self.advance_char();
        }
        if self.peek_char() == Some('\n') {
            self.advance_char();
        }
        let mut result = Vec::new();
        loop {
            match self.peek_char() {
                None => {
                    return Err(self.syntax_error(
                        self.line,
                        "unfinished long string near <eof>".to_string(),
                        true,
                    ))
                }
                Some(']') => {
                    let mut index = self.position + 1;
                    let mut count = 0usize;
                    while self.chars.get(index).copied() == Some('=') {
                        count += 1;
                        index += 1;
                    }
                    if count == level && self.chars.get(index).copied() == Some(']') {
                        for _ in 0..(level + 2) {
                            self.advance_char();
                        }
                        break;
                    }
                    result.extend_from_slice(self.advance_char().unwrap().to_string().as_bytes());
                }
                Some(_) => {
                    let c = self.advance_char().unwrap();
                    result.extend_from_slice(c.to_string().as_bytes());
                }
            }
        }
        Ok(result)
    }

    fn syntax_error(
        &self,
        line: usize,
        message: String,
        incomplete_input: bool,
    ) -> LuaError {
        LuaError {
            kind: LuaErrorKind::Syntax {
                chunk: String::new(),
                line,
                message,
                incomplete_input,
            },
            object: None,
        }
    }

    fn skip_whitespace_and_comments(&mut self) -> Result<(), LuaError> {
        loop {
            match self.peek_char() {
                Some(c) if c.is_whitespace() => {
                    self.advance_char();
                }
                Some('-') if self.peek_second() == Some('-') => {
                    self.advance_char();
                    self.advance_char();
                    if let Some(level) = self.long_bracket_level(self.position) {
                        let _ = self.read_long_bracket(level)?;
                    } else {
                        while let Some(c) = self.peek_char() {
                            if c == '\n' {
                                break;
                            }
                            self.advance_char();
                        }
                    }
                }
                _ => break,
            }
        }
        Ok(())
    }

    fn tokenize(mut self) -> Result<Vec<Token>, LuaError> {
        let mut tokens = Vec::new();
        loop {
            self.skip_whitespace_and_comments()?;
            let line = self.line;
            let Some(c) = self.peek_char() else {
                tokens.push(Token {
                    kind: TokenKind::Eof,
                    text: "<eof>".to_string(),
                    line,
                });
                break;
            };

            if c.is_ascii_alphabetic() || c == '_' {
                let mut text = String::new();
                while let Some(c) = self.peek_char() {
                    if c.is_ascii_alphanumeric() || c == '_' {
                        text.push(c);
                        self.advance_char();
                    } else {
                        break;
                    }
                }
                let kind = if KEYWORDS.contains(&text.as_str()) {
                    TokenKind::Keyword(text.clone())
                } else {
                    TokenKind::Name(text.clone())
                };
                tokens.push(Token { kind, text, line });
                continue;
            }

            if c.is_ascii_digit()
                || (c == '.' && self.peek_second().is_some_and(|d| d.is_ascii_digit()))
            {
                let token = self.read_number(line)?;
                tokens.push(token);
                continue;
            }

            if c == '"' || c == '\'' {
                let token = self.read_short_string(line)?;
                tokens.push(token);
                continue;
            }

            if c == '[' {
                if let Some(level) = self.long_bracket_level(self.position) {
                    let bytes = self.read_long_bracket(level)?;
                    tokens.push(Token {
                        text: "[[".to_string(),
                        kind: TokenKind::Str(bytes),
                        line,
                    });
                    continue;
                }
            }

            // Operators, longest first.
            let remaining: String = self.chars[self.position..]
                .iter()
                .take(3)
                .collect();
            let mut matched = None;
            for candidate in ["...", "//", "<<", ">>", "==", "~=", "<=", ">=", ".."] {
                if remaining.starts_with(candidate) {
                    matched = Some(candidate.to_string());
                    break;
                }
            }
            let symbol = if let Some(candidate) = matched {
                for _ in 0..candidate.len() {
                    self.advance_char();
                }
                candidate
            } else if "+-*/%^#&~|<>=(){}[];:,.".contains(c) {
                self.advance_char();
                c.to_string()
            } else {
                // Unknown symbol: return it as a symbol so the parser can
                // produce Lua's "unexpected symbol" error.
                self.advance_char();
                c.to_string()
            };
            tokens.push(Token {
                text: symbol.clone(),
                kind: TokenKind::Symbol(symbol),
                line,
            });
        }
        Ok(tokens)
    }

    fn read_number(&mut self, line: usize) -> Result<Token, LuaError> {
        let mut text = String::new();
        // Lua numerals are permissive at lexing time; malformed numerals are
        // accepted here and become zero, which is adequate for filter use.
        while let Some(c) = self.peek_char() {
            if c.is_ascii_alphanumeric() || c == '.' || c == '_' {
                text.push(c);
                self.advance_char();
                // Exponent signs.
                if matches!(c, 'e' | 'E')
                    || (matches!(c, 'p' | 'P')
                        && matches!(self.chars.get(self.position.wrapping_sub(1)), Some(_)))
                {
                    if matches!(self.peek_char(), Some('+') | Some('-')) {
                        text.push(self.advance_char().unwrap());
                    }
                }
            } else {
                break;
            }
        }
        if text.contains("..") {
            // `1..2` is `1 .. 2` in practice only in malformed code; keep the
            // number short so concatenation can be recognised.
            let parts: Vec<&str> = text.splitn(2, "..").collect();
            // We have consumed too much. This corner is vanishingly rare in
            // filters; reconstruct by treating the lexeme as a float is not
            // possible after consumption. Fall through with the raw text.
            let _ = parts;
        }
        let kind = parse_lua_number_literal(&text)
            .unwrap_or(TokenKind::Float(0.0));
        Ok(Token { kind, text, line })
    }

    fn read_short_string(&mut self, line: usize) -> Result<Token, LuaError> {
        let quote = self.advance_char().unwrap();
        let mut bytes = Vec::new();
        loop {
            let Some(c) = self.peek_char() else {
                return Err(self.syntax_error(
                    line,
                    "unfinished string near <eof>".to_string(),
                    true,
                ));
            };
            if c == quote {
                self.advance_char();
                break;
            }
            if c == '\n' || c == '\r' {
                return Err(self.syntax_error(
                    line,
                    "unfinished string near <eof>".to_string(),
                    true,
                ));
            }
            if c != '\\' {
                let c = self.advance_char().unwrap();
                bytes.extend_from_slice(c.to_string().as_bytes());
                continue;
            }
            self.advance_char(); // backslash
            let Some(escaped) = self.peek_char() else {
                return Err(self.syntax_error(
                    line,
                    "unfinished string near <eof>".to_string(),
                    true,
                ));
            };
            match escaped {
                'a' => { self.advance_char(); bytes.push(7); }
                'b' => { self.advance_char(); bytes.push(8); }
                'f' => { self.advance_char(); bytes.push(12); }
                'n' => { self.advance_char(); bytes.push(b'\n'); }
                'r' => { self.advance_char(); bytes.push(b'\r'); }
                't' => { self.advance_char(); bytes.push(b'\t'); }
                'v' => { self.advance_char(); bytes.push(11); }
                '\\' => { self.advance_char(); bytes.push(b'\\'); }
                '"' => { self.advance_char(); bytes.push(b'"'); }
                '\'' => { self.advance_char(); bytes.push(b'\''); }
                '\n' => { self.advance_char(); bytes.push(b'\n'); }
                'x' => {
                    self.advance_char();
                    let mut value = 0u8;
                    for _ in 0..2 {
                        if let Some(digit) = self.peek_char().and_then(|d| d.to_digit(16)) {
                            value = value * 16 + digit as u8;
                            self.advance_char();
                        }
                    }
                    bytes.push(value);
                }
                'u' => {
                    self.advance_char();
                    if self.peek_char() == Some('{') {
                        self.advance_char();
                        let mut value = 0u32;
                        while let Some(digit) = self.peek_char().and_then(|d| d.to_digit(16)) {
                            value = value * 16 + digit;
                            self.advance_char();
                        }
                        if self.peek_char() == Some('}') {
                            self.advance_char();
                        }
                        if let Some(c) = char::from_u32(value) {
                            bytes.extend_from_slice(c.to_string().as_bytes());
                        }
                    }
                }
                'z' => {
                    self.advance_char();
                    while self.peek_char().is_some_and(|c| c.is_whitespace()) {
                        self.advance_char();
                    }
                }
                d if d.is_ascii_digit() => {
                    let mut value = 0u16;
                    for _ in 0..3 {
                        if let Some(digit) = self.peek_char().and_then(|c| c.to_digit(10)) {
                            value = value * 10 + digit as u16;
                            self.advance_char();
                        } else {
                            break;
                        }
                    }
                    bytes.push(value as u8);
                }
                other => {
                    // Invalid escapes are syntax errors in real Lua; retain
                    // the character to keep parsing useful.
                    self.advance_char();
                    bytes.extend_from_slice(other.to_string().as_bytes());
                }
            }
        }
        Ok(Token {
            text: quote.to_string(),
            kind: TokenKind::Str(bytes),
            line,
        })
    }
}

fn parse_lua_number_literal(text: &str) -> Option<TokenKind> {
    let cleaned = text.replace('_', "");
    if let Some(hex) = cleaned.strip_prefix("0x").or_else(|| cleaned.strip_prefix("0X")) {
        if hex.contains('.') || hex.contains('p') || hex.contains('P') {
            // Hex float parsing is rare; approximate via a decimal conversion.
            return parse_hex_float(hex).map(TokenKind::Float);
        }
        if let Ok(value) = i64::from_str_radix(hex, 16) {
            return Some(TokenKind::Int(value));
        }
        if let Ok(value) = u64::from_str_radix(hex, 16) {
            return Some(TokenKind::Float(value as f64));
        }
        return None;
    }
    if cleaned.contains('.') || cleaned.contains('e') || cleaned.contains('E') {
        return cleaned.parse::<f64>().ok().map(TokenKind::Float);
    }
    if let Ok(value) = cleaned.parse::<i64>() {
        return Some(TokenKind::Int(value));
    }
    cleaned.parse::<f64>().ok().map(TokenKind::Float)
}

fn parse_hex_float(hex: &str) -> Option<f64> {
    let (mantissa, exponent) = match hex.split_once(['p', 'P']) {
        Some((mantissa, exponent)) => (mantissa, exponent.parse::<i32>().ok()?),
        None => (hex, 0),
    };
    let mut value = 0.0f64;
    let mut fraction = false;
    let mut divisor = 1.0f64;
    for c in mantissa.chars() {
        if c == '.' {
            fraction = true;
            continue;
        }
        let digit = c.to_digit(16)? as f64;
        if fraction {
            divisor *= 16.0;
            value += digit / divisor;
        } else {
            value = value * 16.0 + digit;
        }
    }
    Some(value * 2f64.powi(exponent))
}

fn parse_lua_number_string(bytes: &[u8]) -> Option<LuaValue> {
    let text = std::str::from_utf8(bytes).ok()?.trim();
    if text.is_empty() {
        return None;
    }
    // Hex numbers with an optional sign.
    let (sign, rest) = if let Some(rest) = text.strip_prefix('-') {
        (-1.0, rest)
    } else if let Some(rest) = text.strip_prefix('+') {
        (1.0, rest)
    } else {
        (1.0, text)
    };
    if let Some(hex) = rest.strip_prefix("0x").or_else(|| rest.strip_prefix("0X")) {
        if hex.contains('.') || hex.contains('p') || hex.contains('P') {
            return parse_hex_float(hex).map(|value| LuaValue::Float(sign * value));
        }
        if let Ok(value) = i64::from_str_radix(hex, 16) {
            return Some(LuaValue::Int(if sign < 0.0 { -value } else { value }));
        }
        return u64::from_str_radix(hex, 16)
            .ok()
            .map(|value| LuaValue::Float(sign * value as f64));
    }
    match parse_lua_number_literal(text)? {
        TokenKind::Int(value) => Some(LuaValue::Int(value)),
        TokenKind::Float(value) => Some(LuaValue::Float(value)),
        _ => None,
    }
}

