                    self.next();
                    let (name, line) = self.expect_name()?;
                    let args = self.parse_call_arguments()?;
                    expression = Expr {
                        kind: ExprKind::Call {
                            function: Box::new(expression),
                            args,
                            method: Some(name),
                        },
                        line,
                    };
                }
                TokenKind::Symbol(symbol) if symbol == "(" => {
                    // A `(` immediately after a value, or following it as a
                    // call. Lua also permits whitespace, so treat all as calls.
                    let args = self.parse_call_arguments()?;
                    expression = Expr {
                        kind: ExprKind::Call {
                            function: Box::new(expression),
                            args,
                            method: None,
                        },
                        line: token.line,
                    };
                }
                TokenKind::Str(_) => {
                    // Function call sugar: `f "text"`.
                    let argument = self.parse_primary()?;
                    expression = Expr {
                        kind: ExprKind::Call {
                            function: Box::new(expression),
                            args: vec![argument],
                            method: None,
                        },
                        line: token.line,
                    };
                }
                TokenKind::Symbol(symbol) if symbol == "{" => {
                    // Function call sugar: `f{...}`.
                    let argument = self.parse_primary()?;
                    expression = Expr {
                        kind: ExprKind::Call {
                            function: Box::new(expression),
                            args: vec![argument],
                            method: None,
                        },
                        line: token.line,
                    };
                }
                _ => break,
            }
        }
        Ok(expression)
    }

    fn parse_call_arguments(&mut self) -> Result<Vec<Expr>, LuaError> {
        if let TokenKind::Str(_) = self.peek().kind {
            return Ok(vec![self.parse_primary()?]);
        }
        if matches!(&self.peek().kind, TokenKind::Symbol(s) if s == "{") {
            return Ok(vec![self.parse_primary()?]);
        }
        self.expect_symbol("(")?;
        let mut arguments = Vec::new();
        if self.check_symbol(")") {
            return Ok(arguments);
        }
        loop {
            arguments.push(self.parse_expression()?);
            if self.check_symbol(",") {
                continue;
            }
            self.expect_symbol(")")?;
            break;
        }
        Ok(arguments)
    }

    fn parse_primary(&mut self) -> Result<Expr, LuaError> {
        let token = self.peek().clone();
        match token.kind {
            TokenKind::Keyword(ref keyword) if keyword == "nil" => {
                self.next();
                Ok(Expr { kind: ExprKind::Nil, line: token.line })
            }
            TokenKind::Keyword(ref keyword) if keyword == "true" => {
                self.next();
                Ok(Expr { kind: ExprKind::Bool(true), line: token.line })
            }
            TokenKind::Keyword(ref keyword) if keyword == "false" => {
                self.next();
                Ok(Expr { kind: ExprKind::Bool(false), line: token.line })
            }
            TokenKind::Keyword(ref keyword) if keyword == "function" => {
                self.next();
                self.parse_function_body(token.line)
            }
            TokenKind::Int(value) => {
                self.next();
                Ok(Expr { kind: ExprKind::Int(value), line: token.line })
            }
            TokenKind::Float(value) => {
                self.next();
                Ok(Expr { kind: ExprKind::Float(value), line: token.line })
            }
            TokenKind::Str(bytes) => {
                self.next();
                Ok(Expr { kind: ExprKind::Str(bytes), line: token.line })
            }
            TokenKind::Name(name) => {
                self.next();
                Ok(Expr { kind: ExprKind::Var(name), line: token.line })
            }
            TokenKind::Symbol(ref symbol) if symbol == "..." => {
                self.next();
                Ok(Expr { kind: ExprKind::Vararg, line: token.line })
            }
            TokenKind::Symbol(ref symbol) if symbol == "(" => {
                self.next();
                let expression = self.parse_expression()?;
                self.expect_symbol(")")?;
                Ok(Expr {
                    kind: ExprKind::Paren(Box::new(expression)),
                    line: token.line,
                })
            }
            TokenKind::Symbol(ref symbol) if symbol == "{" => {
                self.next();
                self.parse_table_constructor(token.line)
            }
            _ => self.unexpected(&token),
        }
    }

    fn parse_table_constructor(&mut self, line: usize) -> Result<Expr, LuaError> {
        let mut fields = Vec::new();
        if self.check_symbol("}") {
            return Ok(Expr {
                kind: ExprKind::Table(fields),
                line,
            });
        }
        loop {
            let token = self.peek().clone();
            if matches!(&token.kind, TokenKind::Symbol(s) if s == "[") {
                self.next();
                let key = self.parse_expression()?;
                self.expect_symbol("]")?;
                self.expect_symbol("=")?;
                let value = self.parse_expression()?;
                fields.push(TableField::Keyed(key, value));
            } else if matches!(&token.kind, TokenKind::Name(_))
                && matches!(&self.peek_second().kind, TokenKind::Symbol(s) if s == "=")
            {
                let (name, _) = self.expect_name()?;
                self.expect_symbol("=")?;
                let value = self.parse_expression()?;
                fields.push(TableField::Named(name, value));
            } else {
                let value = self.parse_expression()?;
                fields.push(TableField::Positional(value));
            }

            if self.check_symbol(",") || self.check_symbol(";") {
                if self.check_symbol("}") {
                    break;
                }
                continue;
            }
            self.expect_symbol("}")?;
            break;
        }
        Ok(Expr {
            kind: ExprKind::Table(fields),
            line,
        })
    }
}
