    fn execute_statements(
        &mut self,
        statements: &[Stmt],
        env: &Rc<Scope>,
        varargs: &[LuaValue],
    ) -> Result<Flow, LuaError> {
        for statement in statements {
            match self.execute_statement(statement, env, varargs)? {
                Flow::Normal => {}
                flow => return Ok(flow),
