// ---------------------------------------------------------------------------
// Interpreter

struct Frame {
    description: String,
    chunk: String,
    line: usize,
    function_scope_id: u64,
    is_main: bool,
}

struct Lua {
    globals: LuaValue,
    frames: Vec<Frame>,
    next_id: u64,
    rng_state: u64,
    started: Instant,
    current_chunk: String,
}

enum Flow {
    Normal,
    Return(Vec<LuaValue>),
    Break,
}

impl Lua {
    fn new() -> Self {
        let mut lua = Self {
            globals: LuaValue::Nil,
            frames: Vec::new(),
            next_id: 1,
            rng_state: SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .map(|duration| duration.as_nanos() as u64 ^ std::process::id() as u64)
                .unwrap_or(0x9e37_79b9_7f4a_7c15),
            started: Instant::now(),
            current_chunk: String::new(),
        };
        let globals = lua.new_table();
        lua.globals = globals;
        install_standard_library(&mut lua);
        if let LuaValue::Table(table) = &lua.globals {
            let globals_clone = lua.globals.clone();
            table.borrow_mut().raw_set(str_value("_G"), globals_clone);
            table.borrow_mut().raw_set(str_value("_VERSION"), str_value("Lua 5.4"));
        }
        lua
    }

    fn allocate_id(&mut self) -> u64 {
        let id = self.next_id;
        self.next_id += 1;
        id
    }

    fn new_table(&mut self) -> LuaValue {
        LuaValue::Table(Rc::new(RefCell::new(Table::new(self.allocate_id()))))
    }

    fn make_function(&mut self, kind: FunctionKind) -> LuaValue {
        LuaValue::Function(Rc::new(Function {
            id: self.allocate_id(),
            kind,
        }))
    }

    fn builtin(&mut self, name: &str, func: BuiltinFn) -> LuaValue {
        self.make_function(FunctionKind::Builtin {
            name: name.to_string(),
            func,
        })
    }

    fn set_global(&mut self, name: &str, value: LuaValue) {
        if let LuaValue::Table(table) = &self.globals {
            table.borrow_mut().raw_set(str_value(name), value);
        }
    }

    fn get_global(&self, name: &str) -> LuaValue {
        if let LuaValue::Table(table) = &self.globals {
            table.borrow().raw_get(&str_value(name))
        } else {
            LuaValue::Nil
        }
    }

    fn set_line(&mut self, line: usize) {
        if let Some(frame) = self.frames.last_mut() {
            frame.line = line;
        }
    }

    fn current_line(&self) -> usize {
        self.frames.last().map(|frame| frame.line).unwrap_or(1)
    }

    fn current_chunk(&self) -> String {
        self.frames
            .last()
            .map(|frame| frame.chunk.clone())
            .unwrap_or_else(|| self.current_chunk.clone())
    }

    fn frame_trace(&self) -> Vec<String> {
        self.frames
            .iter()
            .rev()
            .map(|frame| frame.description.replace("{line}", &frame.line.to_string()))
            .collect()
    }

    fn runtime_error(&self, message: String, mut prefix: Vec<String>) -> LuaError {
        let mut traceback = Vec::new();
        traceback.append(&mut prefix);
        traceback.extend(self.frame_trace());
        LuaError::runtime(message, traceback)
    }

    fn located_message(&self, line: usize, message: &str) -> String {
        format!("{}:{}: {}", self.current_chunk(), line, message)
    }

    fn error_at(&self, line: usize, message: &str, prefix: Vec<String>) -> LuaError {
        self.runtime_error(self.located_message(line, message), prefix)
    }

    fn load_and_execute(
        &mut self,
        source: &str,
        chunk: &str,
    ) -> Result<Vec<LuaValue>, LuaError> {
        let mut parser = Parser::new(source, chunk)?;
        let statements = parser.parse_chunk()?;
        self.current_chunk = chunk.to_string();
        self.frames.push(Frame {
            description: format!("{}:{{line}}: in main chunk", chunk),
            chunk: chunk.to_string(),
            line: 1,
            function_scope_id: 0,
            is_main: true,
        });
        let root_scope = Scope::new(None, 0);
        let result = self.execute_block(&statements, &root_scope, &[]);
        self.frames.pop();
        match result? {
            Flow::Return(values) => Ok(values),
            _ => Ok(Vec::new()),
        }
    }

    fn execute_block(
        &mut self,
        statements: &[Stmt],
        env: &Rc<Scope>,
        varargs: &[LuaValue],
    ) -> Result<Flow, LuaError> {
        let scope = Scope::new(Some(env.clone()), current_function_scope(self, env));
        self.execute_statements(statements, &scope, varargs)
    }

    fn execute_statements(
        &mut self,
        statements: &[Stmt],
        env: &Rc<Scope>,
        varargs: &[LuaValue],
    ) -> Result<Flow, LuaError> {
        for statement in statements {
            match self.execute_statement(statement, env, varargs)? {
                Flow::Normal => {}
                flow => return Ok(flow),
            }
        }
        Ok(Flow::Normal)
    }

    fn execute_statement(
        &mut self,
        statement: &Stmt,
        env: &Rc<Scope>,
        varargs: &[LuaValue],
    ) -> Result<Flow, LuaError> {
        match statement {
            Stmt::Empty => Ok(Flow::Normal),
            Stmt::LocalAssign { names, values, line } => {
                self.set_line(*line);
                let evaluated = self.evaluate_expression_list(values, env, varargs)?;
                for (index, name) in names.iter().enumerate() {
                    let value = evaluated.get(index).cloned().unwrap_or(LuaValue::Nil);
                    env.define(name, value);
                }
                Ok(Flow::Normal)
            }
            Stmt::LocalFunction { name, function, line } => {
                self.set_line(*line);
                let cell = env.define(name, LuaValue::Nil);
                let value = self.evaluate(function, env, varargs)?;
                *cell.borrow_mut() = value;
                Ok(Flow::Normal)
            }
            Stmt::Assign { targets, values, line } => {
                self.set_line(*line);
                let evaluated = self.evaluate_expression_list(values, env, varargs)?;
                for (index, target) in targets.iter().enumerate() {
                    let value = evaluated.get(index).cloned().unwrap_or(LuaValue::Nil);
                    self.assign_target(target, value, env, varargs)?;
                }
                Ok(Flow::Normal)
            }
            Stmt::Call { expression, .. } => {
                let _ = self.evaluate(expression, env, varargs)?;
                Ok(Flow::Normal)
            }
            Stmt::Do { body, .. } => self.execute_block(body, env, varargs),
            Stmt::While { condition, body, line } => {
                loop {
                    self.set_line(*line);
                    if !self.evaluate(condition, env, varargs)?.is_truthy() {
                        break;
                    }
                    match self.execute_block(body, env, varargs)? {
                        Flow::Normal => {}
                        Flow::Break => break,
                        Flow::Return(values) => return Ok(Flow::Return(values)),
                    }
                }
                Ok(Flow::Normal)
            }
            Stmt::Repeat { body, condition, line } => {
                loop {
                    self.set_line(*line);
                    let scope = Scope::new(Some(env.clone()), current_function_scope(self, env));
                    match self.execute_statements(body, &scope, varargs)? {
                        Flow::Normal => {}
                        Flow::Break => break,
                        Flow::Return(values) => return Ok(Flow::Return(values)),
                    }
                    self.set_line(*line);
                    if self.evaluate(condition, &scope, varargs)?.is_truthy() {
                        break;
                    }
                }
                Ok(Flow::Normal)
            }
            Stmt::If { arms, else_body, line } => {
                for (condition, body) in arms {
                    self.set_line(*line);
                    if self.evaluate(condition, env, varargs)?.is_truthy() {
                        return self.execute_block(body, env, varargs);
                    }
                }
                if let Some(body) = else_body {
                    return self.execute_block(body, env, varargs);
                }
                Ok(Flow::Normal)
            }
            Stmt::NumericFor { name, start, stop, step, body, line } => {
                self.set_line(*line);
                let start_value = self.evaluate(start, env, varargs)?;
                let stop_value = self.evaluate(stop, env, varargs)?;
                let step_value = if let Some(step) = step {
                    self.evaluate(step, env, varargs)?
                } else {
                    LuaValue::Int(1)
                };
                self.execute_numeric_for(
                    name, start_value, stop_value, step_value, body, env, varargs, *line,
                )
            }
            Stmt::GenericFor { names, iterators, body, line } => {
                self.set_line(*line);
                let evaluated = self.evaluate_expression_list(iterators, env, varargs)?;
                let iterator = evaluated.get(0).cloned().unwrap_or(LuaValue::Nil);
                let state = evaluated.get(1).cloned().unwrap_or(LuaValue::Nil);
                let mut control = evaluated.get(2).cloned().unwrap_or(LuaValue::Nil);
                let loop_scope = Scope::new(Some(env.clone()), current_function_scope(self, env));
                let mut cells = Vec::new();
                for name in names {
                    cells.push(loop_scope.define(name, LuaValue::Nil));
                }
                loop {
                    let results = self.call_value(
                        iterator.clone(),
                        vec![state.clone(), control.clone()],
                        *line,
                        None,
                        env,
                    )?;
                    let first = results.get(0).cloned().unwrap_or(LuaValue::Nil);
                    if matches!(first, LuaValue::Nil) {
                        break;
                    }
                    control = first;
                    for (index, cell) in cells.iter().enumerate() {
                        *cell.borrow_mut() =
                            results.get(index).cloned().unwrap_or(LuaValue::Nil);
                    }
                    match self.execute_block(body, &loop_scope, varargs)? {
                        Flow::Normal => {}
                        Flow::Break => break,
                        Flow::Return(values) => return Ok(Flow::Return(values)),
                    }
                }
                Ok(Flow::Normal)
            }
            Stmt::FunctionStatement { target, function, line, .. } => {
                self.set_line(*line);
                let value = self.evaluate(function, env, varargs)?;
                self.assign_target(target, value, env, varargs)?;
                Ok(Flow::Normal)
            }
            Stmt::Return { values, line } => {
                self.set_line(*line);
                let evaluated = self.evaluate_expression_list(values, env, varargs)?;
                Ok(Flow::Return(evaluated))
            }
            Stmt::Break { line } => {
                self.set_line(*line);
                Ok(Flow::Break)
            }
        }
    }

    fn execute_numeric_for(
        &mut self,
        name: &str,
        start: LuaValue,
        stop: LuaValue,
        step: LuaValue,
        body: &[Stmt],
        env: &Rc<Scope>,
        varargs: &[LuaValue],
        line: usize,
    ) -> Result<Flow, LuaError> {
        // Integer loops stay integer; anything else uses floats.
        let all_integers = [&start, &stop, &step]
            .iter()
            .all(|value| matches!(value, LuaValue::Int(_)));
        let loop_scope = Scope::new(Some(env.clone()), current_function_scope(self, env));
        let cell = loop_scope.define(name, start.clone());
        if all_integers {
            let (start, stop, step) = (
                int_value(&start).unwrap_or(0),
                int_value(&stop).unwrap_or(0),
                int_value(&step).unwrap_or(0),
            );
            if step == 0 {
                return Err(self.error_at(line, "'for' step is zero", Vec::new()));
            }
            let mut current = start;
            loop {
                if (step > 0 && current > stop) || (step < 0 && current < stop) {
                    break;
                }
                *cell.borrow_mut() = LuaValue::Int(current);
                match self.execute_block(body, &loop_scope, varargs)? {
                    Flow::Normal => {}
                    Flow::Break => break,
                    Flow::Return(values) => return Ok(Flow::Return(values)),
                }
                match current.checked_add(step) {
                    Some(next) => current = next,
                    None => break,
                }
            }
        } else {
            let start = number_as_f64(&start).unwrap_or(0.0);
            let stop = number_as_f64(&stop).unwrap_or(0.0);
            let step = number_as_f64(&step).unwrap_or(0.0);
            if step == 0.0 {
                return Err(self.error_at(line, "'for' step is zero", Vec::new()));
            }
            let mut current = start;
            loop {
                if (step > 0.0 && current > stop) || (step < 0.0 && current < stop) {
                    break;
                }
                *cell.borrow_mut() = LuaValue::Float(current);
                match self.execute_block(body, &loop_scope, varargs)? {
                    Flow::Normal => {}
                    Flow::Break => break,
                    Flow::Return(values) => return Ok(Flow::Return(values)),
                }
                current += step;
            }
        }
        Ok(Flow::Normal)
    }

    fn evaluate_expression_list(
        &mut self,
        expressions: &[Expr],
        env: &Rc<Scope>,
        varargs: &[LuaValue],
    ) -> Result<Vec<LuaValue>, LuaError> {
        let mut values = Vec::new();
        for (index, expression) in expressions.iter().enumerate() {
            if index + 1 == expressions.len() {
                values.extend(self.evaluate_multiple(expression, env, varargs)?);
            } else {
                values.push(self.evaluate(expression, env, varargs)?);
            }
        }
        Ok(values)
    }

    fn evaluate_multiple(
        &mut self,
        expression: &Expr,
        env: &Rc<Scope>,
        varargs: &[LuaValue],
    ) -> Result<Vec<LuaValue>, LuaError> {
        match &expression.kind {
            ExprKind::Call { .. } => {
                let (values, _) = self.evaluate_call(expression, env, varargs)?;
                Ok(values)
            }
            ExprKind::Vararg => Ok(varargs.to_vec()),
            ExprKind::Paren(inner) => Ok(vec![self.evaluate(inner, env, varargs)?]),
            _ => Ok(vec![self.evaluate(expression, env, varargs)?]),
        }
    }

    fn evaluate(
        &mut self,
        expression: &Expr,
        env: &Rc<Scope>,
        varargs: &[LuaValue],
    ) -> Result<LuaValue, LuaError> {
        self.set_line(expression.line);
        match &expression.kind {
            ExprKind::Nil => Ok(LuaValue::Nil),
            ExprKind::Bool(value) => Ok(LuaValue::Bool(*value)),
            ExprKind::Int(value) => Ok(LuaValue::Int(*value)),
            ExprKind::Float(value) => Ok(LuaValue::Float(*value)),
            ExprKind::Str(bytes) => Ok(bytes_value(bytes.clone())),
            ExprKind::Var(name) => Ok(self.lookup_variable(name, env)),
            ExprKind::Vararg => Ok(varargs.get(0).cloned().unwrap_or(LuaValue::Nil)),
            ExprKind::Paren(inner) => self.evaluate(inner, env, varargs),
            ExprKind::Index(base, key) => {
                let base_value = self.evaluate(base, env, varargs)?;
                let key_value = self.evaluate(key, env, varargs)?;
                self.index_value(base_value, key_value, base, env, expression.line)
            }
            ExprKind::Call { .. } => {
                let (values, _) = self.evaluate_call(expression, env, varargs)?;
                Ok(values.into_iter().next().unwrap_or(LuaValue::Nil))
            }
            ExprKind::Function { params, vararg, body } => {
                let function = FunctionKind::User {
                    params: params.clone(),
                    vararg: *vararg,
                    body: body.clone(),
                    env: env.clone(),
                    chunk: self.current_chunk(),
                    def_line: expression.line,
                };
                Ok(self.make_function(function))
            }
            ExprKind::Table(fields) => {
                let table = self.new_table();
                let mut positional = 1i64;
                for (index, field) in fields.iter().enumerate() {
                    let is_last = index + 1 == fields.len();
                    match field {
                        TableField::Positional(value_expression) => {
                            if is_last {
                                let values = self.evaluate_multiple(
                                    value_expression,
                                    env,
                                    varargs,
                                )?;
                                for value in values {
                                    self.table_set(
                                        table.clone(),
                                        LuaValue::Int(positional),
                                        value,
                                        expression.line,
                                    )?;
                                    positional += 1;
                                }
                            } else {
                                let value = self.evaluate(value_expression, env, varargs)?;
                                self.table_set(
                                    table.clone(),
                                    LuaValue::Int(positional),
                                    value,
                                    expression.line,
                                )?;
                                positional += 1;
                            }
                        }
                        TableField::Named(name, value_expression) => {
                            let value = self.evaluate(value_expression, env, varargs)?;
                            self.table_set(
                                table.clone(),
                                str_value(name),
                                value,
                                expression.line,
                            )?;
                        }
                        TableField::Keyed(key_expression, value_expression) => {
                            let key = self.evaluate(key_expression, env, varargs)?;
                            let value = self.evaluate(value_expression, env, varargs)?;
                            self.table_set(table.clone(), key, value, expression.line)?;
                        }
                    }
                }
                Ok(table)
            }
            ExprKind::Unary { operator, operand } => {
                let value = self.evaluate(operand, env, varargs)?;
                self.evaluate_unary(operator, value, expression.line)
            }
            ExprKind::Binary { operator, left, right } => {
                self.evaluate_binary(operator, left, right, env, varargs, expression.line)
            }
        }
    }

    fn lookup_variable(&self, name: &str, env: &Rc<Scope>) -> LuaValue {
        if let Some(cell) = env.lookup(name) {
            return cell.borrow().clone();
        }
        self.get_global(name)
    }

    fn classify_variable(&self, name: &str, env: &Rc<Scope>) -> &'static str {
        let current_function = self
            .frames
            .last()
            .map(|frame| frame.function_scope_id)
            .unwrap_or(0);
        let mut scope = Some(env.clone());
        while let Some(current) = scope {
            if current.vars.borrow().contains_key(name) {
                return if current.function_id == current_function {
                    "local"
                } else {
                    "upvalue"
                };
            }
            scope = current.parent.clone();
        }
        "global"
    }

    fn expression_description(
        &self,
        expression: &Expr,
        env: &Rc<Scope>,
    ) -> Option<(String, String)> {
        match &expression.kind {
            ExprKind::Var(name) => Some((
                self.classify_variable(name, env).to_string(),
                name.clone(),
            )),
            ExprKind::Index(_, key) => {
                if let ExprKind::Str(bytes) = &key.kind {
                    Some((
                        "field".to_string(),
                        String::from_utf8_lossy(bytes).into_owned(),
                    ))
                } else if let ExprKind::Int(index) = &key.kind {
                    Some(("field".to_string(), index.to_string()))
                } else {
                    None
                }
            }
            ExprKind::Paren(inner) => self.expression_description(inner, env),
            _ => None,
        }
    }

    fn index_value(
        &mut self,
        base: LuaValue,
        key: LuaValue,
        base_expression: &Expr,
        env: &Rc<Scope>,
        line: usize,
    ) -> Result<LuaValue, LuaError> {
        self.set_line(line);
        match &base {
            LuaValue::Table(table) => {
                let raw = table.borrow().raw_get(&key);
                if !matches!(raw, LuaValue::Nil) {
                    return Ok(raw);
                }
                // Minimal metamethod support for `__index`.
                let metatable = table.borrow().metatable.clone();
                if let Some(metatable) = metatable {
                    if let LuaValue::Table(metatable) = &metatable {
                        let index = metatable.borrow().raw_get(&str_value("__index"));
                        match index {
                            LuaValue::Table(_) => {
                                return Ok(self.index_value(index, key, base_expression, env, line)?);
                            }
                            LuaValue::Function(_) => {
                                let results = self.call_value(
                                    index,
                                    vec![base.clone(), key.clone()],
                                    line,
                                    None,
                                    env,
                                )?;
                                return Ok(results.into_iter().next().unwrap_or(LuaValue::Nil));
                            }
                            _ => {}
                        }
                    }
                }
                Ok(raw)
            }
            LuaValue::Str(_) => {
                // Strings index into the string library.
                let string_table = self.get_global("string");
                if let LuaValue::Table(table) = string_table {
                    Ok(table.borrow().raw_get(&key))
                } else {
                    Ok(LuaValue::Nil)
                }
            }
            _ => {
                let description = self
                    .expression_description(base_expression, env)
                    .map(|(kind, name)| format!(" ({} '{}')", kind, name))
                    .unwrap_or_default();
                Err(self.error_at(
                    line,
                    &format!(
                        "attempt to index a {} value{}",
                        base.type_name(),
                        description
                    ),
                    vec!["[C]: in metamethod 'index'".to_string()],
                ))
            }
        }
    }

    fn table_set(
        &mut self,
        table_value: LuaValue,
        key: LuaValue,
        value: LuaValue,
        line: usize,
    ) -> Result<(), LuaError> {
        let LuaValue::Table(table) = table_value else {
            return Err(self.error_at(
                line,
                &format!(
                    "attempt to index a {} value",
                    table_value.type_name()
                ),
                vec!["[C]: in metamethod 'newindex'".to_string()],
            ));
        };
        if matches!(key, LuaValue::Nil) {
            return Err(self.error_at(line, "table index is nil", Vec::new()));
        }
        if matches!(key, LuaValue::Float(value) if value.is_nan()) {
            return Err(self.error_at(line, "table index is NaN", Vec::new()));
        }
        // Minimal `__newindex` support.
        let metatable = table.borrow().metatable.clone();
        let already_present = !matches!(table.borrow().raw_get(&key), LuaValue::Nil);
        if !already_present {
            if let Some(LuaValue::Table(metatable)) = &metatable {
                let newindex = metatable.borrow().raw_get(&str_value("__newindex"));
                match newindex {
                    LuaValue::Table(_) => {
                        let target = newindex.clone();
                        // Avoid recursion through this helper for a table
                        // target by using another table assignment round.
                        if let LuaValue::Table(target_table) = target {
                            target_table.borrow_mut().raw_set(key, value);
                        }
                        return Ok(());
                    }
                    LuaValue::Function(_) => {
                        let function = newindex.clone();
                        let table_clone = LuaValue::Table(table.clone());
                        let _ = self.call_value(
                            function,
                            vec![table_clone, key, value],
                            line,
                            None,
                            &Scope::new(None, 0),
                        )?;
                        return Ok(());
                    }
                    _ => {}
                }
            }
        }
        table.borrow_mut().raw_set(key, value);
        Ok(())
    }

    fn assign_target(
        &mut self,
        target: &Expr,
        value: LuaValue,
        env: &Rc<Scope>,
        varargs: &[LuaValue],
    ) -> Result<(), LuaError> {
        match &target.kind {
            ExprKind::Var(name) => {
                if let Some(cell) = env.lookup(name) {
                    *cell.borrow_mut() = value;
                } else {
                    self.set_global(name, value);
                }
                Ok(())
            }
            ExprKind::Index(base, key) => {
                let base_value = self.evaluate(base, env, varargs)?;
                let key_value = self.evaluate(key, env, varargs)?;
                if let LuaValue::Table(_) = base_value {
                    self.table_set(base_value, key_value, value, target.line)
                } else {
                    let description = self
                        .expression_description(base, env)
                        .map(|(kind, name)| format!(" ({} '{}')", kind, name))
                        .unwrap_or_default();
                    Err(self.error_at(
                        target.line,
                        &format!(
                            "attempt to index a {} value{}",
                            base_value.type_name(),
                            description
                        ),
                        vec!["[C]: in metamethod 'newindex'".to_string()],
                    ))
                }
            }
            ExprKind::Paren(inner) => self.assign_target(inner, value, env, varargs),
            _ => Err(self.error_at(target.line, "invalid assignment target", Vec::new())),
        }
    }

    fn evaluate_call(
        &mut self,
        expression: &Expr,
        env: &Rc<Scope>,
        varargs: &[LuaValue],
    ) -> Result<(Vec<LuaValue>, ()), LuaError> {
        let ExprKind::Call { function, args, method } = &expression.kind else {
            unreachable!()
        };
        self.set_line(expression.line);
        let (callee, call_args) = if let Some(method_name) = method {
            let base = self.evaluate(function, env, varargs)?;
            let function_value = self.index_value(
                base.clone(),
                str_value(method_name),
                function,
                env,
                expression.line,
            )?;
            let mut evaluated = vec![base];
            for argument in args {
                evaluated.push(self.evaluate(argument, env, varargs)?);
            }
            (function_value, evaluated)
        } else {
            let function_value = self.evaluate(function, env, varargs)?;
            let mut evaluated = Vec::new();
            for (index, argument) in args.iter().enumerate() {
                if index + 1 == args.len() {
                    evaluated.extend(self.evaluate_multiple(argument, env, varargs)?);
                } else {
                    evaluated.push(self.evaluate(argument, env, varargs)?);
                }
            }
            (function_value, evaluated)
        };

        let description = if method.is_some() {
            method.as_ref().map(|name| ("method".to_string(), name.clone()))
        } else {
            self.expression_description(function, env)
        };
        let display = call_display_name(function, method, &callee);
        let values = self.call_value_with_description(
            callee,
            call_args,
            expression.line,
            description,
            display,
            env,
        )?;
        Ok((values, ()))
    }

    fn call_value(
        &mut self,
        callee: LuaValue,
        args: Vec<LuaValue>,
        line: usize,
        description: Option<(String, String)>,
        env: &Rc<Scope>,
    ) -> Result<Vec<LuaValue>, LuaError> {
        let display = match &callee {
            LuaValue::Function(function) => match &function.kind {
                FunctionKind::Builtin { name, .. } => Some(name.clone()),
                _ => None,
            },
            _ => None,
        };
        self.call_value_with_description(callee, args, line, description, display, env)
    }

    fn call_value_with_description(
        &mut self,
        callee: LuaValue,
        args: Vec<LuaValue>,
        line: usize,
        description: Option<(String, String)>,
        display: Option<String>,
        env: &Rc<Scope>,
    ) -> Result<Vec<LuaValue>, LuaError> {
        self.set_line(line);
        let LuaValue::Function(function) = &callee else {
            // A table with a `__call` metamethod is callable in Lua.
            if let LuaValue::Table(table) = &callee {
                let metatable = table.borrow().metatable.clone();
                if let Some(LuaValue::Table(metatable)) = metatable {
                    let call = metatable.borrow().raw_get(&str_value("__call"));
                    if matches!(call, LuaValue::Function(_)) {
                        let mut call_args = vec![callee.clone()];
                        call_args.extend(args);
                        return self.call_value_with_description(
                            call,
                            call_args,
                            line,
                            description,
                            display,
                            env,
                        );
                    }
                }
            }
            let (suffix, trace_prefix) = if let Some((kind, name)) = description {
                (
                    format!(" ({} '{}')", kind, name),
                    vec![format!("[C]: in {} '{}'", kind, name)],
                )
            } else {
                (String::new(), vec!["[C]: in ?".to_string()])
            };
            return Err(self.error_at(
                line,
                &format!(
                    "attempt to call a {} value{}",
                    callee.type_name(),
                    suffix
                ),
                trace_prefix,
            ));
        };

        match &function.kind {
            FunctionKind::Builtin { name, func } => {
                let display_name = display.unwrap_or_else(|| name.clone());
                let chunk = self.current_chunk();
                let scope_id = self
                    .frames
                    .last()
                    .map(|frame| frame.function_scope_id)
                    .unwrap_or(0);
                self.frames.push(Frame {
                    description: format!("[C]: in function '{}'", display_name),
                    chunk,
                    line,
                    function_scope_id: scope_id,
                    is_main: false,
                });
                let result = func(self, args, line);
                self.frames.pop();
                result
            }
            FunctionKind::User { params, vararg, body, env: captured_env, chunk, def_line } => {
                let function_scope_id = self.allocate_id();
                let scope = Scope::new(Some(captured_env.clone()), function_scope_id);
                let mut varargs = Vec::new();
                for (index, parameter) in params.iter().enumerate() {
                    let value = args.get(index).cloned().unwrap_or(LuaValue::Nil);
                    scope.define(parameter, value);
                }
                if *vararg {
                    varargs = args.iter().skip(params.len()).cloned().collect();
                }
                let name = display.clone();
                self.frames.push(Frame {
                    description: if let Some(name) = name {
                        format!("{}:{{line}}: in function '{}'", chunk, name)
                    } else {
                        format!("{}:{{line}}: in function <{}:{}>", chunk, chunk, def_line)
                    },
                    chunk: chunk.clone(),
                    line: *def_line,
                    function_scope_id,
                    is_main: false,
                });
                let body_clone = body.clone();
                let result = self.execute_block(&body_clone, &scope, &varargs);
                self.frames.pop();
                match result? {
                    Flow::Return(values) => Ok(values),
                    _ => Ok(Vec::new()),
                }
            }
            FunctionKind::NextIterator { table } => {
                let state = args.get(0).cloned().unwrap_or(LuaValue::Nil);
                let control = args.get(1).cloned().unwrap_or(LuaValue::Nil);
                let table_value = match &state {
                    LuaValue::Table(_) => state,
                    _ => table.clone(),
                };
                Ok(next_table_entry(&table_value, &control))
            }
            FunctionKind::IPairsIterator => {
                let table = args.get(0).cloned().unwrap_or(LuaValue::Nil);
                let index = int_value(&args.get(1).cloned().unwrap_or(LuaValue::Int(0)))
                    .unwrap_or(0)
                    + 1;
                let value = self.index_value_no_error(&table, LuaValue::Int(index));
                if matches!(value, LuaValue::Nil) {
                    Ok(vec![LuaValue::Nil])
                } else {
                    Ok(vec![LuaValue::Int(index), value])
                }
            }
            FunctionKind::GMatchIterator { text, pattern, position } => {
                let start = *position.borrow();
                match find_lua_pattern(text, pattern, start, false) {
                    Some(match_result) => {
                        *position.borrow_mut() = if match_result.end >= match_result.start {
                            match_result.end + 1
                        } else {
                            match_result.end + 2
                        };
                        if match_result.captures.is_empty() {
                            Ok(vec![bytes_value(
                                text[match_result.start..=match_result.end.min(text.len().saturating_sub(1))]
                                    .to_vec(),
                            )])
                        } else {
                            Ok(match_result
                                .captures
                                .iter()
                                .map(|capture| match capture {
                                    PatternCapture::Text(bytes) => bytes_value(bytes.clone()),
                                    PatternCapture::Position(position) => {
                                        LuaValue::Int((*position + 1) as i64)
                                    }
                                })
                                .collect())
                        }
                    }
                    None => Ok(vec![LuaValue::Nil]),
                }
            }
        }
    }

    fn index_value_no_error(&self, base: &LuaValue, key: LuaValue) -> LuaValue {
        match base {
            LuaValue::Table(table) => table.borrow().raw_get(&key),
            LuaValue::Str(_) => {
                if let LuaValue::Table(table) = self.get_global("string") {
                    table.borrow().raw_get(&key)
                } else {
                    LuaValue::Nil
                }
            }
            _ => LuaValue::Nil,
        }
    }

    fn evaluate_unary(
        &mut self,
        operator: &str,
        value: LuaValue,
        line: usize,
    ) -> Result<LuaValue, LuaError> {
        self.set_line(line);
        match operator {
            "not" => Ok(LuaValue::Bool(!value.is_truthy())),
            "#" => match &value {
                LuaValue::Str(text) => Ok(LuaValue::Int(text.len() as i64)),
                LuaValue::Table(table) => Ok(LuaValue::Int(table.borrow().length())),
                _ => Err(self.error_at(
                    line,
                    &format!("attempt to get length of a {} value", value.type_name()),
                    vec!["[C]: in metamethod 'len'".to_string()],
                )),
            },
            "-" => {
                match numeric_value(&value) {
                    Some(LuaNumber::Int(number)) => Ok(LuaValue::Int(number.wrapping_neg())),
                    Some(LuaNumber::Float(number)) => Ok(LuaValue::Float(-number)),
                    None => Err(self.error_at(
                        line,
                        &format!(
                            "attempt to perform arithmetic on a {} value",
                            value.type_name()
                        ),
                        vec!["[C]: in metamethod 'unm'".to_string()],
                    )),
                }
            }
            "~" => {
                match integer_value_coerced(&value) {
                    Some(number) => Ok(LuaValue::Int(!number)),
                    None => Err(self.error_at(
                        line,
                        &format!(
                            "attempt to perform bitwise operation on a {} value",
                            value.type_name()
                        ),
                        vec!["[C]: in metamethod 'bnot'".to_string()],
                    )),
                }
            }
            _ => Ok(LuaValue::Nil),
        }
    }

    fn evaluate_binary(
        &mut self,
        operator: &str,
        left: &Expr,
        right: &Expr,
        env: &Rc<Scope>,
        varargs: &[LuaValue],
        line: usize,
    ) -> Result<LuaValue, LuaError> {
        match operator {
            "and" => {
                let left_value = self.evaluate(left, env, varargs)?;
                if !left_value.is_truthy() {
                    return Ok(left_value);
                }
                return self.evaluate(right, env, varargs);
            }
            "or" => {
                let left_value = self.evaluate(left, env, varargs)?;
                if left_value.is_truthy() {
                    return Ok(left_value);
                }
                return self.evaluate(right, env, varargs);
            }
            _ => {}
        }

        let left_value = self.evaluate(left, env, varargs)?;
        let right_value = self.evaluate(right, env, varargs)?;
        self.set_line(line);

        match operator {
            "==" => return Ok(LuaValue::Bool(left_value.lua_equals(&right_value))),
            "~=" => return Ok(LuaValue::Bool(!left_value.lua_equals(&right_value))),
            "<" | "<=" => {
                return self.compare_values(operator, left_value, right_value, line);
            }
            ".." => {
                let left_text = concat_operand(&left_value);
                let right_text = concat_operand(&right_value);
                match (left_text, right_text) {
                    (Some(mut left), Some(right)) => {
                        left.extend_from_slice(&right);
                        return Ok(bytes_value(left));
                    }
                    _ => {
                        let invalid = if concat_operand(&left_value).is_none() {
                            &left_value
                        } else {
                            &right_value
                        };
                        return Err(self.error_at(
                            line,
                            &format!(
                                "attempt to concatenate a {} value",
                                invalid.type_name()
                            ),
                            vec!["[C]: in metamethod 'concat'".to_string()],
                        ));
                    }
                }
            }
            "&" | "|" | "~" | "<<" | ">>" => {
                return self.bitwise_operation(operator, left_value, right_value, line);
            }
            _ => {}
        }

        self.arithmetic_operation(operator, left_value, right_value, line)
    }

    fn compare_values(
        &self,
        operator: &str,
        left: LuaValue,
        right: LuaValue,
        line: usize,
    ) -> Result<LuaValue, LuaError> {
        let ordering = match (&left, &right) {
            (LuaValue::Int(a), LuaValue::Int(b)) => a.partial_cmp(b),
            (LuaValue::Int(a), LuaValue::Float(b)) => (*a as f64).partial_cmp(b),
            (LuaValue::Float(a), LuaValue::Int(b)) => a.partial_cmp(&(*b as f64)),
            (LuaValue::Float(a), LuaValue::Float(b)) => a.partial_cmp(b),
            (LuaValue::Str(a), LuaValue::Str(b)) => Some(a.cmp(b)),
            _ => None,
        };
        if let Some(ordering) = ordering {
            let result = match operator {
                "<" => ordering == std::cmp::Ordering::Less,
                "<=" => ordering != std::cmp::Ordering::Greater,
                _ => false,
            };
            return Ok(LuaValue::Bool(result));
        }
        let message = if left.type_name() == right.type_name() {
            format!("attempt to compare two {} values", left.type_name())
        } else {
            format!(
                "attempt to compare {} with {}",
                left.type_name(),
                right.type_name()
            )
        };
        Err(self.error_at(
            line,
            &message,
            vec![format!(
                "[C]: in metamethod '{}'",
                if operator == "<" { "lt" } else { "le" }
            )],
        ))
    }

    fn bitwise_operation(
        &self,
        operator: &str,
        left: LuaValue,
        right: LuaValue,
        line: usize,
    ) -> Result<LuaValue, LuaError> {
        let left_number = integer_value_coerced(&left);
        let right_number = integer_value_coerced(&right);
        if let (Some(left), Some(right)) = (left_number, right_number) {
            let result = match operator {
                "&" => left & right,
                "|" => left | right,
                "~" => left ^ right,
                "<<" => shift_left(left, right),
                ">>" => shift_right(left, right),
                _ => 0,
            };
            return Ok(LuaValue::Int(result));
        }
        let invalid = if left_number.is_none() { &left } else { &right };
        Err(self.error_at(
            line,
            &format!(
                "attempt to perform bitwise operation on a {} value",
                invalid.type_name()
            ),
            vec![format!(
                "[C]: in metamethod '{}'",
                match operator {
                    "&" => "band",
                    "|" => "bor",
                    "~" => "bxor",
                    "<<" => "shl",
                    _ => "shr",
                }
            )],
        ))
    }

    fn arithmetic_operation(
        &self,
        operator: &str,
        left: LuaValue,
        right: LuaValue,
        line: usize,
    ) -> Result<LuaValue, LuaError> {
        let left_number = numeric_value(&left);
        let right_number = numeric_value(&right);
        if let (Some(left_number), Some(right_number)) = (left_number, right_number) {
            return arithmetic_numbers(operator, left_number, right_number, self, line);
        }

        let method = match operator {
            "+" => "add",
            "-" => "sub",
            "*" => "mul",
            "/" => "div",
            "//" => "idiv",
            "%" => "mod",
            "^" => "pow",
            _ => "add",
        };
        // Lua reports a two-type message when a non-numeric string is mixed
        // with a number; otherwise it reports the offending operand.
        let both_named_types = matches!(left, LuaValue::Str(_))
            || matches!(right, LuaValue::Str(_));
        if both_named_types
            && !matches!(left, LuaValue::Table(_) | LuaValue::Function(_))
            && !matches!(right, LuaValue::Table(_) | LuaValue::Function(_))
            && !matches!(left, LuaValue::Nil)
            && !matches!(right, LuaValue::Nil)
        {
            let operation_name = match operator {
                "+" => "add",
                "-" => "subtract",
                "*" => "multiply",
                "/" | "//" => "divide",
                "%" => "modulo",
                "^" => "power",
                _ => "add",
            };
            return Err(self.error_at(
                line,
                &format!(
                    "attempt to {} a '{}' with a '{}'",
                    operation_name,
                    left.type_name(),
                    right.type_name()
                ),
                vec![format!("[C]: in metamethod '{}'", method)],
            ));
        }
        let invalid = if left_number.is_none() { &left } else { &right };
        Err(self.error_at(
            line,
            &format!(
                "attempt to perform arithmetic on a {} value",
                invalid.type_name()
            ),
            vec![format!("[C]: in metamethod '{}'", method)],
        ))
    }
}

fn current_function_scope(_lua: &Lua, env: &Rc<Scope>) -> u64 {
    env.function_id
}

fn call_display_name(
    function_expression: &Expr,
    method: &Option<String>,
    callee: &LuaValue,
) -> Option<String> {
    if let Some(method) = method {
        return Some(method.clone());
    }
    if let Some(path) = expression_path(function_expression) {
        return Some(path);
    }
    if let LuaValue::Function(function) = callee {
        if let FunctionKind::Builtin { name, .. } = &function.kind {
            return Some(name.clone());
        }
    }
    None
}

fn expression_path(expression: &Expr) -> Option<String> {
    match &expression.kind {
        ExprKind::Var(name) => Some(name.clone()),
        ExprKind::Index(base, key) => {
            if let ExprKind::Str(bytes) = &key.kind {
                let base_path = expression_path(base)?;
                Some(format!(
                    "{}.{}",
                    base_path,
                    String::from_utf8_lossy(bytes)
                ))
            } else {
                None
            }
        }
        ExprKind::Paren(inner) => expression_path(inner),
        _ => None,
    }
}

// ---------------------------------------------------------------------------
// Numeric helpers

#[derive(Clone, Copy)]
enum LuaNumber {
    Int(i64),
    Float(f64),
}

fn is_integral_f64(value: f64) -> bool {
    value.fract() == 0.0
        && value >= i64::MIN as f64
        && value <= i64::MAX as f64
}

fn int_value(value: &LuaValue) -> Option<i64> {
    match value {
        LuaValue::Int(number) => Some(*number),
        LuaValue::Float(number) if is_integral_f64(*number) => Some(*number as i64),
        _ => None,
    }
}

fn number_as_f64(value: &LuaValue) -> Option<f64> {
    match value {
        LuaValue::Int(number) => Some(*number as f64),
        LuaValue::Float(number) => Some(*number),
        LuaValue::Str(bytes) => match parse_lua_number_string(bytes)? {
            LuaValue::Int(number) => Some(number as f64),
            LuaValue::Float(number) => Some(number),
            _ => None,
        },
        _ => None,
    }
}

fn numeric_value(value: &LuaValue) -> Option<LuaNumber> {
    match value {
        LuaValue::Int(number) => Some(LuaNumber::Int(*number)),
        LuaValue::Float(number) => Some(LuaNumber::Float(*number)),
        LuaValue::Str(bytes) => match parse_lua_number_string(bytes)? {
            LuaValue::Int(number) => Some(LuaNumber::Int(number)),
            LuaValue::Float(number) => Some(LuaNumber::Float(number)),
            _ => None,
        },
        _ => None,
    }
}

fn integer_value_coerced(value: &LuaValue) -> Option<i64> {
    match numeric_value(value)? {
        LuaNumber::Int(number) => Some(number),
        LuaNumber::Float(number) if is_integral_f64(number) => Some(number as i64),
        _ => None,
    }
}

fn arithmetic_numbers(
    operator: &str,
    left: LuaNumber,
    right: LuaNumber,
    lua: &Lua,
    line: usize,
) -> Result<LuaValue, LuaError> {
    if operator == "^" {
        let left = match left { LuaNumber::Int(v) => v as f64, LuaNumber::Float(v) => v };
        let right = match right { LuaNumber::Int(v) => v as f64, LuaNumber::Float(v) => v };
        return Ok(LuaValue::Float(left.powf(right)));
    }
    if operator == "/" {
        let left = match left { LuaNumber::Int(v) => v as f64, LuaNumber::Float(v) => v };
        let right = match right { LuaNumber::Int(v) => v as f64, LuaNumber::Float(v) => v };
        return Ok(LuaValue::Float(left / right));
    }
    match (left, right) {
        (LuaNumber::Int(a), LuaNumber::Int(b)) => {
            let value = match operator {
                "+" => a.wrapping_add(b),
                "-" => a.wrapping_sub(b),
                "*" => a.wrapping_mul(b),
                "//" => {
                    if b == 0 {
                        return Err(lua.error_at(
                            line,
                            "attempt to divide by zero",
                            vec!["[C]: in metamethod 'idiv'".to_string()],
                        ));
                    }
                    floor_div(a, b)
                }
                "%" => {
                    if b == 0 {
                        return Err(lua.error_at(
                            line,
                            "attempt to perform modulo by zero",
                            vec!["[C]: in metamethod 'mod'".to_string()],
                        ));
                    }
                    floor_mod(a, b)
                }
                _ => a,
            };
            Ok(LuaValue::Int(value))
        }
        _ => {
            let a = match left { LuaNumber::Int(v) => v as f64, LuaNumber::Float(v) => v };
            let b = match right { LuaNumber::Int(v) => v as f64, LuaNumber::Float(v) => v };
            let value = match operator {
                "+" => a + b,
                "-" => a - b,
                "*" => a * b,
                "//" => (a / b).floor(),
                "%" => a - (a / b).floor() * b,
                _ => a,
            };
            Ok(LuaValue::Float(value))
        }
    }
}

fn floor_div(a: i64, b: i64) -> i64 {
    let quotient = a.wrapping_div(b);
    if (a % b != 0) && ((a < 0) != (b < 0)) {
        quotient - 1
    } else {
        quotient
    }
}

fn floor_mod(a: i64, b: i64) -> i64 {
    let remainder = a.wrapping_rem(b);
    if remainder != 0 && ((remainder < 0) != (b < 0)) {
        remainder + b
    } else {
        remainder
    }
}

fn shift_left(value: i64, shift: i64) -> i64 {
    if shift < 0 {
        shift_right(value, -shift)
    } else if shift >= 64 {
        0
    } else {
        value << shift
    }
}

fn shift_right(value: i64, shift: i64) -> i64 {
    if shift < 0 {
        shift_left(value, -shift)
    } else if shift >= 64 {
        if value < 0 { -1 } else { 0 }
    } else {
        value >> shift
    }
}

fn concat_operand(value: &LuaValue) -> Option<Vec<u8>> {
    match value {
        LuaValue::Str(bytes) => Some((**bytes).clone()),
        LuaValue::Int(number) => Some(number.to_string().into_bytes()),
        LuaValue::Float(number) => Some(lua_float_to_string(*number).into_bytes()),
        _ => None,
    }
}

pub fn lua_float_to_string(value: f64) -> String {
    if value.is_nan() {
        return "nan".to_string();
    }
    if value.is_infinite() {
        return if value > 0.0 { "inf".to_string() } else { "-inf".to_string() };
    }
    if value == 0.0 {
        return if value.is_sign_negative() {
            "-0.0".to_string()
        } else {
            "0.0".to_string()
        };
    }
    // C's %.14g conversion.
    let scientific = format!("{:.13e}", value);
    let (mantissa, exponent_text) = scientific
        .split_once('e')
        .unwrap_or((scientific.as_str(), "0"));
    let exponent: i32 = exponent_text.parse().unwrap_or(0);
    let digits: String = mantissa.replace(['-', '.'], "");
    let sign = if value < 0.0 { "-" } else { "" };
    if (-4..14).contains(&exponent) {
        // Fixed notation.
        let result = if exponent >= 0 {
            let integer_digits = (exponent + 1) as usize;
            if digits.len() <= integer_digits {
                format!("{}{}.0", sign, pad_digits(&digits, integer_digits))
            } else {
                let (integer, fraction) = digits.split_at(integer_digits);
                let fraction = fraction.trim_end_matches('0');
                if fraction.is_empty() {
                    format!("{}{}.0", sign, integer)
                } else {
                    format!("{}{}.{}", sign, integer, fraction)
                }
            }
        } else {
            let zeros = "0".repeat((-exponent - 1) as usize);
            let fraction = format!("{}{}", zeros, digits).trim_end_matches('0').to_string();
            format!("{}0.{}", sign, fraction)
        };
        result
    } else {
        let mut mantissa_digits = digits.clone();
        while mantissa_digits.len() > 1 && mantissa_digits.ends_with('0') {
            mantissa_digits.pop();
        }
        let mantissa_text = if mantissa_digits.len() == 1 {
            mantissa_digits
        } else {
            format!(
                "{}.{}",
                &mantissa_digits[..1],
                &mantissa_digits[1..]
            )
        };
        format!(
            "{}{}e{:+03}",
            sign, mantissa_text, exponent
        )
    }
}

fn pad_digits(digits: &str, width: usize) -> String {
    let mut result = digits.to_string();
    while result.len() < width {
        result.push('0');
    }
    result
}
