}

fn optional_integer(
    lua: &Lua,
    line: usize,
    function: &str,
    args: &[LuaValue],
    index: usize,
    default: i64,
) -> Result<i64, LuaError> {
    if args.get(index - 1).is_none() || matches!(args.get(index - 1), Some(LuaValue::Nil)) {
