cat >> src/filter.rs <<'RS'

// ---------------------------------------------------------------------------
// Standard library helpers

fn caller_location(lua: &Lua) -> (String, usize) {
    // Frame stack: [..., caller, builtin]. Use the caller if present.
    if lua.frames.len() >= 2 {
        let frame = &lua.frames[lua.frames.len() - 2];
        (frame.chunk.clone(), frame.line)
    } else {
        (lua.current_chunk(), lua.current_line())
    }
}

fn bad_argument(
    lua: &Lua,
    line: usize,
    function: &str,
    index: usize,
    details: &str,
) -> LuaError {
    let (chunk, _) = caller_location(lua);
    let message = format!(
        "{}:{}: bad argument #{} to '{}' ({})",
        chunk, line, index, function, details
    );
    lua.runtime_error(message, vec!["[C]: in ?".to_string()])
}

fn got_description(value: Option<&LuaValue>) -> String {
    match value {
        None => "got no value".to_string(),
        Some(value) => format!("got {}", value.type_name()),
    }
}

fn bad_argument_type(
    lua: &Lua,
    line: usize,
    function: &str,
    index: usize,
    expected: &str,
    value: Option<&LuaValue>,
) -> LuaError {
    bad_argument(
        lua,
        line,
        function,
        index,
        &format!("{} expected, {}", expected, got_description(value)),
    )
}

fn require_value<'a>(
    lua: &Lua,
    line: usize,
    function: &str,
    args: &'a [LuaValue],
    index: usize,
) -> Result<&'a LuaValue, LuaError> {
    args.get(index - 1).ok_or_else(|| {
        bad_argument(lua, line, function, index, "value expected")
    })
}

fn coerce_string(
    lua: &Lua,
    line: usize,
    function: &str,
    args: &[LuaValue],
    index: usize,
) -> Result<Vec<u8>, LuaError> {
    let value = require_value(lua, line, function, args, index)?;
    match value {
        LuaValue::Str(bytes) => Ok((**bytes).clone()),
        LuaValue::Int(number) => Ok(number.to_string().into_bytes()),
        LuaValue::Float(number) => Ok(lua_float_to_string(*number).into_bytes()),
        _ => Err(bad_argument_type(
            lua,
            line,
            function,
            index,
            "string",
            Some(value),
        )),
    }
}

fn coerce_number(
    lua: &Lua,
    line: usize,
    function: &str,
    args: &[LuaValue],
    index: usize,
) -> Result<LuaValue, LuaError> {
    let value = require_value(lua, line, function, args, index)?;
    numeric_value(value).map(|_| match value {
        LuaValue::Str(bytes) => parse_lua_number_string(bytes).unwrap(),
        _ => value.clone(),
    }).ok_or_else(|| {
        bad_argument_type(lua, line, function, index, "number", Some(value))
    })
}

fn coerce_f64(
    lua: &Lua,
    line: usize,
    function: &str,
    args: &[LuaValue],
    index: usize,
) -> Result<f64, LuaError> {
    let value = coerce_number(lua, line, function, args, index)?;
    Ok(number_as_f64(&value).unwrap_or(0.0))
}

fn coerce_integer(
    lua: &Lua,
    line: usize,
    function: &str,
    args: &[LuaValue],
    index: usize,
) -> Result<i64, LuaError> {
    let value = require_value(lua, line, function, args, index)?;
    if let Some(number) = integer_value_coerced(value) {
        return Ok(number);
    }
    if numeric_value(value).is_some() {
        return Err(bad_argument(
            lua,
            line,
            function,
            index,
            "number has no integer representation",
        ));
    }
    Err(bad_argument_type(
        lua,
        line,
        function,
        index,
        "number",
        Some(value),
    ))
}

fn optional_integer(
    lua: &Lua,
    line: usize,
    function: &str,
    args: &[LuaValue],
    index: usize,
    default: i64,
) -> Result<i64, LuaError> {
    if args.get(index - 1).is_none() || matches!(args.get(index - 1), Some(LuaValue::Nil)) {
        Ok(default)
    } else {
        coerce_integer(lua, line, function, args, index)
    }
}

fn table_argument<'a>(
    lua: &Lua,
    line: usize,
    function: &str,
    args: &'a [LuaValue],
    index: usize,
) -> Result<&'a LuaValue, LuaError> {
    let value = require_value(lua, line, function, args, index)?;
    if matches!(value, LuaValue::Table(_)) {
        Ok(value)
    } else {
        Err(bad_argument_type(
            lua,
            line,
            function,
            index,
            "table",
            Some(value),
        ))
    }
}

fn value_to_string_for_format(value: &LuaValue, lua: &Lua) -> Vec<u8> {
    value.to_lua_string(lua)
}

fn install_standard_library(lua: &mut Lua) {
    // Global functions.
    let print_function = lua.builtin("print", builtin_print);
    lua.set_global("print", print_function);
    let tostring_function = lua.builtin("tostring", builtin_tostring);
    lua.set_global("tostring", tostring_function);
    let tonumber_function = lua.builtin("tonumber", builtin_tonumber);
    lua.set_global("tonumber", tonumber_function);
    let type_function = lua.builtin("type", builtin_type);
    lua.set_global("type", type_function);
    let error_function = lua.builtin("error", builtin_error);
    lua.set_global("error", error_function);
    let assert_function = lua.builtin("assert", builtin_assert);
    lua.set_global("assert", assert_function);
    let pcall_function = lua.builtin("pcall", builtin_pcall);
    lua.set_global("pcall", pcall_function);
    let xpcall_function = lua.builtin("xpcall", builtin_xpcall);
    lua.set_global("xpcall", xpcall_function);
    let next_function = lua.builtin("next", builtin_next);
    lua.set_global("next", next_function);
    let pairs_function = lua.builtin("pairs", builtin_pairs);
    lua.set_global("pairs", pairs_function);
    let ipairs_function = lua.builtin("ipairs", builtin_ipairs);
    lua.set_global("ipairs", ipairs_function);
    let select_function = lua.builtin("select", builtin_select);
    lua.set_global("select", select_function);
    let rawget_function = lua.builtin("rawget", builtin_rawget);
    lua.set_global("rawget", rawget_function);
    let rawset_function = lua.builtin("rawset", builtin_rawset);
    lua.set_global("rawset", rawset_function);
    let rawequal_function = lua.builtin("rawequal", builtin_rawequal);
    lua.set_global("rawequal", rawequal_function);
    let rawlen_function = lua.builtin("rawlen", builtin_rawlen);
    lua.set_global("rawlen", rawlen_function);
    let setmetatable_function = lua.builtin("setmetatable", builtin_setmetatable);
    lua.set_global("setmetatable", setmetatable_function);
    let getmetatable_function = lua.builtin("getmetatable", builtin_getmetatable);
    lua.set_global("getmetatable", getmetatable_function);

    install_string_library(lua);
    install_math_library(lua);
    install_table_library(lua);
    install_os_library(lua);
    install_io_library(lua);
    install_utf8_library(lua);
}

fn set_table_field(lua: &mut Lua, table: &LuaValue, name: &str, value: LuaValue) {
    if let LuaValue::Table(table) = table {
        table.borrow_mut().raw_set(str_value(name), value);
    }
}

fn install_string_library(lua: &mut Lua) {
    let table = lua.new_table();
    let functions: Vec<(&str, BuiltinFn)> = vec![
        ("len", builtin_string_len),
        ("sub", builtin_string_sub),
        ("upper", builtin_string_upper),
        ("lower", builtin_string_lower),
        ("reverse", builtin_string_reverse),
        ("byte", builtin_string_byte),
        ("char", builtin_string_char),
        ("find", builtin_string_find),
        ("match", builtin_string_match),
        ("gmatch", builtin_string_gmatch),
        ("gsub", builtin_string_gsub),
        ("format", builtin_string_format),
        ("rep", builtin_string_rep),
    ];
    for (name, function) in functions {
        let value = lua.builtin(name, function);
        set_table_field(lua, &table, name, value);
    }
    lua.set_global("string", table);
}

fn builtin_print(lua: &mut Lua, args: Vec<LuaValue>, _line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let mut output = Vec::new();
    for (index, value) in args.iter().enumerate() {
        if index > 0 {
            output.push(b'\t');
        }
        output.extend_from_slice(&value.to_lua_string(lua));
    }
    output.push(b'\n');
    use std::io::Write;
    let mut stdout = std::io::stdout().lock();
    let _ = stdout.write_all(&output);
    let _ = stdout.flush();
    Ok(Vec::new())
}

fn builtin_tostring(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let value = require_value(lua, line, "tostring", &args, 1)?.clone();
    // Honour a `__tostring` metamethod on tables.
    if let LuaValue::Table(table) = &value {
        if let Some(LuaValue::Table(metatable)) = &table.borrow().metatable {
            let method = metatable.borrow().raw_get(&str_value("__tostring"));
            if matches!(method, LuaValue::Function(_)) {
                return lua.call_value(method, vec![value], line, None, &Scope::new(None, 0));
            }
        }
    }
    Ok(vec![bytes_value(value.to_lua_string(lua))])
}

fn builtin_tonumber(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let value = require_value(lua, line, "tonumber", &args, 1)?.clone();
    if let Some(base_value) = args.get(1) {
        let base = coerce_integer(lua, line, "tonumber", &args, 2)?;
        if !(2..=36).contains(&base) {
            return Err(bad_argument(
                lua,
                line,
                "tonumber",
                2,
                "base out of range",
            ));
        }
        let text = match &value {
            LuaValue::Str(bytes) => bytes.clone(),
            _ => {
                return Err(bad_argument_type(
                    lua,
                    line,
                    "tonumber",
                    1,
                    "string",
                    Some(&value),
                ))
            }
        };
        let text = String::from_utf8_lossy(&text).trim().to_string();
        let (sign, digits) = if let Some(rest) = text.strip_prefix('-') {
            (-1i64, rest)
        } else if let Some(rest) = text.strip_prefix('+') {
            (1i64, rest)
        } else {
            (1i64, text.as_str())
        };
        return Ok(vec![
            i64::from_str_radix(digits, base as u32)
                .map(|number| LuaValue::Int(sign * number))
                .unwrap_or(LuaValue::Nil),
        ]);
    }
    let result = match &value {
        LuaValue::Int(_) | LuaValue::Float(_) => value,
        LuaValue::Str(bytes) => parse_lua_number_string(bytes).unwrap_or(LuaValue::Nil),
        _ => LuaValue::Nil,
    };
    let _ = base_value;
    Ok(vec![result])
}

fn builtin_type(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let value = require_value(lua, line, "type", &args, 1)?;
    Ok(vec![str_value(value.type_name())])
}

fn make_error_value(
    lua: &Lua,
    value: LuaValue,
    level_value: Option<&LuaValue>,
) -> LuaError {
    let level = level_value
        .and_then(|value| int_value(value))
        .unwrap_or(1);
    if let LuaValue::Str(bytes) = &value {
        let mut message = (**bytes).clone();
        if level > 0 {
            // Locate the frame `level` above this builtin.
            let frame_index = lua.frames.len().saturating_sub(1 + level as usize);
            if let Some(frame) = lua.frames.get(frame_index) {
                let location = format!("{}:{}: ", frame.chunk, frame.line).into_bytes();
                let mut located = location;
                located.extend_from_slice(&message);
                message = located;
            }
        }
        let message = String::from_utf8_lossy(&message).into_owned();
        lua.runtime_error(message, vec!["[C]: in ?".to_string()])
    } else {
        let message = value_to_string_for_format(&value, lua);
        let mut error = lua.runtime_error(
            String::from_utf8_lossy(&message).into_owned(),
            vec!["[C]: in ?".to_string()],
        );
        error.object = Some(value);
        error
    }
}

fn builtin_error(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let value = args.get(0).cloned().unwrap_or(LuaValue::Nil);
    if matches!(value, LuaValue::Nil) && args.is_empty() {
        // Lua's `error()` with no message still raises; mlua surfaces the
        // resulting payload as "nil" through the top-level conversion.
    }
    let _ = line;
    Err(make_error_value(lua, value, args.get(1)))
}

fn builtin_assert(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let condition = require_value(lua, line, "assert", &args, 1)?.clone();
    if condition.is_truthy() {
        return Ok(args);
    }
    if let Some(message) = args.get(1).cloned() {
        Err(make_error_value(lua, message, Some(&LuaValue::Int(1))))
    } else {
        let message = str_value("assertion failed!");
        Err(make_error_value(lua, message, Some(&LuaValue::Int(1))))
    }
}

fn error_result_value(error: &LuaError) -> LuaValue {
    if let Some(object) = &error.object {
        object.clone()
    } else {
        bytes_value(error.bare_message().into_bytes())
    }
}

fn builtin_pcall(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let function = require_value(lua, line, "pcall", &args, 1)?.clone();
    let call_args = args.iter().skip(1).cloned().collect::<Vec<_>>();
    match lua.call_value(function, call_args, line, None, &Scope::new(None, 0)) {
        Ok(mut values) => {
            let mut result = vec![LuaValue::Bool(true)];
            result.append(&mut values);
            Ok(result)
        }
        Err(error) => Ok(vec![LuaValue::Bool(false), error_result_value(&error)]),
    }
}

fn builtin_xpcall(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let function = require_value(lua, line, "xpcall", &args, 1)?.clone();
    let handler = args.get(1).cloned().unwrap_or(LuaValue::Nil);
    let call_args = args.iter().skip(2).cloned().collect::<Vec<_>>();
    match lua.call_value(function, call_args, line, None, &Scope::new(None, 0)) {
        Ok(mut values) => {
            let mut result = vec![LuaValue::Bool(true)];
            result.append(&mut values);
            Ok(result)
        }
        Err(error) => {
            let error_value = error_result_value(&error);
            let handled = lua.call_value(
                handler,
                vec![error_value],
                line,
                None,
                &Scope::new(None, 0),
            )?;
            let mut result = vec![LuaValue::Bool(false)];
            result.extend(handled);
            Ok(result)
        }
    }
}

fn next_table_entry(table: &LuaValue, control: &LuaValue) -> Vec<LuaValue> {
    let LuaValue::Table(table) = table else {
        return vec![LuaValue::Nil];
    };
    let table = table.borrow();
    if matches!(control, LuaValue::Nil) {
        if let Some((key, value)) = table.entries.first() {
            return vec![key_to_value(key), value.clone()];
        }
        return vec![LuaValue::Nil];
    }
    let Some(control_key) = control.table_key() else {
        return vec![LuaValue::Nil];
    };
    let mut found = false;
    for (key, value) in &table.entries {
        if found {
            return vec![key_to_value(key), value.clone()];
        }
        if key == &control_key {
            found = true;
        }
    }
    vec![LuaValue::Nil]
}

fn key_to_value(key: &TableKey) -> LuaValue {
    match key {
        TableKey::Bool(value) => LuaValue::Bool(*value),
        TableKey::Int(value) => LuaValue::Int(*value),
        TableKey::Float(bits) => LuaValue::Float(f64::from_bits(*bits)),
        TableKey::Str(bytes) => bytes_value(bytes.clone()),
        TableKey::Table(_) | TableKey::Function(_) => LuaValue::Nil,
    }
}

fn builtin_next(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let table = table_argument(lua, line, "next", &args, 1)?.clone();
    let control = args.get(1).cloned().unwrap_or(LuaValue::Nil);
    if !matches!(control, LuaValue::Nil) {
        // Validate that the key exists, as Lua raises for an invalid key.
        let exists = if let LuaValue::Table(inner) = &table {
            control
                .table_key()
                .is_some_and(|key| inner.borrow().get_key(&key).is_some())
        } else {
            false
        };
        if !exists {
            return Err(lua.error_at(
                line,
                "invalid key to 'next'",
                vec!["[C]: in ?".to_string()],
            ));
        }
    }
    Ok(next_table_entry(&table, &control))
}

fn builtin_pairs(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let table = require_value(lua, line, "pairs", &args, 1)?.clone();
    if let LuaValue::Table(inner) = &table {
        if let Some(LuaValue::Table(metatable)) = &inner.borrow().metatable {
            let method = metatable.borrow().raw_get(&str_value("__pairs"));
            if matches!(method, LuaValue::Function(_)) {
                return lua.call_value(method, vec![table], line, None, &Scope::new(None, 0));
            }
        }
    }
    let next_function = lua.get_global("next");
    Ok(vec![next_function, table, LuaValue::Nil])
}

fn builtin_ipairs(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let table = require_value(lua, line, "ipairs", &args, 1)?.clone();
    let iterator = lua.make_function(FunctionKind::IPairsIterator);
    Ok(vec![iterator, table, LuaValue::Int(0)])
}

fn builtin_select(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let selector = require_value(lua, line, "select", &args, 1)?.clone();
    if let LuaValue::Str(bytes) = &selector {
        if &**bytes == b"#" {
            return Ok(vec![LuaValue::Int((args.len() - 1) as i64)]);
        }
    }
    let index = coerce_integer(lua, line, "select", &args, 1)?;
    let count = (args.len() - 1) as i64;
    let start = if index > 0 {
        index
    } else if index < 0 {
        count + index + 1
    } else {
        return Err(bad_argument(lua, line, "select", 1, "index out of range"));
    };
    if start < 1 {
        return Err(bad_argument(lua, line, "select", 1, "index out of range"));
    }
    Ok(args.iter().skip(start as usize).cloned().collect())
}

fn builtin_rawget(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let table = table_argument(lua, line, "rawget", &args, 1)?.clone();
    let key = require_value(lua, line, "rawget", &args, 2)?.clone();
    if let LuaValue::Table(table) = table {
        Ok(vec![table.borrow().raw_get(&key)])
    } else {
        Ok(vec![LuaValue::Nil])
    }
}

fn builtin_rawset(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let table = table_argument(lua, line, "rawset", &args, 1)?.clone();
    let key = require_value(lua, line, "rawset", &args, 2)?.clone();
    let value = require_value(lua, line, "rawset", &args, 3)?.clone();
    if let LuaValue::Table(inner) = &table {
        inner.borrow_mut().raw_set(key, value);
    }
    Ok(vec![table])
}

fn builtin_rawequal(_lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let _ = line;
    let first = args.get(0).cloned().unwrap_or(LuaValue::Nil);
    let second = args.get(1).cloned().unwrap_or(LuaValue::Nil);
    Ok(vec![LuaValue::Bool(first.lua_equals(&second))])
}

fn builtin_rawlen(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let value = require_value(lua, line, "rawlen", &args, 1)?;
    match value {
        LuaValue::Str(bytes) => Ok(vec![LuaValue::Int(bytes.len() as i64)]),
        LuaValue::Table(table) => Ok(vec![LuaValue::Int(table.borrow().length())]),
        _ => Err(bad_argument_type(
            lua,
            line,
            "rawlen",
            1,
            "table or string",
            Some(value),
        )),
    }
}

fn builtin_setmetatable(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let table = table_argument(lua, line, "setmetatable", &args, 1)?.clone();
    let metatable = args.get(1).cloned().unwrap_or(LuaValue::Nil);
    if let LuaValue::Table(inner) = &table {
        inner.borrow_mut().metatable = if matches!(metatable, LuaValue::Nil) {
            None
        } else {
            Some(metatable)
        };
    }
    Ok(vec![table])
}

fn builtin_getmetatable(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let value = require_value(lua, line, "getmetatable", &args, 1)?;
    if let LuaValue::Table(table) = value {
        if let Some(metatable) = &table.borrow().metatable {
            return Ok(vec![metatable.clone()]);
        }
    }
    Ok(vec![LuaValue::Nil])
}
