fn install_string_library(lua: &mut Lua) {
    let table = lua.new_table();
    let functions: Vec<(&str, BuiltinFn)> = vec![
        ("len", builtin_string_len),
        ("sub", builtin_string_sub),
        ("upper", builtin_string_upper),
        ("lower", builtin_string_lower),
        ("reverse", builtin_string_reverse),
        ("byte", builtin_string_byte),
