    }
}

fn parse_pattern_set(pattern: &[u8], start: usize) -> Result<(PatternMatcher, usize), String> {
    // start points at '['; returns matcher and index just past ']'.
    let mut index = start + 1;
    let mut negated = false;
    if pattern.get(index) == Some(&b'^') {
        negated = true;
        index += 1;
    }
    let mut items = Vec::new();
    let mut first = true;
    while index < pattern.len() {
        let byte = pattern[index];
        if byte == b']' && !first {
            return Ok((PatternMatcher::Set(negated, items), index + 1));
        }
        first = false;
        if byte == b'%' && index + 1 < pattern.len() {
            let code = pattern[index + 1];
            if code.is_ascii_alphanumeric() {
                items.push(PatternSetItem::Class(code, code.is_ascii_uppercase()));
            } else {
                items.push(PatternSetItem::Byte(code));
            }
            index += 2;
            continue;
        }
        if index + 2 < pattern.len()
            && pattern[index + 1] == b'-'
            && pattern[index + 2] != b']'
        {
            items.push(PatternSetItem::Range(byte, pattern[index + 2]));
            index += 3;
            continue;
        }
        items.push(PatternSetItem::Byte(byte));
        index += 1;
    }
    Err("malformed pattern (missing ']')".to_string())
}

fn parse_frontier_set(pattern: &[u8], start: usize) -> Result<(Vec<PatternSetItem>, bool, usize), String> {
    match parse_pattern_set(pattern, start)? {
        (PatternMatcher::Set(negated, items), next) => Ok((items, negated, next)),
        _ => Err("malformed pattern".to_string()),
    }
}

fn parse_pattern(pattern: &[u8]) -> Result<ParsedPattern, String> {
    let mut items = Vec::new();
    let mut index = 0usize;
    let mut anchored = false;
    let mut capture_count = 0usize;
    if pattern.get(index) == Some(&b'^') {
        anchored = true;
        index += 1;
    }
    while index < pattern.len() {
        let byte = pattern[index];
        match byte {
            b'(' => {
                if pattern.get(index + 1) == Some(&b')') {
                    items.push(PatternItem::CaptureStart(capture_count));
                    items.push(PatternItem::CaptureEnd);
                    capture_count += 1;
                    index += 2;
                } else {
                    items.push(PatternItem::CaptureStart(capture_count));
                    capture_count += 1;
                    index += 1;
                }
            }
            b')' => {
                items.push(PatternItem::CaptureEnd);
                index += 1;
            }
            b'$' if index + 1 == pattern.len() => {
                // Represented as a zero-width character item that only
                // matches at the end via a special matcher path.
                items.push(PatternItem::Character(
                    PatternMatcher::Byte(0),
                    PatternQuantifier::One,
                ));
                // Patch it to an end anchor marker using a dedicated encoding:
                // a Byte(0) preceded by this marker would be ambiguous, so
                // store it as a frontier with an empty set handled below.
                // Simpler: replace with Frontier that never advances and is
                // interpreted specially in matching by position? We instead
                // encode end anchors separately at the end of parsing.
                items.pop();
                items.push(PatternItem::Frontier(Vec::new(), false));
                index += 1;
            }
            b'%' => {
                if index + 1 >= pattern.len() {
                    return Err("malformed pattern (ends with '%')".to_string());
                }
                let code = pattern[index + 1];
                match code {
                    b'b' => {
                        if index + 3 >= pattern.len() {
                            return Err("malformed pattern (missing arguments to '%b')".to_string());
                        }
                        items.push(PatternItem::Balanced(pattern[index + 2], pattern[index + 3]));
                        index += 4;
                    }
                    b'f' => {
                        if pattern.get(index + 2) != Some(&b'[') {
                            return Err("missing '[' after '%f' in pattern".to_string());
                        }
                        let (set, negated, next) = parse_frontier_set(pattern, index + 2)?;
                        // Frontier is zero width; negated sets are encoded in
                        // the items themselves in this implementation.
                        let _ = negated;
                        items.push(PatternItem::Frontier(set, negated));
                        index = next;
                    }
                    b'1'..=b'9' => {
                        items.push(PatternItem::BackReference((code - b'1') as usize));
                        index += 2;
                    }
                    _ if code.is_ascii_alphanumeric() => {
                        let matcher = PatternMatcher::Class(code, code.is_ascii_uppercase());
                        let (matcher, next) = apply_quantifier(pattern, index + 2, matcher, &mut items)?;
                        let _ = matcher;
                        index = next;
                    }
                    _ => {
                        let matcher = PatternMatcher::Byte(code);
                        let (_, next) = apply_quantifier(pattern, index + 2, matcher, &mut items)?;
                        index = next;
                    }
                }
            }
            b'[' => {
                let (matcher, next) = parse_pattern_set(pattern, index)?;
                let (_, after) = apply_quantifier(pattern, next, matcher, &mut items)?;
                index = after;
            }
            b'.' => {
                let (_, next) = apply_quantifier(pattern, index + 1, PatternMatcher::Any, &mut items)?;
                index = next;
            }
            _ => {
                let (_, next) = apply_quantifier(pattern, index + 1, PatternMatcher::Byte(byte), &mut items)?;
                index = next;
            }
        }
    }
    Ok(ParsedPattern {
        anchored,
        items,
        capture_count,
    })
}

fn apply_quantifier(
    pattern: &[u8],
    index: usize,
    matcher: PatternMatcher,
    items: &mut Vec<PatternItem>,
) -> Result<(PatternMatcher, usize), String> {
    let (quantifier, next) = match pattern.get(index) {
        Some(b'*') => (PatternQuantifier::Greedy, index + 1),
        Some(b'+') => (PatternQuantifier::GreedyPlus, index + 1),
        Some(b'-') => (PatternQuantifier::Lazy, index + 1),
        Some(b'?') => (PatternQuantifier::Optional, index + 1),
        _ => (PatternQuantifier::One, index),
    };
    items.push(PatternItem::Character(matcher.clone(), quantifier));
    Ok((matcher, next))
}

#[derive(Clone)]
struct CaptureState {
    start: Option<usize>,
    end: Option<usize>,
    position_capture: bool,
}

fn match_items(
    items: &[PatternItem],
    item_index: usize,
    text: &[u8],
    position: usize,
    captures: &mut Vec<CaptureState>,
    pattern_end_anchor: bool,
) -> Option<usize> {
    if item_index >= items.len() {
        if pattern_end_anchor && position != text.len() {
            return None;
        }
        return Some(position);
    }
    match &items[item_index] {
        PatternItem::CaptureStart(id) => {
            let mut next_captures = captures.clone();
            if *id >= next_captures.len() {
                next_captures.resize_with(id + 1, || CaptureState {
                    start: None,
                    end: None,
                    position_capture: false,
                });
            }
            next_captures[*id].start = Some(position);
            next_captures[*id].end = None;
            // A start immediately followed by an end is a position capture.
            next_captures[*id].position_capture = matches!(
                items.get(item_index + 1),
                Some(PatternItem::CaptureEnd)
            ) && matches!(items.get(item_index.saturating_sub(1)), None)
                || matches!(items.get(item_index + 1), Some(PatternItem::CaptureEnd));
            if let Some(end) = match_items(items, item_index + 1, text, position, &mut next_captures, pattern_end_anchor) {
                *captures = next_captures;
                return Some(end);
            }
            None
        }
        PatternItem::CaptureEnd => {
            // Find the most recently opened capture.
            let mut next_captures = captures.clone();
            let open_index = next_captures
                .iter()
                .rposition(|capture| capture.start.is_some() && capture.end.is_none());
            if let Some(id) = open_index {
                next_captures[id].end = Some(position);
            }
            if let Some(end) = match_items(items, item_index + 1, text, position, &mut next_captures, pattern_end_anchor) {
                *captures = next_captures;
                return Some(end);
            }
            None
        }
        PatternItem::BackReference(id) => {
            let capture = captures.get(*id)?;
            let start = capture.start?;
            let end = capture.end?;
            let expected = &text[start..end];
            if text[position..].starts_with(expected) {
                match_items(
                    items,
                    item_index + 1,
                    text,
                    position + expected.len(),
                    captures,
                    pattern_end_anchor,
                )
            } else {
                None
            }
        }
        PatternItem::Balanced(open, close) => {
            if text.get(position) != Some(open) {
                return None;
            }
            let mut depth = 0usize;
            let mut index = position;
            while index < text.len() {
                if text[index] == *open {
                    depth += 1;
                } else if text[index] == *close {
                    depth -= 1;
                    if depth == 0 {
                        return match_items(
                            items,
                            item_index + 1,
                            text,
                            index + 1,
                            captures,
                            pattern_end_anchor,
                        );
                    }
                }
                index += 1;
            }
            None
        }
        PatternItem::Frontier(set, negated) => {
            if set.is_empty() && !*negated {
                // Encoding used for the `$` anchor.
                if position == text.len() {
                    return match_items(items, item_index + 1, text, position, captures, pattern_end_anchor);
                }
                return None;
            }
            let previous_matches = if position == 0 {
                false
            } else {
                set.iter().any(|item| set_item_matches(item, text[position - 1]))
            };
            let next_matches = if position >= text.len() {
                false
            } else {
                set.iter().any(|item| set_item_matches(item, text[position]))
            };
            let previous_matches = previous_matches != *negated && position != 0 || (position == 0 && *negated);
            let next_matches = next_matches != *negated;
            // Frontier requires previous outside the set and next inside it.
            let previous_inside = if position == 0 {
                false
            } else {
                set.iter().any(|item| set_item_matches(item, text[position - 1]))
            };
            let next_inside = if position >= text.len() {
                false
            } else {
                set.iter().any(|item| set_item_matches(item, text[position]))
            };
            let _ = (previous_matches, next_matches);
            if !previous_inside && next_inside {
                match_items(items, item_index + 1, text, position, captures, pattern_end_anchor)
            } else {
                None
            }
        }
        PatternItem::Character(matcher, quantifier) => {
            match quantifier {
                PatternQuantifier::One => {
                    if position < text.len() && matcher_matches(matcher, text[position]) {
                        match_items(items, item_index + 1, text, position + 1, captures, pattern_end_anchor)
                    } else {
                        None
                    }
                }
                PatternQuantifier::Optional => {
                    if position < text.len() && matcher_matches(matcher, text[position]) {
                        let mut attempt = captures.clone();
                        if let Some(end) = match_items(items, item_index + 1, text, position + 1, &mut attempt, pattern_end_anchor) {
                            *captures = attempt;
                            return Some(end);
                        }
                    }
                    match_items(items, item_index + 1, text, position, captures, pattern_end_anchor)
                }
                PatternQuantifier::Greedy | PatternQuantifier::GreedyPlus => {
                    let minimum = if *quantifier == PatternQuantifier::GreedyPlus { 1 } else { 0 };
                    let mut maximum = 0usize;
                    while position + maximum < text.len()
                        && matcher_matches(matcher, text[position + maximum])
                    {
                        maximum += 1;
                    }
                    let mut count = maximum;
                    loop {
                        if count >= minimum {
                            let mut attempt = captures.clone();
                            if let Some(end) = match_items(
                                items,
                                item_index + 1,
                                text,
                                position + count,
                                &mut attempt,
                                pattern_end_anchor,
                            ) {
                                *captures = attempt;
                                return Some(end);
                            }
                        }
                        if count == 0 {
                            break;
                        }
                        count -= 1;
                    }
                    None
                }
                PatternQuantifier::Lazy => {
                    let mut count = 0usize;
                    loop {
                        let mut attempt = captures.clone();
                        if let Some(end) = match_items(
                            items,
                            item_index + 1,
                            text,
                            position + count,
                            &mut attempt,
                            pattern_end_anchor,
                        ) {
                            *captures = attempt;
                            return Some(end);
                        }
                        if position + count < text.len()
                            && matcher_matches(matcher, text[position + count])
                        {
                            count += 1;
                        } else {
                            break;
                        }
                    }
                    None
                }
            }
        }
    }
}

fn pattern_match_at(
    parsed: &ParsedPattern,
    text: &[u8],
    start: usize,
) -> Option<PatternResult> {
    // The `$` anchor is encoded as an empty frontier at the end; match_items
    // handles it directly, so no separate flag is needed.
    let mut captures = vec![
        CaptureState { start: None, end: None, position_capture: false };
        parsed.capture_count
    ];
    // Mark empty captures `()` as position captures. Their start and end are
    // filled by the matcher; conversion below decides based on whether the
    // source pattern segment was empty, which the matcher encoded by setting
    // both to the same position and the flag during parsing of items.
    let end = match_items(&parsed.items, 0, text, start, &mut captures, false)?;
    let converted = captures
        .iter()
        .map(|capture| {
            if capture.position_capture {
                PatternCapture::Position(capture.start.unwrap_or(start))
            } else {
                match (capture.start, capture.end) {
                    (Some(capture_start), Some(capture_end)) => {
                        PatternCapture::Text(text[capture_start..capture_end].to_vec())
                    }
                    (Some(capture_start), None) => {
                        PatternCapture::Text(text[capture_start..end].to_vec())
                    }
                    _ => PatternCapture::Text(Vec::new()),
                }
            }
        })
        .collect();
    Some(PatternResult {
        start,
        end_exclusive: end,
        captures: converted,
    })
}

fn find_lua_pattern(
    text: &[u8],
    pattern: &[u8],
    start: usize,
    anchored_search: bool,
) -> Option<PatternResult> {
    let parsed = parse_pattern(pattern).ok()?;
    let mut position = start.min(text.len());
    loop {
        if let Some(result) = pattern_match_at(&parsed, text, position) {
            return Some(result);
        }
        if parsed.anchored || anchored_search || position >= text.len() {
            break;
        }
        position += 1;
    }
    None
}

fn pattern_error(lua: &Lua, line: usize, function: &str, message: String) -> LuaError {
    let _ = function;
    lua.error_at(line, &message, vec!["[C]: in ?".to_string()])
}

fn validate_pattern(lua: &Lua, line: usize, function: &str, pattern: &[u8]) -> Result<ParsedPattern, LuaError> {
    parse_pattern(pattern).map_err(|message| pattern_error(lua, line, function, message))
}

fn capture_values(result: &PatternResult) -> Vec<LuaValue> {
    result
        .captures
        .iter()
        .map(|capture| match capture {
            PatternCapture::Text(bytes) => bytes_value(bytes.clone()),
            PatternCapture::Position(position) => LuaValue::Int((*position + 1) as i64),
        })
        .collect()
}

fn initial_position(
    lua: &Lua,
    line: usize,
    function: &str,
    args: &[LuaValue],
    index: usize,
    text_len: usize,
) -> Result<usize, LuaError> {
    let init = optional_integer(lua, line, function, args, index, 1)?;
    if init > 0 {
        Ok((init as usize).saturating_sub(1).min(text_len))
    } else if init < 0 {
        let from_end = text_len as i64 + init;
        Ok(from_end.max(0) as usize)
    } else {
        Ok(0)
    }
}
