fn string_index(position: i64, length: usize) -> Option<usize> {
    let length = length as i64;
    let resolved = if position > 0 {
        position - 1
    } else if position < 0 {
        length + position
    } else {
        -1
    };
    if resolved < 0 || resolved > length {
        None
    } else {
        Some(resolved as usize)
    }
}

fn builtin_string_sub(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let text = coerce_string(lua, line, "sub", &args, 1)?;
    let start = coerce_integer(lua, line, "sub", &args, 2)?;
    let end = optional_integer(lua, line, "sub", &args, 3, -1)?;
    let length = text.len() as i64;
    let mut first = if start > 0 { start - 1 } else if start < 0 { length + start } else { -1 };
    let mut last = if end > 0 { end - 1 } else if end < 0 { length + end } else { -1 };
    if first < 0 { first = 0; }
    if last >= length { last = length - 1; }
    if first > last || first >= length || last < 0 {
        return Ok(vec![bytes_value(Vec::new())]);
    }
    Ok(vec![bytes_value(text[first as usize..=last as usize].to_vec())])
}

