        let number = coerce_integer(lua, line, "char", &args, index)?;
        if !(0..=255).contains(&number) {
            return Err(bad_argument(lua, line, "char", index, "value out of range"));
        }
        bytes.push(number as u8);
    }
    Ok(vec![bytes_value(bytes)])
}

fn builtin_string_find(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let text = coerce_string(lua, line, "find", &args, 1)?;
    let pattern = coerce_string(lua, line, "find", &args, 2)?;
    let start = initial_position(lua, line, "find", &args, 3, text.len())?;
    let plain = args.get(3).is_some_and(|value| value.is_truthy());
    if plain {
        if start > text.len() {
            return Ok(vec![LuaValue::Nil]);
        }
        let haystack = &text[start..];
        if let Some(position) = find_subslice(haystack, &pattern) {
            let found_start = start + position;
            return Ok(vec![
                LuaValue::Int((found_start + 1) as i64),
                LuaValue::Int((found_start + pattern.len()) as i64),
            ]);
        }
        return Ok(vec![LuaValue::Nil]);
    }
    validate_pattern(lua, line, "find", &pattern)?;
    match find_lua_pattern(&text, &pattern, start, false) {
        Some(result) => {
            let mut values = vec![
                LuaValue::Int((result.start + 1) as i64),
                LuaValue::Int(result.end_exclusive as i64),
            ];
            values.extend(capture_values(&result));
            Ok(values)
        }
        None => Ok(vec![LuaValue::Nil]),
    }
}

fn find_subslice(haystack: &[u8], needle: &[u8]) -> Option<usize> {
    if needle.is_empty() {
        return Some(0);
    }
    haystack
        .windows(needle.len())
        .position(|window| window == needle)
}

fn builtin_string_match(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let text = coerce_string(lua, line, "match", &args, 1)?;
    let pattern = coerce_string(lua, line, "match", &args, 2)?;
    let start = initial_position(lua, line, "match", &args, 3, text.len())?;
    validate_pattern(lua, line, "match", &pattern)?;
    match find_lua_pattern(&text, &pattern, start, false) {
        Some(result) => {
            if result.captures.is_empty() {
                Ok(vec![bytes_value(
                    text[result.start..result.end_exclusive].to_vec(),
                )])
            } else {
                Ok(capture_values(&result))
            }
        }
        None => Ok(vec![LuaValue::Nil]),
    }
}

fn builtin_string_gmatch(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let text = coerce_string(lua, line, "gmatch", &args, 1)?;
    let pattern = coerce_string(lua, line, "gmatch", &args, 2)?;
    validate_pattern(lua, line, "gmatch", &pattern)?;
    let iterator = lua.make_function(FunctionKind::GMatchIterator {
        text,
        pattern: String::from_utf8_lossy(&pattern).into_owned(),
        position: RefCell::new(0),
    });
    Ok(vec![iterator])
}

fn builtin_string_gsub(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let text = coerce_string(lua, line, "gsub", &args, 1)?;
    let pattern = coerce_string(lua, line, "gsub", &args, 2)?;
    let replacement = require_value(lua, line, "gsub", &args, 3)?.clone();
    let limit = optional_integer(lua, line, "gsub", &args, 4, i64::MAX)?;
    validate_pattern(lua, line, "gsub", &pattern)?;
    let parsed = parse_pattern(&pattern)
        .map_err(|message| pattern_error(lua, line, "gsub", message))?;

    let mut output = Vec::new();
    let mut position = 0usize;
    let mut count = 0i64;
    while position <= text.len() && count < limit {
        let Some(result) = pattern_match_at(&parsed, &text, position) else {
            if position < text.len() {
                output.push(text[position]);
                position += 1;
                continue;
            }
            break;
        };
        count += 1;
        let replacement_bytes = gsub_replacement(
            lua,
            &replacement,
            &text,
            &result,
            line,
        )?;
        if let Some(bytes) = replacement_bytes {
            output.extend_from_slice(&bytes);
        } else {
            output.extend_from_slice(&text[result.start..result.end_exclusive]);
        }
        if result.end_exclusive > result.start {
            position = result.end_exclusive;
        } else {
            if position < text.len() {
                output.push(text[position]);
            }
            position += 1;
        }
        if parsed.anchored {
            break;
        }
    }
    if position < text.len() && count < limit {
        // Any tail was already appended character by character except when the
        // loop stopped because the position reached the end.
    } else if position < text.len() {
        output.extend_from_slice(&text[position..]);
    }
    Ok(vec![bytes_value(output), LuaValue::Int(count)])
}

fn gsub_replacement(
    lua: &mut Lua,
    replacement: &LuaValue,
    text: &[u8],
    result: &PatternResult,
    line: usize,
) -> Result<Option<Vec<u8>>, LuaError> {
    match replacement {
        LuaValue::Str(template) => {
            let mut output = Vec::new();
            let mut index = 0usize;
            while index < template.len() {
                if template[index] == b'%' && index + 1 < template.len() {
                    let code = template[index + 1];
                    if code == b'%' {
                        output.push(b'%');
                    } else if code == b'0' {
                        output.extend_from_slice(&text[result.start..result.end_exclusive]);
                    } else if (b'1'..=b'9').contains(&code) {
                        let capture_index = (code - b'1') as usize;
                        match result.captures.get(capture_index) {
                            Some(PatternCapture::Text(bytes)) => output.extend_from_slice(bytes),
                            Some(PatternCapture::Position(position)) => {
                                output.extend_from_slice((position + 1).to_string().as_bytes())
                            }
                            None => {
                                return Err(lua.error_at(
                                    line,
                                    &format!("invalid capture index %{}", code as char),
                                    vec!["[C]: in ?".to_string()],
                                ))
                            }
                        }
                    } else {
                        output.push(code);
                    }
                    index += 2;
                } else {
                    output.push(template[index]);
                    index += 1;
                }
            }
            Ok(Some(output))
        }
        LuaValue::Table(table) => {
            let key = if let Some(capture) = result.captures.first() {
                match capture {
                    PatternCapture::Text(bytes) => bytes_value(bytes.clone()),
                    PatternCapture::Position(position) => LuaValue::Int((*position + 1) as i64),
                }
            } else {
                bytes_value(text[result.start..result.end_exclusive].to_vec())
            };
            let value = table.borrow().raw_get(&key);
            match value {
                LuaValue::Nil | LuaValue::Bool(false) => Ok(None),
                LuaValue::Str(bytes) => Ok(Some((*bytes).clone())),
                LuaValue::Int(number) => Ok(Some(number.to_string().into_bytes())),
                LuaValue::Float(number) => Ok(Some(lua_float_to_string(number).into_bytes())),
                _ => Ok(None),
            }
        }
        LuaValue::Function(_) => {
            let call_args = if result.captures.is_empty() {
                vec![bytes_value(text[result.start..result.end_exclusive].to_vec())]
            } else {
                capture_values(result)
            };
            let values = lua.call_value(
                replacement.clone(),
                call_args,
                line,
                None,
                &Scope::new(None, 0),
            )?;
            match values.get(0) {
                Some(LuaValue::Str(bytes)) => Ok(Some((**bytes).clone())),
                Some(LuaValue::Int(number)) => Ok(Some(number.to_string().into_bytes())),
                Some(LuaValue::Float(number)) => Ok(Some(lua_float_to_string(*number).into_bytes())),
                _ => Ok(None),
            }
        }
        LuaValue::Int(number) => Ok(Some(number.to_string().into_bytes())),
        LuaValue::Float(number) => Ok(Some(lua_float_to_string(*number).into_bytes())),
        _ => Ok(None),
    }
}

fn builtin_string_rep(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let text = coerce_string(lua, line, "rep", &args, 1)?;
    let count = coerce_integer(lua, line, "rep", &args, 2)?;
    let separator = if args.len() >= 3 {
        coerce_string(lua, line, "rep", &args, 3)?
    } else {
        Vec::new()
    };
    if count <= 0 {
        return Ok(vec![bytes_value(Vec::new())]);
    }
    let mut output = Vec::new();
    for index in 0..count {
        if index > 0 {
            output.extend_from_slice(&separator);
        }
        output.extend_from_slice(&text);
    }
    Ok(vec![bytes_value(output)])
}

fn builtin_string_format(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let format = coerce_string(lua, line, "format", &args, 1)?;
    let output = format_lua_string(lua, &format, &args[1..], line)?;
    Ok(vec![bytes_value(output)])
}

fn format_lua_string(
    lua: &mut Lua,
    format: &[u8],
    values: &[LuaValue],
    line: usize,
) -> Result<Vec<u8>, LuaError> {
    let mut output = Vec::new();
    let mut value_index = 0usize;
    let mut index = 0usize;
    while index < format.len() {
        if format[index] != b'%' {
            output.push(format[index]);
            index += 1;
            continue;
        }
        index += 1;
        if format.get(index) == Some(&b'%') {
            output.push(b'%');
            index += 1;
            continue;
        }
        let start_of_spec = index;
        let mut flags = String::new();
        while matches!(format.get(index), Some(b'-' | b'+' | b' ' | b'#' | b'0')) {
            flags.push(format[index] as char);
            index += 1;
        }
        let mut width: Option<usize> = None;
        if format.get(index) == Some(&b'*') {
            index += 1;
            let value = values.get(value_index).cloned().unwrap_or(LuaValue::Nil);
            value_index += 1;
            width = Some(int_value(&value).unwrap_or(0).max(0) as usize);
        } else {
            let mut digits = String::new();
            while format.get(index).is_some_and(|byte| byte.is_ascii_digit()) {
                digits.push(format[index] as char);
                index += 1;
            }
            if !digits.is_empty() {
                width = digits.parse::<usize>().ok();
            }
        }
        let mut precision: Option<usize> = None;
        if format.get(index) == Some(&b'.') {
            index += 1;
            if format.get(index) == Some(&b'*') {
                index += 1;
                let value = values.get(value_index).cloned().unwrap_or(LuaValue::Nil);
                value_index += 1;
                precision = Some(int_value(&value).unwrap_or(0).max(0) as usize);
            } else {
                let mut digits = String::new();
                while format.get(index).is_some_and(|byte| byte.is_ascii_digit()) {
                    digits.push(format[index] as char);
                    index += 1;
                }
                precision = Some(digits.parse::<usize>().unwrap_or(0));
            }
        }
        let Some(conversion) = format.get(index).copied() else {
            return Err(bad_argument(
                lua,
                line,
                "format",
                1,
                "invalid option '%' to 'format'",
            ));
        };
        index += 1;
        let argument_number = value_index + 2;
        let value = values.get(value_index).cloned();
        value_index += 1;
        let Some(value) = value else {
            return Err(bad_argument(
                lua,
                line,
                "format",
                argument_number,
                "value expected",
            ));
        };
        let _ = start_of_spec;
        let formatted = format_one_specifier(
            lua,
            line,
            conversion,
            &value,
            &flags,
            width,
            precision,
            argument_number,
        )?;
        output.extend_from_slice(&formatted);
    }
    Ok(output)
}

fn format_one_specifier(
    lua: &mut Lua,
    line: usize,
    conversion: u8,
    value: &LuaValue,
    flags: &str,
    width: Option<usize>,
    precision: Option<usize>,
    argument_number: usize,
) -> Result<Vec<u8>, LuaError> {
    let left_align = flags.contains('-');
    let zero_pad = flags.contains('0') && !left_align;
    let formatted: Vec<u8> = match conversion {
        b'd' | b'i' => {
            let number = match value {
                LuaValue::Int(number) => *number,
                LuaValue::Float(number) if is_integral_f64(*number) => *number as i64,
                LuaValue::Str(bytes) => match parse_lua_number_string(bytes) {
                    Some(LuaValue::Int(number)) => number,
                    Some(LuaValue::Float(number)) if is_integral_f64(number) => number as i64,
                    _ => {
                        return Err(bad_argument(
                            lua,
                            line,
                            "format",
                            argument_number,
                            &format!("number expected, got {}", value.type_name()),
                        ))
                    }
                },
                _ => {
                    return Err(bad_argument(
                        lua,
                        line,
                        "format",
                        argument_number,
                        &format!("number expected, got {}", value.type_name()),
                    ))
                }
            };
            let mut text = number.to_string();
            if let Some(precision) = precision {
                let negative = text.starts_with('-');
                let digits = if negative { &text[1..] } else { &text[..] };
                if digits.len() < precision {
                    text = format!(
                        "{}{}{}",
                        if negative { "-" } else { "" },
                        "0".repeat(precision - digits.len()),
                        digits
                    );
                }
            }
            if flags.contains('+') && !text.starts_with('-') {
                text = format!("+{}", text);
            } else if flags.contains(' ') && !text.starts_with('-') {
                text = format!(" {}", text);
            }
            text.into_bytes()
        }
        b'u' => {
            let number = integer_value_coerced(value).unwrap_or(0) as u64;
            number.to_string().into_bytes()
        }
        b'x' | b'X' | b'o' => {
            let number = integer_value_coerced(value).unwrap_or(0) as u64;
            let mut text = match conversion {
                b'x' => format!("{:x}", number),
                b'X' => format!("{:X}", number),
                _ => format!("{:o}", number),
            };
            if flags.contains('#') {
                text = match conversion {
                    b'x' => format!("0x{}", text),
                    b'X' => format!("0X{}", text),
                    _ => format!("0{}", text),
                };
            }
            text.into_bytes()
        }
        b'c' => {
            let number = integer_value_coerced(value).unwrap_or(0);
            vec![number as u8]
        }
        b's' => {
            let mut text = value.to_lua_string(lua);
            if let Some(precision) = precision {
                text.truncate(precision);
            }
            text
        }
        b'q' => lua_quote_string(value, lua),
        b'f' => {
            let number = number_as_f64(value).unwrap_or(0.0);
            let precision = precision.unwrap_or(6);
            format!("{:.*}", precision, number).into_bytes()
        }
        b'e' | b'E' => {
            let number = number_as_f64(value).unwrap_or(0.0);
            let precision = precision.unwrap_or(6);
            let mut text = format!("{:.*e}", precision, number);
            if conversion == b'E' {
                text = text.to_uppercase();
            }
            text.into_bytes()
        }
        b'g' | b'G' => {
            let number = number_as_f64(value).unwrap_or(0.0);
            let mut text = if let Some(precision) = precision {
                format_c_g(number, precision.max(1))
            } else {
                format_c_g(number, 6)
            };
            if conversion == b'G' {
                text = text.to_uppercase();
            }
            text.into_bytes()
        }
        _ => {
            return Err(bad_argument(
                lua,
                line,
                "format",
                argument_number,
                &format!("invalid option '%{}' to 'format'", conversion as char),
            ))
        }
    };

    if let Some(width) = width {
        if formatted.len() >= width {
            return Ok(formatted);
        }
        let padding = width - formatted.len();
        if left_align {
            let mut result = formatted;
            result.extend(std::iter::repeat(b' ').take(padding));
            Ok(result)
        } else if zero_pad && matches!(conversion, b'd' | b'i' | b'u' | b'x' | b'X' | b'o' | b'f' | b'e' | b'E' | b'g' | b'G') {
            // Keep a sign in front of zero padding.
            if formatted.first() == Some(&b'-')
                || formatted.first() == Some(&b'+')
                || formatted.first() == Some(&b' ')
            {
                let mut result = vec![formatted[0]];
                result.extend(std::iter::repeat(b'0').take(padding));
                result.extend_from_slice(&formatted[1..]);
                Ok(result)
            } else {
                let mut result = vec![b'0'; padding];
                result.extend_from_slice(&formatted);
                Ok(result)
            }
        } else {
            let mut result = vec![b' '; padding];
            result.extend_from_slice(&formatted);
            Ok(result)
        }
    } else {
        Ok(formatted)
    }
}

fn format_c_g(value: f64, precision: usize) -> String {
    if value == 0.0 {
        return "0".to_string();
    }
    let scientific = format!("{:.*e}", precision - 1, value);
    let (mantissa, exponent_text) = scientific.split_once('e').unwrap();
    let exponent: i32 = exponent_text.parse().unwrap_or(0);
    if exponent < -4 || exponent >= precision as i32 {
        let mantissa = mantissa.trim_end_matches('0').trim_end_matches('.');
        format!("{}e{:+03}", mantissa, exponent)
    } else {
        let decimals = (precision as i32 - 1 - exponent).max(0) as usize;
        let text = format!("{:.*}", decimals, value);
        text.trim_end_matches('0').trim_end_matches('.').to_string()
    }
}

fn lua_quote_string(value: &LuaValue, lua: &Lua) -> Vec<u8> {
    let text = value.to_lua_string(lua);
    let mut result = vec![b'"'];
    for byte in text {
        match byte {
            b'"' => result.extend_from_slice(b"\\\""),
            b'\\' => result.extend_from_slice(b"\\\\"),
            b'\n' => result.extend_from_slice(b"\\\n"),
            0..=31 | 127 => {
                result.extend_from_slice(format!("\\{}", byte).as_bytes());
            }
            _ => result.push(byte),
        }
    }
    result.push(b'"');
    result
}
