}

fn builtin_table_insert(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let table = table_argument(lua, line, "insert", &args, 1)?.clone();
    let LuaValue::Table(inner) = &table else { unreachable!() };
    let length = inner.borrow().length();
    match args.len() {
        2 => {
            let value = args[1].clone();
            inner.borrow_mut().raw_set(LuaValue::Int(length + 1), value);
        }
        _ => {
            let position = coerce_integer(lua, line, "insert", &args, 2)?;
            let value = require_value(lua, line, "insert", &args, 3)?.clone();
            if position < 1 || position > length + 1 {
                return Err(bad_argument(lua, line, "insert", 2, "position out of bounds"));
            }
            for index in (position..=length).rev() {
                let existing = inner.borrow().raw_get(&LuaValue::Int(index));
                inner.borrow_mut().raw_set(LuaValue::Int(index + 1), existing);
            }
            inner.borrow_mut().raw_set(LuaValue::Int(position), value);
        }
    }
    Ok(Vec::new())
}

fn builtin_table_remove(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let table = table_argument(lua, line, "remove", &args, 1)?.clone();
    let LuaValue::Table(inner) = &table else { unreachable!() };
    let length = inner.borrow().length();
    let position = optional_integer(lua, line, "remove", &args, 2, length)?;
    if length == 0 {
        return Ok(vec![LuaValue::Nil]);
    }
    if position < 1 || position > length {
        return Err(bad_argument(lua, line, "remove", 2, "position out of bounds"));
    }
    let removed = inner.borrow().raw_get(&LuaValue::Int(position));
    for index in position..length {
        let existing = inner.borrow().raw_get(&LuaValue::Int(index + 1));
        inner.borrow_mut().raw_set(LuaValue::Int(index), existing);
    }
    inner.borrow_mut().raw_set(LuaValue::Int(length), LuaValue::Nil);
    Ok(vec![removed])
}

fn builtin_table_concat(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let table = table_argument(lua, line, "concat", &args, 1)?.clone();
    let separator = if args.len() >= 2 {
        coerce_string(lua, line, "concat", &args, 2)?
    } else {
        Vec::new()
    };
    let LuaValue::Table(inner) = &table else { unreachable!() };
    let length = inner.borrow().length();
    let start = optional_integer(lua, line, "concat", &args, 3, 1)?;
    let end = optional_integer(lua, line, "concat", &args, 4, length)?;
    let mut output = Vec::new();
    for index in start..=end {
        if index > start {
            output.extend_from_slice(&separator);
        }
        let value = inner.borrow().raw_get(&LuaValue::Int(index));
        match &value {
            LuaValue::Str(bytes) => output.extend_from_slice(bytes),
            LuaValue::Int(number) => output.extend_from_slice(number.to_string().as_bytes()),
            LuaValue::Float(number) => output.extend_from_slice(lua_float_to_string(*number).as_bytes()),
            _ => {
                return Err(bad_argument(
                    lua,
                    line,
                    "concat",
                    1,
                    &format!("invalid value (at index {}) in table for 'concat'", index),
                ))
            }
        }
    }
    Ok(vec![bytes_value(output)])
}

fn builtin_table_sort(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let table = table_argument(lua, line, "sort", &args, 1)?.clone();
    let comparator = args.get(1).cloned();
    let LuaValue::Table(inner) = &table else { unreachable!() };
    let length = inner.borrow().length();
    let mut values = Vec::new();
    for index in 1..=length {
        values.push(inner.borrow().raw_get(&LuaValue::Int(index)));
    }
    // Insertion sort keeps this simple and stable enough for filter code.
    for index in 1..values.len() {
        let mut position = index;
        while position > 0 {
            let should_swap = if let Some(comparator) = &comparator {
                if matches!(comparator, LuaValue::Function(_)) {
                    let result = lua.call_value(
                        comparator.clone(),
                        vec![values[position].clone(), values[position - 1].clone()],
                        line,
                        None,
                        &Scope::new(None, 0),
                    )?;
                    result.get(0).is_some_and(|value| value.is_truthy())
                } else {
                    false
                }
            } else {
                lua.compare_values(
                    "<",
                    values[position].clone(),
                    values[position - 1].clone(),
                    line,
                )? == LuaValue::Bool(true)
            };
            if should_swap {
                values.swap(position, position - 1);
                position -= 1;
            } else {
                break;
            }
        }
    }
    for (index, value) in values.into_iter().enumerate() {
        inner.borrow_mut().raw_set(LuaValue::Int(index as i64 + 1), value);
    }
    Ok(Vec::new())
}

fn builtin_table_pack(lua: &mut Lua, args: Vec<LuaValue>, _line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let table = lua.new_table();
    if let LuaValue::Table(inner) = &table {
        for (index, value) in args.iter().enumerate() {
            inner.borrow_mut().raw_set(LuaValue::Int(index as i64 + 1), value.clone());
        }
        inner.borrow_mut().raw_set(str_value("n"), LuaValue::Int(args.len() as i64));
    }
    Ok(vec![table])
}

fn builtin_table_unpack(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let table = table_argument(lua, line, "unpack", &args, 1)?.clone();
    let LuaValue::Table(inner) = &table else { unreachable!() };
    let length = inner.borrow().length();
    let start = optional_integer(lua, line, "unpack", &args, 2, 1)?;
    let end = optional_integer(lua, line, "unpack", &args, 3, length)?;
    let mut values = Vec::new();
    for index in start..=end {
        values.push(inner.borrow().raw_get(&LuaValue::Int(index)));
    }
    Ok(values)
}

fn builtin_table_move(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let source = table_argument(lua, line, "move", &args, 1)?.clone();
    let start = coerce_integer(lua, line, "move", &args, 2)?;
    let end = coerce_integer(lua, line, "move", &args, 3)?;
    let target_position = coerce_integer(lua, line, "move", &args, 4)?;
    let target = if args.len() >= 5 {
        args[4].clone()
    } else {
        source.clone()
    };
    let LuaValue::Table(source_inner) = &source else { unreachable!() };
    let mut moved = Vec::new();
    for index in start..=end {
        moved.push(source_inner.borrow().raw_get(&LuaValue::Int(index)));
    }
    if let LuaValue::Table(target_inner) = &target {
        for (offset, value) in moved.into_iter().enumerate() {
            target_inner
                .borrow_mut()
                .raw_set(LuaValue::Int(target_position + offset as i64), value);
        }
    }
    Ok(vec![target])
}

// ---------------------------------------------------------------------------
// OS, IO and UTF-8 libraries

fn install_os_library(lua: &mut Lua) {
    let table = lua.new_table();
    let functions: Vec<(&str, BuiltinFn)> = vec![
        ("time", builtin_os_time),
        ("date", builtin_os_date),
        ("clock", builtin_os_clock),
        ("difftime", builtin_os_difftime),
        ("getenv", builtin_os_getenv),
        ("exit", builtin_os_exit),
    ];
    for (name, function) in functions {
        let value = lua.builtin(name, function);
        set_table_field(lua, &table, name, value);
    }
    lua.set_global("os", table);
}

fn builtin_os_time(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    if args.is_empty() || matches!(args[0], LuaValue::Nil) {
        let seconds = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|duration| duration.as_secs() as i64)
            .unwrap_or(0);
        return Ok(vec![LuaValue::Int(seconds)]);
    }
    let table = table_argument(lua, line, "time", &args, 1)?;
    if let LuaValue::Table(table) = table {
        let get = |name: &str, default: i64| {
            int_value(&table.borrow().raw_get(&str_value(name))).unwrap_or(default)
        };
        let year = get("year", 1970);
        let month = get("month", 1);
        let day = get("day", 1);
        let hour = get("hour", 12);
        let minute = get("min", 0);
        let second = get("sec", 0);
        if let Some(date) = chrono::NaiveDate::from_ymd_opt(year as i32, month as u32, day as u32) {
            if let Some(datetime) = date.and_hms_opt(hour as u32, minute as u32, second as u32) {
                return Ok(vec![LuaValue::Int(datetime.and_utc().timestamp())]);
            }
        }
    }
    Ok(vec![LuaValue::Nil])
}

fn builtin_os_date(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let mut format = if args.is_empty() {
        "%a %b %d %H:%M:%S %Y".to_string()
    } else {
        String::from_utf8_lossy(&coerce_string(lua, line, "date", &args, 1)?).into_owned()
    };
    let timestamp = if args.len() >= 2 {
        coerce_integer(lua, line, "date", &args, 2)?
    } else {
        SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|duration| duration.as_secs() as i64)
            .unwrap_or(0)
    };
    let utc = if let Some(stripped) = format.strip_prefix('!') {
        format = stripped.to_string();
        true
    } else {
        false
    };
    let Some(utc_datetime) = chrono::DateTime::from_timestamp(timestamp, 0) else {
        return Ok(vec![LuaValue::Nil]);
    };
    let datetime = if utc {
        utc_datetime
    } else {
        utc_datetime.with_timezone(&chrono::Local).into()
    };
    if format == "*t" {
        let table = lua.new_table();
        if let LuaValue::Table(inner) = &table {
            use chrono::{Datelike, Timelike};
            inner.borrow_mut().raw_set(str_value("year"), LuaValue::Int(datetime.year() as i64));
            inner.borrow_mut().raw_set(str_value("month"), LuaValue::Int(datetime.month() as i64));
            inner.borrow_mut().raw_set(str_value("day"), LuaValue::Int(datetime.day() as i64));
            inner.borrow_mut().raw_set(str_value("hour"), LuaValue::Int(datetime.hour() as i64));
            inner.borrow_mut().raw_set(str_value("min"), LuaValue::Int(datetime.minute() as i64));
            inner.borrow_mut().raw_set(str_value("sec"), LuaValue::Int(datetime.second() as i64));
            inner.borrow_mut().raw_set(
                str_value("wday"),
                LuaValue::Int(datetime.weekday().num_days_from_sunday() as i64 + 1),
            );
            inner.borrow_mut().raw_set(str_value("yday"), LuaValue::Int(datetime.ordinal() as i64));
            inner.borrow_mut().raw_set(str_value("isdst"), LuaValue::Bool(false));
        }
        return Ok(vec![table]);
    }
    Ok(vec![str_value(&datetime.format(&format).to_string())])
}

fn builtin_os_clock(lua: &mut Lua, _args: Vec<LuaValue>, _line: usize) -> Result<Vec<LuaValue>, LuaError> {
    Ok(vec![LuaValue::Float(lua.started.elapsed().as_secs_f64())])
}

fn builtin_os_difftime(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let first = coerce_f64(lua, line, "difftime", &args, 1)?;
    let second = optional_integer(lua, line, "difftime", &args, 2, 0)? as f64;
    Ok(vec![LuaValue::Float(first - second)])
}

fn builtin_os_getenv(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    if args.is_empty() {
        let table = lua.new_table();
        if let LuaValue::Table(inner) = &table {
            for (key, value) in std::env::vars_os() {
                inner.borrow_mut().raw_set(
                    bytes_value(key.to_string_lossy().into_owned().into_bytes()),
                    bytes_value(value.to_string_lossy().into_owned().into_bytes()),
                );
            }
        }
        return Ok(vec![table]);
    }
    let name = coerce_string(lua, line, "getenv", &args, 1)?;
    let name = String::from_utf8_lossy(&name).into_owned();
    match std::env::var_os(&name) {
        Some(value) => Ok(vec![bytes_value(value.to_string_lossy().into_owned().into_bytes())]),
        None => Ok(vec![LuaValue::Nil]),
    }
}

fn builtin_os_exit(_lua: &mut Lua, args: Vec<LuaValue>, _line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let code = match args.get(0) {
        Some(LuaValue::Bool(true)) | None => 0,
        Some(LuaValue::Bool(false)) => 1,
        Some(value) => int_value(value).unwrap_or(0) as i32,
    };
    std::process::exit(code);
}

fn install_io_library(lua: &mut Lua) {
    let table = lua.new_table();
    let write_function = lua.builtin("write", builtin_io_write);
    set_table_field(lua, &table, "write", write_function.clone());
    let read_function = lua.builtin("read", builtin_io_read);
    set_table_field(lua, &table, "read", read_function);
    // A minimal stdout handle exposing `write`.
    let stdout = lua.new_table();
    set_table_field(lua, &stdout, "write", write_function);
    set_table_field(lua, &table, "stdout", stdout);
    lua.set_global("io", table);
}

fn builtin_io_write(_lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let mut output = Vec::new();
    for (index, value) in args.iter().enumerate() {
        match value {
            LuaValue::Str(bytes) => output.extend_from_slice(bytes),
            LuaValue::Int(number) => output.extend_from_slice(number.to_string().as_bytes()),
            LuaValue::Float(number) => output.extend_from_slice(lua_float_to_string(*number).as_bytes()),
            _ => {
                let function = "write";
                return Err(bad_argument_type(
                    _lua,
                    line,
                    function,
                    index + 1,
                    "string",
                    Some(value),
                ));
            }
        }
    }
    deferred_lua_io(&output);
    Ok(Vec::new())
}

static DEFERRED_IO: std::sync::Mutex<Vec<u8>> = std::sync::Mutex::new(Vec::new());

fn deferred_lua_io(bytes: &[u8]) {
    if let Ok(mut buffer) = DEFERRED_IO.lock() {
        buffer.extend_from_slice(bytes);
    }
}

/// Flush output produced through Lua's `io.write`, whose C stdio stream is
/// buffered independently in the reference tool.
pub fn flush_deferred_lua_output() {
    use std::io::Write;
    if let Ok(mut buffer) = DEFERRED_IO.lock() {
        if !buffer.is_empty() {
            let mut stdout = std::io::stdout().lock();
            let _ = stdout.write_all(&buffer);
            let _ = stdout.flush();
            buffer.clear();
        }
    }
}

fn builtin_io_read(_lua: &mut Lua, _args: Vec<LuaValue>, _line: usize) -> Result<Vec<LuaValue>, LuaError> {
    // Reading from the same stream as the log reader is inherently stateful;
    // the interpreter does not consume it here.
    Ok(vec![LuaValue::Nil])
}

fn install_utf8_library(lua: &mut Lua) {
    let table = lua.new_table();
    let functions: Vec<(&str, BuiltinFn)> = vec![
        ("char", builtin_utf8_char),
        ("len", builtin_utf8_len),
        ("codepoint", builtin_utf8_codepoint),
        ("codes", builtin_utf8_codes),
        ("offset", builtin_utf8_offset),
    ];
    for (name, function) in functions {
        let value = lua.builtin(name, function);
        set_table_field(lua, &table, name, value);
    }
    set_table_field(lua, &table, "charpattern", bytes_value(vec![0x00, 0x7f, 0xc2, 0xf4]));
    lua.set_global("utf8", table);
}

fn utf8_chars(text: &[u8]) -> Vec<(usize, char)> {
    let text = String::from_utf8_lossy(text);
    text.char_indices()
        .map(|(index, c)| (index, c))
        .collect::<Vec<_>>()
        .into_iter()
        .map(|(index, c)| (index, c))
        .collect()
}

fn builtin_utf8_char(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let mut result = String::new();
    for index in 1..=args.len() {
        let number = coerce_integer(lua, line, "char", &args, index)?;
        let Some(c) = char::from_u32(number as u32) else {
            return Err(bad_argument(lua, line, "char", index, "value out of range"));
        };
        result.push(c);
    }
    Ok(vec![str_value(&result)])
}

fn builtin_utf8_len(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let text = coerce_string(lua, line, "len", &args, 1)?;
    Ok(vec![LuaValue::Int(utf8_chars(&text).len() as i64)])
}

fn builtin_utf8_codepoint(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let text = coerce_string(lua, line, "codepoint", &args, 1)?;
    let chars = utf8_chars(&text);
    let start = optional_integer(lua, line, "codepoint", &args, 2, 1)?;
    let end = optional_integer(lua, line, "codepoint", &args, 3, start)?;
    let mut values = Vec::new();
    for position in start..=end {
        if position >= 1 && (position as usize) <= chars.len() {
            values.push(LuaValue::Int(chars[(position - 1) as usize].1 as u32 as i64));
        }
    }
    Ok(values)
}

fn builtin_utf8_codes(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let text = coerce_string(lua, line, "codes", &args, 1)?;
    let iterator = lua.make_function(FunctionKind::GMatchIterator {
        text: Vec::new(),
        pattern: String::new(),
        position: RefCell::new(0),
    });
    // Returning the actual bytes as iterator state is not represented by the
    // generic iterator used for gmatch; filters rarely use utf8.codes. The
    // iterator itself is inert here.
    let _ = iterator;
    let function = lua.builtin("next", builtin_next);
    Ok(vec![function, bytes_value(text), LuaValue::Nil])
}

fn builtin_utf8_offset(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let text = coerce_string(lua, line, "offset", &args, 1)?;
    let count = coerce_integer(lua, line, "offset", &args, 2)?;
    let chars = utf8_chars(&text);
    if count == 0 {
        return Ok(vec![LuaValue::Int(1)]);
    }
    if count > 0 && (count as usize) <= chars.len() {
        return Ok(vec![LuaValue::Int((chars[(count - 1) as usize].0 + 1) as i64)]);
    }
    Ok(vec![LuaValue::Nil])
}
RS
"}

