fn math_unary(
    lua: &mut Lua,
    args: Vec<LuaValue>,
    line: usize,
    name: &'static str,
    operation: fn(f64) -> f64,
    integer_operation: Option<fn(i64) -> i64>,
) -> Result<Vec<LuaValue>, LuaError> {
