    if let (Some(integer), LuaValue::Int(number)) = (integer_operation, &value) {
        return Ok(vec![LuaValue::Int(integer(*number))]);
    }
    Ok(vec![LuaValue::Float(operation(
        number_as_f64(&value).unwrap_or(0.0),
    ))])
}

fn builtin_math_abs(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    math_unary(lua, args, line, "abs", f64::abs, Some(i64::wrapping_abs))
}
fn builtin_math_ceil(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let value = coerce_number(lua, line, "ceil", &args, 1)?;
    let number = number_as_f64(&value).unwrap_or(0.0).ceil();
    if is_integral_f64(number) {
        Ok(vec![LuaValue::Int(number as i64)])
    } else {
        Ok(vec![LuaValue::Float(number)])
    }
}
fn builtin_math_floor(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let value = coerce_number(lua, line, "floor", &args, 1)?;
    let number = number_as_f64(&value).unwrap_or(0.0).floor();
    if is_integral_f64(number) {
        Ok(vec![LuaValue::Int(number as i64)])
    } else {
        Ok(vec![LuaValue::Float(number)])
    }
}
fn builtin_math_sqrt(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    math_unary(lua, args, line, "sqrt", f64::sqrt, None)
}
fn builtin_math_exp(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    math_unary(lua, args, line, "exp", f64::exp, None)
}
fn builtin_math_log(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let value = coerce_f64(lua, line, "log", &args, 1)?;
    let result = if args.len() >= 2 {
        let base = coerce_f64(lua, line, "log", &args, 2)?;
        value.log(base)
    } else {
        value.ln()
    };
    Ok(vec![LuaValue::Float(result)])
}
fn builtin_math_sin(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> { math_unary(lua, args, line, "sin", f64::sin, None) }
fn builtin_math_cos(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> { math_unary(lua, args, line, "cos", f64::cos, None) }
fn builtin_math_tan(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> { math_unary(lua, args, line, "tan", f64::tan, None) }
fn builtin_math_asin(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> { math_unary(lua, args, line, "asin", f64::asin, None) }
fn builtin_math_acos(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> { math_unary(lua, args, line, "acos", f64::acos, None) }
fn builtin_math_atan(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let y = coerce_f64(lua, line, "atan", &args, 1)?;
    if args.len() >= 2 {
        let x = coerce_f64(lua, line, "atan", &args, 2)?;
        Ok(vec![LuaValue::Float(y.atan2(x))])
    } else {
        Ok(vec![LuaValue::Float(y.atan())])
    }
}
fn builtin_math_sinh(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> { math_unary(lua, args, line, "sinh", f64::sinh, None) }
fn builtin_math_cosh(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> { math_unary(lua, args, line, "cosh", f64::cosh, None) }
fn builtin_math_tanh(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> { math_unary(lua, args, line, "tanh", f64::tanh, None) }
fn builtin_math_deg(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> { math_unary(lua, args, line, "deg", f64::to_degrees, None) }
fn builtin_math_rad(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> { math_unary(lua, args, line, "rad", f64::to_radians, None) }

fn builtin_math_max(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    if args.is_empty() {
        return Err(bad_argument(lua, line, "max", 1, "value expected"));
    }
    let mut best = args[0].clone();
    for value in &args[1..] {
        if lua.compare_values("<", best.clone(), value.clone(), line)? == LuaValue::Bool(true) {
            best = value.clone();
        }
    }
    Ok(vec![best])
}

fn builtin_math_min(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    if args.is_empty() {
        return Err(bad_argument(lua, line, "min", 1, "value expected"));
    }
    let mut best = args[0].clone();
    for value in &args[1..] {
        if lua.compare_values("<", value.clone(), best.clone(), line)? == LuaValue::Bool(true) {
            best = value.clone();
        }
    }
    Ok(vec![best])
}

fn builtin_math_fmod(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let first = require_value(lua, line, "fmod", &args, 1)?.clone();
    let second = require_value(lua, line, "fmod", &args, 2)?.clone();
    if let (LuaValue::Int(a), LuaValue::Int(b)) = (&first, &second) {
        if *b == 0 {
            return Err(lua.error_at(line, "attempt to perform modulo by zero", vec!["[C]: in ?".to_string()]));
        }
        return Ok(vec![LuaValue::Int(floor_mod(*a, *b))]);
    }
    let a = coerce_f64(lua, line, "fmod", &args, 1)?;
    let b = coerce_f64(lua, line, "fmod", &args, 2)?;
    Ok(vec![LuaValue::Float(a - (a / b).trunc() * b)])
}

fn builtin_math_modf(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let value = coerce_number(lua, line, "modf", &args, 1)?;
    let number = number_as_f64(&value).unwrap_or(0.0);
    let integer = number.trunc();
    let integer_value = if is_integral_f64(integer) {
        LuaValue::Int(integer as i64)
    } else {
        LuaValue::Float(integer)
    };
    Ok(vec![integer_value, LuaValue::Float(number - integer)])
}

fn next_random(lua: &mut Lua) -> u64 {
    // xorshift64*
    let mut value = lua.rng_state;
    value ^= value >> 12;
    value ^= value << 25;
    value ^= value >> 27;
    lua.rng_state = value;
    value.wrapping_mul(0x2545F4914F6CDD1D)
}

fn builtin_math_random(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    match args.len() {
        0 => {
            let value = next_random(lua);
            Ok(vec![LuaValue::Float(
                ((value >> 11) as f64) / ((1u64 << 53) as f64),
            )])
        }
        1 => {
            let upper = coerce_integer(lua, line, "random", &args, 1)?;
            if upper == 0 {
                return Ok(vec![LuaValue::Int(next_random(lua) as i64)]);
            }
            if upper < 0 {
                return Err(bad_argument(lua, line, "random", 1, "interval is empty"));
            }
            let value = next_random(lua);
            Ok(vec![LuaValue::Int(1 + (value % upper as u64) as i64)])
        }
        _ => {
            let lower = coerce_integer(lua, line, "random", &args, 1)?;
            let upper = coerce_integer(lua, line, "random", &args, 2)?;
            if upper < lower {
                return Err(bad_argument(lua, line, "random", 2, "interval is empty"));
            }
            let range = (upper as i128 - lower as i128 + 1) as u64;
            let value = next_random(lua);
            Ok(vec![LuaValue::Int(
                (lower as i128 + (value % range) as i128) as i64,
            )])
        }
    }
}

fn builtin_math_randomseed(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let seed = coerce_integer(lua, line, "randomseed", &args, 1)?;
    lua.rng_state = (seed as u64) ^ 0x9e37_79b9_7f4a_7c15;
    if lua.rng_state == 0 {
        lua.rng_state = 0x1234_5678_9abc_def1;
    }
    Ok(Vec::new())
}

fn builtin_math_tointeger(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let value = require_value(lua, line, "tointeger", &args, 1)?;
    Ok(vec![int_value(value).map(LuaValue::Int).unwrap_or(LuaValue::Nil)])
}

fn builtin_math_type(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let value = require_value(lua, line, "type", &args, 1)?;
    Ok(vec![match value {
        LuaValue::Int(_) => str_value("integer"),
        LuaValue::Float(_) => str_value("float"),
        _ => LuaValue::Nil,
    }])
