fn builtin_math_ult(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let first = coerce_integer(lua, line, "ult", &args, 1)? as u64;
    let second = coerce_integer(lua, line, "ult", &args, 2)? as u64;
    Ok(vec![LuaValue::Bool(first < second)])
