fn builtin_math_max(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    if args.is_empty() {
        return Err(bad_argument(lua, line, "max", 1, "value expected"));
    }
    let mut best = args[0].clone();
    for value in &args[1..] {
        if lua.compare_values("<", best.clone(), value.clone(), line)? == LuaValue::Bool(true) {
            best = value.clone();
        }
    }
    Ok(vec![best])
}

