fn builtin_math_fmod(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let first = require_value(lua, line, "fmod", &args, 1)?.clone();
    let second = require_value(lua, line, "fmod", &args, 2)?.clone();
    if let (LuaValue::Int(a), LuaValue::Int(b)) = (&first, &second) {
        if *b == 0 {
            return Err(lua.error_at(line, "attempt to perform modulo by zero", vec!["[C]: in ?".to_string()]));
        }
        return Ok(vec![LuaValue::Int(floor_mod(*a, *b))]);
    }
    let a = coerce_f64(lua, line, "fmod", &args, 1)?;
    let b = coerce_f64(lua, line, "fmod", &args, 2)?;
    Ok(vec![LuaValue::Float(a - (a / b).trunc() * b)])
}

fn builtin_math_modf(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let value = coerce_number(lua, line, "modf", &args, 1)?;
    let number = number_as_f64(&value).unwrap_or(0.0);
    let integer = number.trunc();
    let integer_value = if is_integral_f64(integer) {
        LuaValue::Int(integer as i64)
    } else {
        LuaValue::Float(integer)
    };
    Ok(vec![integer_value, LuaValue::Float(number - integer)])
}

fn next_random(lua: &mut Lua) -> u64 {
    // xorshift64*
    let mut value = lua.rng_state;
    value ^= value >> 12;
    value ^= value << 25;
    value ^= value >> 27;
    lua.rng_state = value;
    value.wrapping_mul(0x2545F4914F6CDD1D)
}

fn builtin_math_random(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    match args.len() {
        0 => {
            let value = next_random(lua);
            Ok(vec![LuaValue::Float(
                ((value >> 11) as f64) / ((1u64 << 53) as f64),
            )])
        }
        1 => {
            let upper = coerce_integer(lua, line, "random", &args, 1)?;
            if upper == 0 {
                return Ok(vec![LuaValue::Int(next_random(lua) as i64)]);
            }
            if upper < 0 {
                return Err(bad_argument(lua, line, "random", 1, "interval is empty"));
            }
            let value = next_random(lua);
            Ok(vec![LuaValue::Int(1 + (value % upper as u64) as i64)])
        }
        _ => {
            let lower = coerce_integer(lua, line, "random", &args, 1)?;
            let upper = coerce_integer(lua, line, "random", &args, 2)?;
            if upper < lower {
                return Err(bad_argument(lua, line, "random", 2, "interval is empty"));
            }
            let range = (upper as i128 - lower as i128 + 1) as u64;
            let value = next_random(lua);
            Ok(vec![LuaValue::Int(
                (lower as i128 + (value % range) as i128) as i64,
            )])
        }
    }
}

fn builtin_math_randomseed(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let seed = coerce_integer(lua, line, "randomseed", &args, 1)?;
    lua.rng_state = (seed as u64) ^ 0x9e37_79b9_7f4a_7c15;
    if lua.rng_state == 0 {
        lua.rng_state = 0x1234_5678_9abc_def1;
    }
    Ok(Vec::new())
}

fn builtin_math_tointeger(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
