//! A small Handlebars-compatible template engine.
//!
//! Only the features used by the log viewer are implemented: expressions,
//! inline and block helpers, the built-in `if`/`unless`/`each`/`with`/
//! `lookup`/`log` helpers, raw blocks, comments and the custom styling
//! helpers registered by the application.

use serde_json::{Map, Number, Value as JsonValue};
use std::collections::{BTreeMap, HashMap};
use std::fmt;

// ---------------------------------------------------------------------------
// Errors

#[derive(Clone)]
pub enum TemplateReason {
    InvalidSyntax(String),
    MismatchingClosedHelper(String, String),
}

impl fmt::Debug for TemplateReason {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            TemplateReason::InvalidSyntax(message) => {
                write!(f, "InvalidSyntax({:?})", message)
            }
            TemplateReason::MismatchingClosedHelper(expected, actual) => {
                write!(f, "MismatchingClosedHelper({:?}, {:?})", expected, actual)
            }
        }
    }
}

#[derive(Clone)]
pub struct TemplateError {
    pub reason: TemplateReason,
    pub template_name: String,
    pub line_no: usize,
    pub column_no: usize,
    pub segment: String,
}

impl fmt::Debug for TemplateError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "TemplateError {{ reason: {:?}, template_name: Some({:?}), line_no: Some({}), column_no: Some({}), segment: Some({:?}) }}",
            self.reason, self.template_name, self.line_no, self.column_no, self.segment
        )
    }
}

#[derive(Clone)]
pub struct RenderError {
    pub template_name: String,
    pub line: usize,
    pub column: usize,
    pub message: String,
}

impl fmt::Display for RenderError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "Error rendering {:?} line {}, col {}: {}",
            self.template_name, self.line, self.column, self.message
        )
