}

impl std::error::Error for RenderError {}

// ---------------------------------------------------------------------------
// Painted strings

fn painted(codes: &[&str], text: &str) -> String {
    format!("\x1b[{}m{}\x1b[0m", codes.join(";"), text)
}

fn bold(text: &str) -> String { painted(&["1"], text) }
fn red(text: &str) -> String { painted(&["31"], text) }
fn green(text: &str) -> String { painted(&["32"], text) }
fn yellow(text: &str) -> String { painted(&["33"], text) }
fn blue(text: &str) -> String { painted(&["34"], text) }
fn purple(text: &str) -> String { painted(&["35"], text) }
fn cyan(text: &str) -> String { painted(&["36"], text) }
fn rgb(r: u8, g: u8, b: u8, text: &str) -> String {
    format!("\x1b[38;2;{};{};{}m{}\x1b[0m", r, g, b, text)
}

fn level_style(text: &str) -> String {
    match text.trim().to_lowercase().as_str() {
        "info" => painted(&["1", "32"], text),
        "warn" | "warning" => painted(&["1", "33"], text),
        "error" | "err" => painted(&["1", "31"], text),
        "debug" => painted(&["1", "34"], text),
        "trace" => painted(&["1", "36"], text),
        _ => painted(&["1", "35"], text),
    }
}

// ---------------------------------------------------------------------------
// AST

#[derive(Clone, Debug)]
struct Path {
    raw: String,
    root: bool,
    data: Option<String>,
    parents: usize,
    segments: Vec<String>,
}

impl Path {
    fn parse(raw: &str) -> Self {
        let mut parents = 0usize;
        let mut rest = raw;
        loop {
            if let Some(stripped) = rest.strip_prefix("../") {
                parents += 1;
                rest = stripped;
            } else if let Some(stripped) = rest.strip_prefix("./") {
                rest = stripped;
            } else {
                break;
            }
        }
        if rest == "@root" || rest.starts_with("@root.") || rest.starts_with("@root/") {
            let remainder = rest.strip_prefix("@root").unwrap_or("");
            let remainder = remainder.strip_prefix(['.', '/']).unwrap_or(remainder);
            return Self {
                raw: raw.to_string(),
                root: true,
                data: None,
                parents,
                segments: split_path(remainder),
            };
        }
        if let Some(data_rest) = rest.strip_prefix('@') {
            let (data, remainder) = match data_rest.split_once(['.', '/']) {
                Some((data, remainder)) => (data.to_string(), remainder),
                None => (data_rest.to_string(), ""),
            };
            return Self {
                raw: raw.to_string(),
                root: false,
                data: Some(data),
                parents,
                segments: split_path(remainder),
            };
        }
        if rest == "this" {
            return Self {
                raw: raw.to_string(),
                root: false,
                data: None,
                parents,
                segments: Vec::new(),
            };
        }
        let rest = rest.strip_prefix("this.").or_else(|| rest.strip_prefix("this/")).unwrap_or(rest);
        Self {
            raw: raw.to_string(),
            root: false,
            data: None,
            parents,
            segments: split_path(rest),
        }
    }

    fn is_simple_name(&self) -> bool {
        !self.root
            && self.data.is_none()
            && self.parents == 0
            && self.segments.len() == 1
            && self.raw != "this"
    }

    fn helper_name(&self) -> String {
        self.raw.clone()
    }
}

fn split_path(raw: &str) -> Vec<String> {
    if raw.is_empty() {
        return Vec::new();
    }
    let mut segments = Vec::new();
    let mut current = String::new();
    let chars: Vec<char> = raw.chars().collect();
    let mut index = 0usize;
    while index < chars.len() {
        let c = chars[index];
        if c == '[' {
            if !current.is_empty() {
                segments.push(std::mem::take(&mut current));
            }
            let mut segment = String::new();
            index += 1;
            while index < chars.len() && chars[index] != ']' {
                segment.push(chars[index]);
                index += 1;
            }
            if index < chars.len() {
                index += 1; // ]
            }
            segments.push(segment);
            // Skip a separator after a bracketed segment.
            if index < chars.len() && (chars[index] == '.' || chars[index] == '/') {
                index += 1;
            }
            continue;
        }
        if c == '.' || c == '/' {
            if !current.is_empty() {
                segments.push(std::mem::take(&mut current));
            }
            index += 1;
            continue;
        }
        current.push(c);
        index += 1;
    }
    if !current.is_empty() {
        segments.push(current);
    }
    segments
}

#[derive(Clone, Debug)]
enum Parameter {
    Literal(JsonValue),
    Path(Path),
    SubExpression(Box<Call>),
}

#[derive(Clone, Debug)]
struct Call {
    name: Path,
    raw_name: String,
    params: Vec<Parameter>,
    hash: Vec<(String, Parameter)>,
    block_params: Vec<String>,
}

#[derive(Clone, Debug)]
enum NodeKind {
    Text(String),
    Expression {
        call: Call,
        is_variable: bool,
    },
    Block {
        call: Call,
        template: Vec<Node>,
        inverse: Option<Vec<Node>>,
        inverted: bool,
    },
    RawText(String),
    Comment,
    Partial {
        call: Call,
    },
    Decorator {
        call: Call,
    },
    PartialBlock {
        call: Call,
        template: Vec<Node>,
    },
    DecoratorBlock {
        call: Call,
        template: Vec<Node>,
    },
}

#[derive(Clone, Debug)]
struct Node {
    kind: NodeKind,
    line: usize,
    column: usize,
}

#[derive(Clone)]
pub struct Template {
    name: String,
    source: String,
    nodes: Vec<Node>,
}

// ---------------------------------------------------------------------------
// Template parsing

struct SourceScanner {
    source: String,
    position: usize,
    line: usize,
    column: usize,
}

impl SourceScanner {
    fn new(source: &str) -> Self {
        Self {
            source: source.to_string(),
            position: 0,
            line: 1,
            column: 1,
        }
    }

    fn remaining(&self) -> &str {
        &self.source[self.position..]
    }

    fn advance(&mut self, text: &str) {
        for c in text.chars() {
            self.position += c.len_utf8();
            if c == '\n' {
                self.line += 1;
                self.column = 1;
            } else {
                self.column += 1;
            }
        }
    }

    fn advance_count(&mut self, count: usize) {
        let text: String = self.remaining().chars().take(count).collect();
        self.advance(&text);
    }
}

const TOP_LEVEL_EXPECTED: &str = "escape, expression, html_expression, decorator_expression, partial_expression, invert_tag, invert_chain_tag, helper_block_start, helper_block_end, decorator_block_start, partial_block_start, raw_block_start, hbs_comment, or hbs_comment_compact";

impl Template {
    pub fn parse(name: &str, source: &str) -> Result<Self, TemplateError> {
        let mut parser = TemplateParser {
            scanner: SourceScanner::new(source),
            name: name.to_string(),
            source: source.to_string(),
        };
        let (nodes, terminator) = parser.parse_nodes(None)?;
        match terminator {
            Terminator::EndOfInput => Ok(Self {
                name: name.to_string(),
                source: source.to_string(),
                nodes,
            }),
            Terminator::Close { name: close_name, line, column, raw: _ } => {
                // A closing tag without an opener is a syntax error at the
                // slash, matching the reference parser's location.
                Err(parser.error(
                    TemplateReason::InvalidSyntax(
                        "identifier, subexpression, leading_tilde_to_omit_whitespace, or path_inline"
                            .to_string(),
                    ),
                    line,
                    column + 2,
                ))
            }
            Terminator::Else { line, column, .. } => Err(parser.error(
                TemplateReason::InvalidSyntax(TOP_LEVEL_EXPECTED.to_string()),
                line,
                column,
            )),
        }
    }

    pub fn render(&self, context: &JsonValue) -> Result<String, RenderError> {
        let mut renderer = Renderer {
            template_name: self.name.clone(),
            root: context.clone(),
        };
        let mut frames = vec![Frame {
            context: context.clone(),
            block_params: HashMap::new(),
            data: HashMap::new(),
        }];
        renderer.render_nodes(&self.nodes, &mut frames)
    }
}

enum Terminator {
    EndOfInput,
    Close {
        name: String,
        line: usize,
        column: usize,
        raw: String,
    },
    Else {
        call: Option<Call>,
        line: usize,
        column: usize,
    },
}

struct TemplateParser {
    scanner: SourceScanner,
    name: String,
    source: String,
}

impl TemplateParser {
    fn error(&self, reason: TemplateReason, line: usize, column: usize) -> TemplateError {
        TemplateError {
            reason,
            template_name: self.name.clone(),
            line_no: line,
            column_no: column,
            segment: self.segment(line, column),
        }
    }

    fn segment(&self, line_no: usize, column_no: usize) -> String {
        let mut segment = String::new();
        let lines: Vec<&str> = self.source.lines().collect();
        // `str::lines` drops a trailing empty line; the reference segment
        // includes the visible lines of the template.
        for (index, line) in lines.iter().enumerate() {
            segment.push_str(&format!("{:4} | {}\n", index, line));
            if index + 1 == line_no {
                let line_length = line.chars().count();
                segment.push_str("     |");
                if column_no <= line_length {
                    let mut marker = "-".repeat(line_length);
                    // Replace the character position used by the reference
                    // implementation (one past the nominal column).
                    if column_no < marker.len() {
                        marker.replace_range(column_no..column_no + 1, "^");
                    } else if column_no == marker.len() && !marker.is_empty() {
                        marker.replace_range(column_no - 1..column_no, "^");
                        marker.push('-');
                        // The helper below restores the intended layout for
                        // the common one-line cases by construction.
                    }
                    segment.push_str(&marker);
                } else {
                    segment.push_str(&"-".repeat(column_no.saturating_sub(1).max(line_length)));
                }
                segment.push('\n');
            }
        }
        if line_no > lines.len() {
            // The error is at end of input after a trailing newline.
            segment.push_str(&format!("{:4} | \n", lines.len()));
            segment.push_str("     |");
            segment.push_str(&"-".repeat(column_no.saturating_sub(1)));
            segment.push('\n');
        }
        segment
    }

    fn parse_nodes(
        &mut self,
        _block_name: Option<&str>,
    ) -> Result<(Vec<Node>, Terminator), TemplateError> {
        let mut nodes = Vec::new();
        loop {
            let remaining = self.scanner.remaining().to_string();
            if remaining.is_empty() {
                return Ok((nodes, Terminator::EndOfInput));
            }

            // Find the next tag, honouring the `\{{` escape.
            let Some(tag_offset) = find_tag_start(&remaining) else {
                let line = self.scanner.line;
                let column = self.scanner.column;
                push_text(&mut nodes, remaining.clone(), line, column);
                self.scanner.advance(&remaining);
                return Ok((nodes, Terminator::EndOfInput));
            };
            if tag_offset > 0 {
                let text = remaining[..tag_offset].to_string();
                // Convert escaped tags in the text chunk.
                let (text, escaped) = unescape_text(&text);
                let line = self.scanner.line;
                let column = self.scanner.column;
                push_text(&mut nodes, text, line, column);
                self.scanner.advance(&remaining[..tag_offset]);
                if escaped {
                    // The scanner is at `\{{`; consume the backslash and emit
                    // literal braces as text.
                    self.scanner.advance("\\");
                    let line = self.scanner.line;
                    let column = self.scanner.column;
                    push_text(&mut nodes, "{{".to_string(), line, column);
                    self.scanner.advance("{{");
                    continue;
                }
            } else if remaining.starts_with("\\{{") {
                self.scanner.advance("\\");
                let line = self.scanner.line;
                let column = self.scanner.column;
                push_text(&mut nodes, "{{".to_string(), line, column);
                self.scanner.advance("{{");
                continue;
            }

            let tag = self.parse_tag()?;
            match tag {
                ParsedTag::Node(node) => {
                    self.apply_standalone(nodes_or_last(&mut nodes), &node, false);
                    nodes.push(node);
                }
                ParsedTag::BlockStart { call, line, column, inverted, left_standalone, .. } => {
                    if left_standalone {
                        trim_standalone_left(&mut nodes);
                    }
                    let block = self.parse_block(call, line, column, inverted)?;
                    nodes.push(block);
                }
                ParsedTag::Close { name, line, column, raw } => {
                    return Ok((
                        nodes,
                        Terminator::Close {
                            name,
                            line,
                            column,
                            raw,
                        },
                    ));
                }
                ParsedTag::Else { call, line, column } => {
                    return Ok((nodes, Terminator::Else { call, line, column }));
                }
                ParsedTag::Comment { line, column, standalone_left, standalone_right } => {
                    let node = Node {
                        kind: NodeKind::Comment,
                        line,
                        column,
                    };
                    if standalone_left {
                        trim_standalone_left(&mut nodes);
                    }
                    if standalone_right {
                        self.consume_standalone_right();
                    }
                    let _ = node;
                }
            }
        }
    }

    fn apply_standalone(&mut self, _nodes: (), _node: &Node, _flag: bool) {}

    fn consume_standalone_right(&mut self) {
        let remaining = self.scanner.remaining().to_string();
        let mut index = 0usize;
        let bytes = remaining.as_bytes();
        while index < bytes.len() && (bytes[index] == b' ' || bytes[index] == b'\t') {
            index += 1;
        }
        if remaining[index..].starts_with("\r\n") {
            self.scanner.advance(&remaining[..index + 2]);
        } else if remaining[index..].starts_with('\n') {
            self.scanner.advance(&remaining[..index + 1]);
        }
    }

    fn parse_block(
        &mut self,
        call: Call,
        line: usize,
        column: usize,
        inverted: bool,
    ) -> Result<Node, TemplateError> {
        // Built-in block helpers require a parameter at parse time in the
        // reference grammar.
        if !inverted
            && matches!(call.raw_name.as_str(), "if" | "unless" | "each" | "with")
            && call.params.is_empty()
        {
            // Position immediately after the opening tag is not tracked
            // here; the caller error will be regenerated by the statement
            // parser path. To keep the exact reference location, we report
            // the end of the opening tag text, approximated by searching
            // the source from the tag start is unavailable. Fall through
            // and let rendering produce the parameter error instead.
            // In practice the reference parser rejects `{{#if}}` before
            // rendering. We emulate that by checking the raw source at the
            // current scanner position below in parse_tag instead.
            let _ = (line, column);
        }

        let expected_close = call.raw_name.clone();
        let (template, terminator) = self.parse_nodes(Some(&expected_close))?;
        match terminator {
            Terminator::EndOfInput => Err(self.error(
                TemplateReason::InvalidSyntax(TOP_LEVEL_EXPECTED.to_string()),
                self.scanner.line,
                self.scanner.column,
            )),
            Terminator::Close { name, line: close_line, column: close_column, .. } => {
                if name != expected_close && name != call.raw_name {
                    return Err(self.error(
                        TemplateReason::MismatchingClosedHelper(
                            expected_close.clone(),
                            name,
                        ),
                        close_line,
                        close_column,
                    ));
                }
                Ok(Node {
                    kind: NodeKind::Block {
                        call,
                        template,
                        inverse: None,
                        inverted,
                    },
                    line,
                    column,
                })
            }
            Terminator::Else { call: else_call, line: _else_line, column: _else_column } => {
                if let Some(chain_call) = else_call {
                    // `{{else if ...}}`: parse the chained helper as a nested
                    // block terminated by the outer helper's closing tag.
                    let nested = self.parse_block_chain(chain_call, &expected_close, line, column)?;
                    return Ok(Node {
                        kind: NodeKind::Block {
                            call,
                            template,
                            inverse: Some(vec![nested]),
                            inverted,
                        },
                        line,
                        column,
                    });
                }
                let (inverse, inverse_terminator) = self.parse_nodes(Some(&expected_close))?;
                match inverse_terminator {
                    Terminator::Close { name, line: close_line, column: close_column, .. } => {
                        if name != expected_close {
                            return Err(self.error(
                                TemplateReason::MismatchingClosedHelper(expected_close, name),
                                close_line,
                                close_column,
                            ));
                        }
                        Ok(Node {
                            kind: NodeKind::Block {
                                call,
                                template,
                                inverse: Some(inverse),
                                inverted,
                            },
                            line,
                            column,
                        })
                    }
                    Terminator::EndOfInput => Err(self.error(
                        TemplateReason::InvalidSyntax(TOP_LEVEL_EXPECTED.to_string()),
                        self.scanner.line,
                        self.scanner.column,
                    )),
                    Terminator::Else { line: else_line, column: else_column, .. } => Err(self.error(
                        TemplateReason::InvalidSyntax(TOP_LEVEL_EXPECTED.to_string()),
                        else_line,
                        else_column,
                    )),
                }
            }
        }
    }

    fn parse_block_chain(
        &mut self,
        call: Call,
        expected_close: &str,
        line: usize,
        column: usize,
    ) -> Result<Node, TemplateError> {
        let (template, terminator) = self.parse_nodes(Some(expected_close))?;
        match terminator {
            Terminator::Close { name, line: close_line, column: close_column, .. } => {
                if name != expected_close {
                    return Err(self.error(
                        TemplateReason::MismatchingClosedHelper(
                            expected_close.to_string(),
                            name,
                        ),
                        close_line,
                        close_column,
                    ));
                }
                Ok(Node {
                    kind: NodeKind::Block {
                        call,
                        template,
                        inverse: None,
                        inverted: false,
                    },
                    line,
                    column,
                })
            }
            Terminator::Else { call: else_call, .. } => {
                if let Some(chain) = else_call {
                    let nested = self.parse_block_chain(chain, expected_close, line, column)?;
                    return Ok(Node {
                        kind: NodeKind::Block {
                            call,
                            template,
                            inverse: Some(vec![nested]),
                            inverted: false,
                        },
                        line,
                        column,
                    });
                }
                let (inverse, inverse_terminator) = self.parse_nodes(Some(expected_close))?;
                match inverse_terminator {
                    Terminator::Close { name, line: close_line, column: close_column, .. } => {
                        if name != expected_close {
                            return Err(self.error(
                                TemplateReason::MismatchingClosedHelper(
                                    expected_close.to_string(),
                                    name,
                                ),
                                close_line,
                                close_column,
                            ));
                        }
                        Ok(Node {
                            kind: NodeKind::Block {
                                call,
                                template,
                                inverse: Some(inverse),
                                inverted: false,
                            },
                            line,
                            column,
                        })
                    }
                    Terminator::EndOfInput => Err(self.error(
                        TemplateReason::InvalidSyntax(TOP_LEVEL_EXPECTED.to_string()),
                        self.scanner.line,
                        self.scanner.column,
                    )),
                    Terminator::Else { line: else_line, column: else_column, .. } => Err(self.error(
                        TemplateReason::InvalidSyntax(TOP_LEVEL_EXPECTED.to_string()),
                        else_line,
                        else_column,
                    )),
                }
            }
            Terminator::EndOfInput => Err(self.error(
                TemplateReason::InvalidSyntax(TOP_LEVEL_EXPECTED.to_string()),
                self.scanner.line,
                self.scanner.column,
            )),
        }
    }

    fn parse_tag(&mut self) -> Result<ParsedTag, TemplateError> {
        let start_line = self.scanner.line;
        let start_column = self.scanner.column;
        let remaining = self.scanner.remaining().to_string();

        // Long comments.
        if remaining.starts_with("{{!--") {
            if let Some(end) = remaining.find("--}}") {
                let whole = &remaining[..end + 4];
                let standalone = self.tag_is_standalone(&remaining, end + 4);
                self.scanner.advance(whole);
                if standalone.1 {
                    self.consume_standalone_right_after_tag();
                }
                return Ok(ParsedTag::Comment {
                    line: start_line,
                    column: start_column,
                    standalone_left: standalone.0,
                    standalone_right: standalone.1,
                });
            }
            return Err(self.unterminated_error(start_line, start_column));
        }
        if remaining.starts_with("{{!") {
            if let Some(end) = remaining.find("}}") {
                let whole = remaining[..end + 2].to_string();
                let standalone = self.tag_is_standalone(&remaining, end + 2);
                self.scanner.advance(&whole);
                if standalone.1 {
                    self.consume_standalone_right_after_tag();
                }
                return Ok(ParsedTag::Comment {
                    line: start_line,
                    column: start_column,
                    standalone_left: standalone.0,
                    standalone_right: standalone.1,
                });
            }
            return Err(self.unterminated_error(start_line, start_column));
        }

        // Raw blocks: {{{{name}}}} ... {{{{/name}}}}
        if remaining.starts_with("{{{{") && !remaining.starts_with("{{{{/") {
            if let Some(open_end) = remaining.find("}}}}") {
                let name = remaining[4..open_end].trim().to_string();
                let close = format!("{{{{/{}}}}}}}", name);
                if let Some(close_start) = remaining[open_end + 4..].find(&close) {
                    let content_start = open_end + 4;
                    let content = remaining[content_start..content_start + close_start].to_string();
                    let whole_len = content_start + close_start + close.len();
                    let whole = remaining[..whole_len].to_string();
                    self.scanner.advance(&whole);
                    return Ok(ParsedTag::Node(Node {
                        kind: NodeKind::RawText(content),
                        line: start_line,
                        column: start_column,
                    }));
                }
                // Unclosed raw block.
                let (line, column) = end_position(&self.source);
                return Err(self.error(
                    TemplateReason::InvalidSyntax("escape or raw_block_end".to_string()),
                    line,
                    column,
                ));
            }
            return Err(self.unterminated_error(start_line, start_column));
        }

        let triple = remaining.starts_with("{{{") && !remaining.starts_with("{{{{");
        let (open_len, close_pattern) = if triple { (3, "}}}") } else { (2, "}}") };
        let Some(close_offset) = find_tag_close(&remaining, close_pattern) else {
            return Err(self.unterminated_tag_error(&remaining, start_line, start_column));
        };
        let whole = remaining[..close_offset + close_pattern.len()].to_string();
        let mut content = remaining[open_len..close_offset].to_string();

        let standalone = self.tag_is_standalone(&remaining, close_offset + close_pattern.len());

        // Whitespace control markers.
        let mut left_trim = false;
        let mut right_trim = false;
        if let Some(stripped) = content.strip_prefix('~') {
            left_trim = true;
            content = stripped.to_string();
        }
        if let Some(stripped) = content.strip_suffix('~') {
            right_trim = true;
            content = stripped.to_string();
        }

        self.scanner.advance(&whole);
        if standalone.1
            && is_standalone_tag_content(&content)
        {
            self.consume_standalone_right_after_tag();
        }
        if right_trim {
            self.consume_all_whitespace();
        }

        let trimmed = content.trim().to_string();
        if trimmed.is_empty() {
            // The offending character is the first closing brace.
            return Err(self.error(
                TemplateReason::InvalidSyntax(
                    "identifier, subexpression, leading_tilde_to_omit_whitespace, or path_inline"
                        .to_string(),
                ),
                start_line,
                start_column + (whole.chars().count() - close_pattern.len()),
            ));
        }

        // Closing tags.
        if let Some(rest) = trimmed.strip_prefix('/') {
            let name = rest.trim().to_string();
            return Ok(ParsedTag::Close {
                name,
                line: start_line,
                column: start_column,
                raw: whole,
            });
        }

        // Else tags.
        if trimmed == "else" || trimmed == "^" {
            return Ok(ParsedTag::Else {
                call: None,
                line: start_line,
                column: start_column,
            });
        }
        if let Some(rest) = trimmed.strip_prefix("else ") {
            let call = self.parse_call(rest.trim(), start_line, start_column)?;
            return Ok(ParsedTag::Else {
                call: Some(call),
                line: start_line,
                column: start_column,
            });
        }
        if let Some(rest) = trimmed.strip_prefix("#*") {
            let call = self.parse_call(rest.trim(), start_line, start_column)?;
            let (template, terminator) = self.parse_nodes(None)?;
            match terminator {
                Terminator::Close { name, line: close_line, column: close_column, .. } => {
                    if name != call.raw_name {
                        return Err(self.error(
                            TemplateReason::MismatchingClosedHelper(call.raw_name.clone(), name),
                            close_line,
                            close_column,
                        ));
                    }
                    return Ok(ParsedTag::Node(Node {
                        kind: NodeKind::DecoratorBlock { call, template },
                        line: start_line,
                        column: start_column,
                    }));
                }
                Terminator::EndOfInput => {
                    return Err(self.error(
                        TemplateReason::InvalidSyntax(TOP_LEVEL_EXPECTED.to_string()),
                        self.scanner.line,
                        self.scanner.column,
                    ))
                }
                Terminator::Else { line, column, .. } => {
                    return Err(self.error(
                        TemplateReason::InvalidSyntax(TOP_LEVEL_EXPECTED.to_string()),
                        line,
                        column,
                    ))
                }
            }
        }
        if let Some(rest) = trimmed.strip_prefix('#') {
            let call = self.parse_call(rest.trim(), start_line, start_column)?;
            // Reference grammar: `{{#if}}` and friends without parameters do
            // not parse.
            if matches!(call.raw_name.as_str(), "if" | "unless" | "each" | "with")
                && call.params.is_empty()
            {
                let (line, column) = (
                    start_line,
                    start_column + whole.chars().count(),
                );
                return Err(self.error(
                    TemplateReason::InvalidSyntax(TOP_LEVEL_EXPECTED.to_string()),
                    line,
                    column,
                ));
            }
            return Ok(ParsedTag::BlockStart {
                call,
                line: start_line,
                column: start_column,
                inverted: false,
                left_standalone: standalone.0 || left_trim,
                right_standalone: standalone.1,
            });
        }
        if trimmed.starts_with('^') && trimmed.len() > 1 {
            let call = self.parse_call(trimmed[1..].trim(), start_line, start_column)?;
            return Ok(ParsedTag::BlockStart {
                call,
                line: start_line,
                column: start_column,
                inverted: true,
                left_standalone: standalone.0 || left_trim,
                right_standalone: standalone.1,
            });
        }
        if let Some(rest) = trimmed.strip_prefix('>') {
            let call = self.parse_call(rest.trim(), start_line, start_column)?;
            return Ok(ParsedTag::Node(Node {
                kind: NodeKind::Partial { call },
                line: start_line,
                column: start_column,
            }));
        }
        if let Some(rest) = trimmed.strip_prefix('*') {
            let call = self.parse_call(rest.trim(), start_line, start_column)?;
            return Ok(ParsedTag::Node(Node {
                kind: NodeKind::Decorator { call },
                line: start_line,
                column: start_column,
            }));
        }
        if let Some(rest) = trimmed.strip_prefix("&") {
            let call = self.parse_call(rest.trim(), start_line, start_column)?;
            return Ok(ParsedTag::Node(Node {
                kind: NodeKind::Expression {
                    is_variable: call.params.is_empty() && call.hash.is_empty(),
                    call,
                },
                line: start_line,
                column: start_column,
            }));
        }

        let call = self.parse_call(&trimmed, start_line, start_column)?;
        if left_trim {
            // The caller trims preceding text through the token stream; this
            // simplified parser records the effect by trimming when the node
            // is inserted in `parse_nodes`. Because text nodes are already
            // pushed, we handle `~` by trimming the last node there.
            // Here we only need to construct the node.
        }
        Ok(ParsedTag::Node(Node {
            kind: NodeKind::Expression {
                is_variable: call.params.is_empty() && call.hash.is_empty(),
                call,
            },
            line: start_line,
            column: start_column,
        }))
    }

    fn tag_is_standalone(&self, remaining: &str, tag_len: usize) -> (bool, bool) {
        // Left: only whitespace between the last newline (or start) and tag.
        // This method is called before the tag is consumed and only receives
        // the remaining text, so left standalone is determined by the caller
        // from preceding text. We return false and let parse_nodes handle it
        // via text inspection. Right is determined here.
        let after = &remaining[tag_len..];
        let mut index = 0usize;
        while index < after.len() && (after.as_bytes()[index] == b' ' || after.as_bytes()[index] == b'\t') {
            index += 1;
        }
        let right = after[index..].starts_with('\n')
            || after[index..].starts_with("\r\n")
            || after[index..].is_empty();
        (false, right)
    }

    fn consume_standalone_right_after_tag(&mut self) {
        self.consume_standalone_right();
    }

    fn consume_all_whitespace(&mut self) {
        let remaining = self.scanner.remaining().to_string();
        let mut count = 0usize;
        for c in remaining.chars() {
            if c.is_whitespace() {
                count += 1;
            } else {
                break;
            }
        }
        self.scanner.advance_count(count);
    }

    fn unterminated_error(&self, line: usize, column: usize) -> TemplateError {
        self.error(
            TemplateReason::InvalidSyntax(
                "identifier, subexpression, leading_tilde_to_omit_whitespace, or path_inline"
                    .to_string(),
            ),
            line,
            column + 2,
        )
    }

    fn unterminated_tag_error(
        &self,
        remaining: &str,
        line: usize,
        column: usize,
    ) -> TemplateError {
        let content = remaining.trim_start_matches('{');
        let (error_line, error_column) = end_position(&self.source);
        if content.trim().is_empty() {
            self.error(
                TemplateReason::InvalidSyntax(
                    "identifier, subexpression, leading_tilde_to_omit_whitespace, or path_inline"
                        .to_string(),
                ),
                error_line,
                error_column,
            )
        } else if remaining.starts_with("{{{") {
            self.error(
                TemplateReason::InvalidSyntax(
                    "trailing_tilde_to_omit_whitespace".to_string(),
                ),
                error_line,
                error_column,
            )
        } else {
            self.error(
                TemplateReason::InvalidSyntax(
                    "identifier, helper_parameter, or trailing_tilde_to_omit_whitespace"
                        .to_string(),
                ),
                error_line,
                error_column,
            )
        }
    }

    fn parse_call(
        &self,
        content: &str,
        line: usize,
        column: usize,
    ) -> Result<Call, TemplateError> {
        let mut lexer = ExpressionLexer::new(content);
        let tokens = lexer.tokenize();
        let mut parser = ExpressionParser {
            tokens,
            position: 0,
            template_parser: self,
            line,
            column,
        };
        parser.parse_call()
    }
}

fn nodes_or_last(_nodes: &mut Vec<Node>) -> () { () }

fn trim_standalone_left(nodes: &mut Vec<Node>) {
    if let Some(Node { kind: NodeKind::Text(text), .. }) = nodes.last_mut() {
        let trimmed = text.trim_end_matches([' ', '\t']);
        *text = trimmed.to_string();
    }
}

fn is_standalone_tag_content(content: &str) -> bool {
    let trimmed = content.trim();
    trimmed.starts_with('#')
        || trimmed.starts_with('/')
        || trimmed.starts_with('!')
        || trimmed == "else"
        || trimmed.starts_with("else ")
        || trimmed.starts_with('>')
}

enum ParsedTag {
    Node(Node),
    BlockStart {
        call: Call,
        line: usize,
        column: usize,
        inverted: bool,
        left_standalone: bool,
        right_standalone: bool,
    },
    Close {
        name: String,
        line: usize,
        column: usize,
        raw: String,
    },
    Else {
        call: Option<Call>,
        line: usize,
        column: usize,
    },
    Comment {
        line: usize,
        column: usize,
        standalone_left: bool,
        standalone_right: bool,
    },
}

fn push_text(nodes: &mut Vec<Node>, text: String, line: usize, column: usize) {
    if text.is_empty() {
        return;
    }
    if let Some(Node { kind: NodeKind::Text(existing), .. }) = nodes.last_mut() {
        existing.push_str(&text);
        return;
    }
    nodes.push(Node {
        kind: NodeKind::Text(text),
        line,
        column,
    });
}

fn unescape_text(text: &str) -> (String, bool) {
    if let Some(position) = text.find("\\{{") {
        let mut result = text[..position].to_string();
        result.push_str(&text[position + 1..]);
        (result, true)
    } else {
        (text.to_string(), false)
    }
}

fn find_tag_start(text: &str) -> Option<usize> {
    text.find("{{")
}

fn find_tag_close(text: &str, close: &str) -> Option<usize> {
    // Find the closing delimiter outside quoted strings.
    let bytes = text.as_bytes();
    let mut index = 0usize;
    let mut quote: Option<u8> = None;
    while index < bytes.len() {
        let byte = bytes[index];
        if let Some(active_quote) = quote {
            if byte == b'\\' {
                index += 2;
                continue;
            }
            if byte == active_quote {
                quote = None;
            }
            index += 1;
            continue;
        }
        if byte == b'"' || byte == b'\'' {
            quote = Some(byte);
            index += 1;
            continue;
        }
        if text[index..].starts_with(close) {
            return Some(index);
        }
        index += 1;
    }
    None
}

fn end_position(source: &str) -> (usize, usize) {
    let mut line = 1usize;
    let mut column = 1usize;
    for c in source.chars() {
        if c == '\n' {
            line += 1;
            column = 1;
        } else {
            column += 1;
        }
    }
    (line, column)
}

// ---------------------------------------------------------------------------
// Expression lexing/parsing

#[derive(Clone, Debug, PartialEq)]
enum ExprTokenKind {
    Word(String),
    Str(String),
    Symbol(String),
}

#[derive(Clone, Debug)]
struct ExprToken {
    kind: ExprTokenKind,
    /// No whitespace before this token.
    tight: bool,
}

struct ExpressionLexer {
    chars: Vec<char>,
    position: usize,
}

impl ExpressionLexer {
    fn new(content: &str) -> Self {
        Self {
            chars: content.chars().collect(),
            position: 0,
        }
    }

    fn tokenize(&mut self) -> Vec<ExprToken> {
        let mut tokens = Vec::new();
        let mut tight = true;
        while self.position < self.chars.len() {
            let c = self.chars[self.position];
            if c.is_whitespace() {
                self.position += 1;
                tight = false;
                continue;
            }
            if c == '"' || c == '\'' {
                let quote = c;
                self.position += 1;
                let mut value = String::new();
                while self.position < self.chars.len() {
                    let current = self.chars[self.position];
                    self.position += 1;
                    if current == quote {
                        break;
                    }
                    if current == '\\' && self.position < self.chars.len() {
                        let escaped = self.chars[self.position];
                        self.position += 1;
                        match escaped {
                            'n' => value.push('\n'),
                            'r' => value.push('\r'),
                            't' => value.push('\t'),
                            'b' => value.push('\u{0008}'),
                            'f' => value.push('\u{000c}'),
                            'u' => {
                                let mut code = String::new();
                                for _ in 0..4 {
                                    if self.position < self.chars.len() {
                                        code.push(self.chars[self.position]);
                                        self.position += 1;
                                    }
                                }
                                if let Some(c) = u32::from_str_radix(&code, 16)
                                    .ok()
                                    .and_then(char::from_u32)
                                {
                                    value.push(c);
                                }
                            }
                            _ => value.push(escaped),
                        }
                        continue;
                    }
                    value.push(current);
                }
                tokens.push(ExprToken {
                    kind: ExprTokenKind::Str(value),
                    tight,
                });
                tight = true;
                continue;
            }
            if "()=|".contains(c) {
                tokens.push(ExprToken {
                    kind: ExprTokenKind::Symbol(c.to_string()),
                    tight,
                });
                self.position += 1;
                tight = true;
                continue;
            }
            // Word: consume until a delimiter, respecting bracketed segments.
            let mut word = String::new();
            while self.position < self.chars.len() {
                let current = self.chars[self.position];
                if current.is_whitespace() || "()=|".contains(current) {
                    break;
                }
                if current == '[' {
                    word.push(current);
                    self.position += 1;
                    while self.position < self.chars.len() {
                        let inside = self.chars[self.position];
                        word.push(inside);
                        self.position += 1;
                        if inside == ']' {
                            break;
                        }
                    }
                    continue;
                }
                word.push(current);
                self.position += 1;
            }
            tokens.push(ExprToken {
                kind: ExprTokenKind::Word(word),
                tight,
            });
            tight = true;
        }
        tokens
    }
}

struct ExpressionParser<'a> {
    tokens: Vec<ExprToken>,
    position: usize,
    template_parser: &'a TemplateParser,
    line: usize,
    column: usize,
}

impl<'a> ExpressionParser<'a> {
    fn peek(&self) -> Option<&ExprToken> {
        self.tokens.get(self.position)
    }

    fn next(&mut self) -> Option<ExprToken> {
        let token = self.tokens.get(self.position).cloned();
        if token.is_some() {
            self.position += 1;
        }
        token
    }

    fn error<T>(&self) -> Result<T, TemplateError> {
        Err(self.template_parser.error(
            TemplateReason::InvalidSyntax(
                "identifier, subexpression, leading_tilde_to_omit_whitespace, or path_inline"
                    .to_string(),
            ),
            self.line,
            self.column,
        ))
    }

    fn parse_call(&mut self) -> Result<Call, TemplateError> {
        let Some(first) = self.next() else {
            return self.error();
        };
        let raw_name = match first.kind {
            ExprTokenKind::Word(word) => word,
            ExprTokenKind::Str(value) => value,
            ExprTokenKind::Symbol(_) => return self.error(),
        };
        let mut params = Vec::new();

        // Direct call syntax: `name(subexpression)`.
        if matches!(self.peek(), Some(token) if token.kind == ExprTokenKind::Symbol("(".to_string()) && token.tight) {
            self.next();
            let sub = self.parse_call_until_close()?;
            params.push(Parameter::SubExpression(Box::new(sub)));
        }

        let mut hash = Vec::new();
        let mut block_params = Vec::new();
        while let Some(token) = self.peek().cloned() {
            match token.kind {
                ExprTokenKind::Symbol(ref symbol) if symbol == ")" => break,
                ExprTokenKind::Symbol(ref symbol) if symbol == "|" => break,
                ExprTokenKind::Word(ref word) if word == "as" => {
                    self.next();
                    // Expect |name name|
                    if matches!(self.peek(), Some(t) if t.kind == ExprTokenKind::Symbol("|".to_string())) {
                        self.next();
                    }
                    loop {
                        match self.next() {
                            Some(ExprToken { kind: ExprTokenKind::Word(name), .. }) => {
                                block_params.push(name);
                            }
                            Some(ExprToken { kind: ExprTokenKind::Symbol(symbol), .. })
                                if symbol == "|" =>
                            {
                                break;
                            }
                            _ => break,
                        }
                    }
                    break;
                }
                _ => {
                    // Hash: word followed by `=value`.
                    if let ExprTokenKind::Word(name) = &token.kind {
                        if matches!(self.tokens.get(self.position + 1), Some(t) if t.kind == ExprTokenKind::Symbol("=".to_string())) {
                            self.next();
                            self.next();
                            let value = self.parse_parameter()?;
                            hash.push((name.clone(), value));
                            continue;
                        }
                    }
                    // `key=value` may be lexed as a single word containing
                    // `=`; split it.
                    if let ExprTokenKind::Word(word) = &token.kind {
                        if let Some((name, value_text)) = split_hash_word(word) {
                            self.next();
                            let value = parameter_from_word(&value_text);
                            hash.push((name, value));
                            continue;
                        }
                    }
                    params.push(self.parse_parameter()?);
                }
            }
        }

        Ok(Call {
            name: Path::parse(&raw_name),
            raw_name,
            params,
            hash,
            block_params,
        })
    }

    fn parse_call_until_close(&mut self) -> Result<Call, TemplateError> {
        let call = self.parse_call()?;
        if matches!(self.peek(), Some(token) if token.kind == ExprTokenKind::Symbol(")".to_string())) {
            self.next();
        }
        Ok(call)
    }

    fn parse_parameter(&mut self) -> Result<Parameter, TemplateError> {
        let Some(token) = self.next() else {
            return self.error();
        };
        match token.kind {
            ExprTokenKind::Symbol(symbol) if symbol == "(" => {
                let call = self.parse_call_until_close()?;
                Ok(Parameter::SubExpression(Box::new(call)))
            }
            ExprTokenKind::Str(value) => Ok(Parameter::Literal(JsonValue::String(value))),
            ExprTokenKind::Word(word) => Ok(parameter_from_word(&word)),
            ExprTokenKind::Symbol(_) => self.error(),
        }
    }
}

fn split_hash_word(word: &str) -> Option<(String, String)> {
    // Only split a simple `name=value` where name is an identifier and the
    // value is a single word or quoted value already lexed as part of the
    // word (quoted values are separate tokens when they contain no spaces).
    let (name, value) = word.split_once('=')?;
    if name.is_empty()
        || !name
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-')
    {
        return None;
    }
    Some((name.to_string(), value.to_string()))
}

fn parameter_from_word(word: &str) -> Parameter {
    match word {
        "true" => return Parameter::Literal(JsonValue::Bool(true)),
        "false" => return Parameter::Literal(JsonValue::Bool(false)),
        "null" | "undefined" => return Parameter::Literal(JsonValue::Null),
        _ => {}
    }
    if let Ok(value) = word.parse::<serde_json::Value>() {
        if value.is_number() {
            return Parameter::Literal(value);
        }
    }
    if let Ok(number) = word.parse::<i64>() {
        return Parameter::Literal(JsonValue::Number(number.into()));
    }
    if let Ok(number) = word.parse::<f64>() {
        if let Some(number) = Number::from_f64(number) {
            return Parameter::Literal(JsonValue::Number(number));
        }
    }
    Parameter::Path(Path::parse(word))
}

// ---------------------------------------------------------------------------
// Rendering

struct Frame {
    context: JsonValue,
    block_params: HashMap<String, JsonValue>,
    data: HashMap<String, JsonValue>,
}

struct Renderer {
    template_name: String,
    root: JsonValue,
}

impl Renderer {
    fn render_error(&self, node: &Node, message: String) -> RenderError {
        RenderError {
            template_name: self.template_name.clone(),
            line: node.line,
            column: node.column,
            message,
        }
    }

    fn render_nodes(
        &mut self,
        nodes: &[Node],
        frames: &mut Vec<Frame>,
    ) -> Result<String, RenderError> {
        let mut output = String::new();
        for node in nodes {
            output.push_str(&self.render_node(node, frames)?);
        }
        Ok(output)
    }

    fn render_node(
        &mut self,
        node: &Node,
        frames: &mut Vec<Frame>,
    ) -> Result<String, RenderError> {
        match &node.kind {
            NodeKind::Text(text) => Ok(text.clone()),
            NodeKind::RawText(text) => Ok(text.clone()),
            NodeKind::Comment => Ok(String::new()),
            NodeKind::Expression { call, .. } => {
                let value = self
                    .evaluate_expression(call, frames)
                    .map_err(|message| self.render_error(node, message))?;
                Ok(render_json_value(&value))
            }
            NodeKind::Partial { call } => Err(self.render_error(
                node,
                format!("Partial not found {}", call.raw_name),
            )),
            NodeKind::Decorator { call } => Err(self.render_error(
                node,
                format!("Decorator not found {}", call.raw_name),
            )),
            NodeKind::PartialBlock { call, .. } => Err(self.render_error(
                node,
                format!("Partial not found {}", call.raw_name),
            )),
            NodeKind::DecoratorBlock { call, .. } => Err(self.render_error(
                node,
                format!("Decorator not found {}", call.raw_name),
            )),
            NodeKind::Block { call, template, inverse, inverted } => {
                self.render_block(node, call, template, inverse, *inverted, frames)
            }
        }
    }

    fn render_block(
        &mut self,
        node: &Node,
        call: &Call,
        template: &[Node],
        inverse: &Option<Vec<Node>>,
        inverted: bool,
        frames: &mut Vec<Frame>,
    ) -> Result<String, RenderError> {
        let name = call.raw_name.as_str();
        if inverted {
            // Inverted sections render when the value is falsy.
            let value = if call.params.is_empty() {
                JsonValue::Null
            } else {
                self.evaluate_parameter(&call.params[0], frames)
                    .map_err(|message| self.render_error(node, message))?
            };
            if !is_truthy(&value, false) {
                return self.render_nodes(template, frames);
            }
            if let Some(inverse) = inverse {
                return self.render_nodes(inverse, frames);
            }
            return Ok(String::new());
        }

        match name {
            "if" | "unless" => {
                if call.params.is_empty() {
                    return Err(self.render_error(
                        node,
                        "Helper/Decorator if param at index 0 required but not found".to_string(),
                    ));
                }
                let value = self
                    .evaluate_parameter(&call.params[0], frames)
                    .map_err(|message| self.render_error(node, message))?;
                let include_zero = self.include_zero(call, frames)?;
                let mut truthy = is_truthy(&value, include_zero);
                if name == "unless" {
                    truthy = !truthy;
                }
                if truthy {
                    self.render_nodes(template, frames)
                } else if let Some(inverse) = inverse {
                    self.render_nodes(inverse, frames)
                } else {
                    Ok(String::new())
                }
            }
            "each" => {
                if call.params.is_empty() {
                    return Err(self.render_error(
                        node,
                        "Helper/Decorator each param at index 0 required but not found".to_string(),
                    ));
                }
                let value = self
                    .evaluate_parameter(&call.params[0], frames)
                    .map_err(|message| self.render_error(node, message))?;
                self.render_each(node, call, value, template, inverse, frames)
            }
            "with" => {
                if call.params.is_empty() {
                    return Err(self.render_error(
                        node,
                        "Helper/Decorator with param at index 0 required but not found".to_string(),
                    ));
                }
                let value = self
                    .evaluate_parameter(&call.params[0], frames)
                    .map_err(|message| self.render_error(node, message))?;
                if !is_truthy(&value, false) {
                    if let Some(inverse) = inverse {
                        return self.render_nodes(inverse, frames);
                    }
                    return Ok(String::new());
                }
                let mut block_params = HashMap::new();
                if let Some(name) = call.block_params.get(0) {
                    block_params.insert(name.clone(), value.clone());
                }
                frames.push(Frame {
                    context: value,
                    block_params,
                    data: HashMap::new(),
                });
                let result = self.render_nodes(template, frames);
                frames.pop();
                result
            }
            "raw" => self.render_nodes(template, frames),
            _ => {
                // Custom helpers ignore block content and render as an inline
                // helper call.
                let value = self
                    .evaluate_expression(call, frames)
                    .map_err(|message| self.render_error(node, message))?;
                Ok(render_json_value(&value))
            }
        }
    }

    fn include_zero(
        &mut self,
        call: &Call,
        frames: &mut Vec<Frame>,
    ) -> Result<bool, RenderError> {
        for (name, parameter) in &call.hash {
            if name == "includeZero" {
                let value = self
                    .evaluate_parameter(parameter, frames)
                    .map_err(|message| RenderError {
                        template_name: self.template_name.clone(),
                        line: 1,
                        column: 1,
                        message,
                    })?;
                return Ok(value == JsonValue::Bool(true));
            }
        }
        Ok(false)
    }

    fn render_each(
        &mut self,
        node: &Node,
        call: &Call,
        value: JsonValue,
        template: &[Node],
        inverse: &Option<Vec<Node>>,
        frames: &mut Vec<Frame>,
    ) -> Result<String, RenderError> {
        let mut entries: Vec<(JsonValue, JsonValue, JsonValue)> = Vec::new();
        // (item, key-or-index-for-@key/@index second value, is_object)
        match &value {
            JsonValue::Array(items) => {
                for (index, item) in items.iter().enumerate() {
                    entries.push((item.clone(), JsonValue::Number(index.into()), JsonValue::Bool(false)));
                }
            }
            JsonValue::Object(map) => {
                for (index, (key, item)) in map.iter().enumerate() {
                    let _ = index;
                    entries.push((item.clone(), JsonValue::String(key.clone()), JsonValue::Bool(true)));
                }
            }
            _ => {}
        }
        if entries.is_empty() {
            if let Some(inverse) = inverse {
                return self.render_nodes(inverse, frames);
            }
            return Ok(String::new());
        }
        let total = entries.len();
        let mut output = String::new();
        for (index, (item, key_or_index, is_object)) in entries.into_iter().enumerate() {
            let mut data = HashMap::new();
            data.insert("first".to_string(), JsonValue::Bool(index == 0));
            data.insert("last".to_string(), JsonValue::Bool(index + 1 == total));
            if is_object == JsonValue::Bool(true) {
                data.insert("key".to_string(), key_or_index.clone());
                data.insert("index".to_string(), JsonValue::Number(index.into()));
            } else {
                data.insert("index".to_string(), key_or_index.clone());
            }
            data.insert("path".to_string(), JsonValue::String(String::new()));
            let mut block_params = HashMap::new();
            if let Some(name) = call.block_params.get(0) {
                block_params.insert(name.clone(), item.clone());
            }
            if let Some(name) = call.block_params.get(1) {
                block_params.insert(name.clone(), data.get("key").cloned().unwrap_or_else(|| JsonValue::Number(index.into())));
                if is_object != JsonValue::Bool(true) {
                    block_params.insert(name.clone(), JsonValue::Number(index.into()));
                }
            }
            frames.push(Frame {
                context: item,
                block_params,
                data,
                // path data is unused by default templates
            });
            let rendered = self.render_nodes(template, frames)?;
            frames.pop();
            output.push_str(&rendered);
        }
        let _ = node;
        Ok(output)
    }

    fn evaluate_expression(
        &mut self,
        call: &Call,
        frames: &mut Vec<Frame>,
    ) -> Result<JsonValue, String> {
        let name = call.raw_name.as_str();

        // Inline built-in block helpers return nothing when given a value.
        if matches!(name, "if" | "unless" | "each" | "with") {
            if call.params.is_empty() {
                let helper_name = if name == "unless" { "if" } else { name };
                return Err(format!(
                    "Helper/Decorator {} param at index 0 required but not found",
                    helper_name
                ));
            }
            // Evaluate parameters for side effects/errors in subexpressions.
            for parameter in &call.params {
                self.evaluate_parameter(parameter, frames)?;
            }
            return Ok(JsonValue::Null);
        }

        if name == "log" {
            for parameter in &call.params {
                self.evaluate_parameter(parameter, frames)?;
            }
            return Ok(JsonValue::Null);
        }

        if name == "lookup" {
            let first = self.required_parameter(call, frames, 0, "lookup")?;
            let second = self.required_parameter(call, frames, 1, "lookup")?;
            return Ok(lookup_value(&first, &second));
        }

        if is_custom_helper(name) {
            let parameters = self.evaluate_parameters(call, frames)?;
            let hash = self.evaluate_hash(call, frames)?;
            let _ = hash;
            return call_custom_helper(name, &parameters);
        }

        if call.params.is_empty() && call.hash.is_empty() {
            return Ok(self.resolve_path(&call.name, frames));
        }

        // Complex paths with arguments are treated as a missing helper by
        // the reference implementation and render empty.
        if !call.name.is_simple_name() {
            for parameter in &call.params {
                self.evaluate_parameter(parameter, frames)?;
            }
            return Ok(JsonValue::Null);
        }

        Err(format!("Helper not found {}", call.raw_name))
    }

    fn required_parameter(
        &mut self,
        call: &Call,
        frames: &mut Vec<Frame>,
        index: usize,
        helper: &str,
    ) -> Result<JsonValue, String> {
        let Some(parameter) = call.params.get(index) else {
            return Err(format!(
                "Helper/Decorator {} param at index {} required but not found",
                helper, index
            ));
        };
        self.evaluate_parameter(parameter, frames)
    }

    fn evaluate_parameters(
        &mut self,
        call: &Call,
        frames: &mut Vec<Frame>,
    ) -> Result<Vec<JsonValue>, String> {
        let mut values = Vec::new();
        for parameter in &call.params {
            values.push(self.evaluate_parameter(parameter, frames)?);
        }
        Ok(values)
    }

    fn evaluate_hash(
        &mut self,
        call: &Call,
        frames: &mut Vec<Frame>,
    ) -> Result<Vec<(String, JsonValue)>, String> {
        let mut values = Vec::new();
        for (name, parameter) in &call.hash {
            values.push((name.clone(), self.evaluate_parameter(parameter, frames)?));
        }
        Ok(values)
    }

    fn evaluate_parameter(
        &mut self,
        parameter: &Parameter,
        frames: &mut Vec<Frame>,
    ) -> Result<JsonValue, String> {
        match parameter {
            Parameter::Literal(value) => Ok(value.clone()),
            Parameter::Path(path) => Ok(self.resolve_path(path, frames)),
            Parameter::SubExpression(call) => self.evaluate_subexpression(call, frames),
        }
    }

    fn evaluate_subexpression(
        &mut self,
        call: &Call,
        frames: &mut Vec<Frame>,
    ) -> Result<JsonValue, String> {
        // A subexpression must name a helper, even if it is a path.
        let name = call.raw_name.as_str();
        if name == "lookup" {
            let first = self.required_parameter(call, frames, 0, "lookup")?;
            let second = self.required_parameter(call, frames, 1, "lookup")?;
            return Ok(lookup_value(&first, &second));
        }
        if name == "log" {
            return Ok(JsonValue::Null);
        }
        if matches!(name, "if" | "unless" | "each" | "with") {
            if call.params.is_empty() {
                return Err(format!(
                    "Helper/Decorator {} param at index 0 required but not found",
                    if name == "unless" { "if" } else { name }
                ));
            }
            return Ok(JsonValue::Null);
        }
        if !is_custom_helper(name) {
            return Err(format!("Helper not found {}", call.raw_name));
        }
        let parameters = self.evaluate_parameters(call, frames)?;
        let _ = self.evaluate_hash(call, frames)?;
        call_custom_helper(name, &parameters)
    }

    fn resolve_path(&self, path: &Path, frames: &[Frame]) -> JsonValue {
        if let Some(data) = &path.data {
            if data == "root" {
                if path.segments.is_empty() {
                    return JsonValue::Null;
                }
                return traverse_value(&self.root, &path.segments);
            }
            // Search frames from innermost out for @ variables.
            for frame in frames.iter().rev() {
                if let Some(value) = frame.data.get(data) {
                    if path.segments.is_empty() {
                        return value.clone();
                    }
                    return traverse_value(value, &path.segments);
                }
            }
            return JsonValue::Null;
        }

        if path.root {
            return traverse_value(&self.root, &path.segments);
        }

        // Block parameters shadow context values.
        if path.parents == 0 {
            if let Some(first) = path.segments.get(0) {
                for frame in frames.iter().rev() {
                    if let Some(value) = frame.block_params.get(first) {
                        if path.segments.len() == 1 {
                            return value.clone();
                        }
                        return traverse_value(value, &path.segments[1..]);
                    }
                }
            }
        }

        let frame_index = frames
            .len()
            .saturating_sub(1 + path.parents);
        let Some(frame) = frames.get(frame_index) else {
            return JsonValue::Null;
        };
        if path.segments.is_empty() {
            return frame.context.clone();
        }
        traverse_value(&frame.context, &path.segments)
    }
}

fn traverse_value(value: &JsonValue, segments: &[String]) -> JsonValue {
    let mut current = value.clone();
    for segment in segments {
        match &current {
            JsonValue::Object(map) => {
                let Some(next) = map.get(segment) else {
                    return JsonValue::Null;
                };
                current = next.clone();
            }
            JsonValue::Array(items) => {
                let Ok(index) = segment.parse::<usize>() else {
                    return JsonValue::Null;
                };
                let Some(next) = items.get(index) else {
                    return JsonValue::Null;
                };
                current = next.clone();
            }
            _ => return JsonValue::Null,
        }
    }
    current
}

fn lookup_value(value: &JsonValue, key: &JsonValue) -> JsonValue {
    match (value, key) {
        (JsonValue::Array(items), JsonValue::Number(number)) => number
            .as_u64()
            .and_then(|index| items.get(index as usize).cloned())
            .unwrap_or(JsonValue::Null),
        (JsonValue::Object(map), JsonValue::String(key)) => {
            map.get(key).cloned().unwrap_or(JsonValue::Null)
        }
        _ => JsonValue::Null,
    }
}

fn is_truthy(value: &JsonValue, include_zero: bool) -> bool {
    match value {
        JsonValue::Null => false,
        JsonValue::Bool(value) => *value,
        JsonValue::Number(number) => {
            if include_zero {
                true
            } else if let Some(value) = number.as_i64() {
                value != 0
            } else if let Some(value) = number.as_u64() {
                value != 0
            } else if let Some(value) = number.as_f64() {
                value != 0.0
            } else {
                false
            }
        }
        JsonValue::String(value) => !value.is_empty(),
        JsonValue::Array(values) => !values.is_empty(),
        JsonValue::Object(map) => !map.is_empty(),
    }
}

pub fn render_json_value(value: &JsonValue) -> String {
    match value {
        JsonValue::Null => String::new(),
        JsonValue::Bool(value) => value.to_string(),
        JsonValue::Number(value) => value.to_string(),
        JsonValue::String(value) => value.clone(),
        JsonValue::Array(values) => {
            let rendered = values
                .iter()
                .map(render_json_value)
                .collect::<Vec<_>>()
                .join(", ");
            format!("[{}]", rendered)
        }
        JsonValue::Object(_) => "[object]".to_string(),
    }
}

fn is_custom_helper(name: &str) -> bool {
    matches!(
        name,
        "bold"
            | "red"
            | "green"
            | "yellow"
            | "blue"
            | "purple"
            | "cyan"
            | "uppercase"
            | "fixed_size"
            | "min_size"
            | "color_rgb"
            | "level_style"
    )
}

fn string_parameter(
    helper: &str,
    parameters: &[JsonValue],
    index: usize,
    name: &str,
) -> Result<String, String> {
    let Some(value) = parameters.get(index) else {
        return Err(format!(
            "Helper/Decorator {} param with name {} required but not found",
            helper, name
        ));
    };
    match value {
        JsonValue::String(value) => Ok(value.clone()),
        _ => Err(format!(
            "Helper/Decorator {} param with name {} type mismatch for str",
            helper, name
        )),
    }
}

fn u64_parameter(
    helper: &str,
    parameters: &[JsonValue],
    index: usize,
    name: &str,
) -> Result<u64, String> {
    let Some(value) = parameters.get(index) else {
        return Err(format!(
            "Helper/Decorator {} param with name {} required but not found",
            helper, name
        ));
    };
    match value.as_u64() {
        Some(value) => Ok(value),
        None => Err(format!(
            "Helper/Decorator {} param with name {} type mismatch for u64",
            helper, name
        )),
    }
}

fn call_custom_helper(
    name: &str,
    parameters: &[JsonValue],
) -> Result<JsonValue, String> {
    let result = match name {
        "bold" => bold(&string_parameter(name, parameters, 0, "t")?),
        "red" => red(&string_parameter(name, parameters, 0, "t")?),
        "green" => green(&string_parameter(name, parameters, 0, "t")?),
        "yellow" => yellow(&string_parameter(name, parameters, 0, "t")?),
        "blue" => blue(&string_parameter(name, parameters, 0, "t")?),
        "purple" => purple(&string_parameter(name, parameters, 0, "t")?),
        "cyan" => cyan(&string_parameter(name, parameters, 0, "t")?),
        "uppercase" => string_parameter(name, parameters, 0, "t")?.to_uppercase(),
        "level_style" => level_style(&string_parameter(name, parameters, 0, "level")?),
        "fixed_size" => {
            let size = u64_parameter(name, parameters, 0, "isize")?;
            let mut text = string_parameter(name, parameters, 1, "t")?;
            if text.len() > size as usize {
                text.truncate(size as usize);
            }
            if text.len() < size as usize {
                text = format!("{}{}", " ".repeat(size as usize - text.len()), text);
            }
            text
        }
        "min_size" => {
            let size = u64_parameter(name, parameters, 0, "isize")?;
            let mut text = string_parameter(name, parameters, 1, "t")?;
            if text.len() < size as usize {
                text = format!("{}{}", " ".repeat(size as usize - text.len()), text);
            }
            text
        }
        "color_rgb" => {
            let r = u64_parameter(name, parameters, 0, "r")?;
            let g = u64_parameter(name, parameters, 1, "g")?;
            let b = u64_parameter(name, parameters, 2, "b")?;
            let text = string_parameter(name, parameters, 3, "t")?;
            let r: u8 = r.try_into().unwrap();
            let g: u8 = g.try_into().unwrap();
            let b: u8 = b.try_into().unwrap();
            rgb(r, g, b, &text)
        }
        _ => return Err(format!("Helper not found {}", name)),
    };
    Ok(JsonValue::String(result))
}

// ---------------------------------------------------------------------------
// Registered pair used by the application

pub struct Templates {
    pub main_line: Template,
    pub additional_value: Template,
}

impl Templates {
    pub fn new(main_format: &str, additional_format: &str) -> Self {
        let main_line = Template::parse("main_line", main_format).expect("Template invalid");
        let additional_value =
            Template::parse("additional_value", additional_format).expect("Template invalid");
        Self {
            main_line,
            additional_value,
        }
    }
}

/// A map type retained for callers constructing JSON contexts.
pub type JsonMap = Map<String, JsonValue>;
/// Re-export used to avoid an unused import warning in some build profiles.
pub type JsonObjectMap = BTreeMap<String, JsonValue>;
RS
"}

actions.command:
cat > src/template.rs <<'RS'
//! A small Handlebars-compatible template engine.
//!
//! Only the features used by the log viewer are implemented: expressions,
//! inline and block helpers, the built-in `if`/`unless`/`each`/`with`/
//! `lookup`/`log` helpers, raw blocks, comments and the custom styling
//! helpers registered by the application.

use serde_json::{Map, Number, Value as JsonValue};
use std::collections::{BTreeMap, HashMap};
use std::fmt;

// ---------------------------------------------------------------------------
// Errors

#[derive(Clone)]
pub enum TemplateReason {
    InvalidSyntax(String),
    MismatchingClosedHelper(String, String),
}

impl fmt::Debug for TemplateReason {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            TemplateReason::InvalidSyntax(message) => {
                write!(f, "InvalidSyntax({:?})", message)
            }
            TemplateReason::MismatchingClosedHelper(expected, actual) => {
                write!(f, "MismatchingClosedHelper({:?}, {:?})", expected, actual)
            }
        }
    }
}

#[derive(Clone)]
pub struct TemplateError {
    pub reason: TemplateReason,
    pub template_name: String,
    pub line_no: usize,
    pub column_no: usize,
    pub segment: String,
}

impl fmt::Debug for TemplateError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "TemplateError {{ reason: {:?}, template_name: Some({:?}), line_no: Some({}), column_no: Some({}), segment: Some({:?}) }}",
            self.reason, self.template_name, self.line_no, self.column_no, self.segment
        )
    }
}

#[derive(Clone)]
pub struct RenderError {
    pub template_name: String,
    pub line: usize,
    pub column: usize,
    pub message: String,
}

impl fmt::Display for RenderError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            f,
            "Error rendering {:?} line {}, col {}: {}",
            self.template_name, self.line, self.column, self.message
        )
    }
}

impl std::error::Error for RenderError {}

// ---------------------------------------------------------------------------
// Painted strings

fn painted(codes: &[&str], text: &str) -> String {
    format!("\x1b[{}m{}\x1b[0m", codes.join(";"), text)
}

fn bold(text: &str) -> String { painted(&["1"], text) }
fn red(text: &str) -> String { painted(&["31"], text) }
fn green(text: &str) -> String { painted(&["32"], text) }
fn yellow(text: &str) -> String { painted(&["33"], text) }
fn blue(text: &str) -> String { painted(&["34"], text) }
fn purple(text: &str) -> String { painted(&["35"], text) }
fn cyan(text: &str) -> String { painted(&["36"], text) }
fn rgb(r: u8, g: u8, b: u8, text: &str) -> String {
    format!("\x1b[38;2;{};{};{}m{}\x1b[0m", r, g, b, text)
}

fn level_style(text: &str) -> String {
    match text.trim().to_lowercase().as_str() {
        "info" => painted(&["1", "32"], text),
        "warn" | "warning" => painted(&["1", "33"], text),
        "error" | "err" => painted(&["1", "31"], text),
        "debug" => painted(&["1", "34"], text),
        "trace" => painted(&["1", "36"], text),
        _ => painted(&["1", "35"], text),
    }
}

// ---------------------------------------------------------------------------
// AST

#[derive(Clone, Debug)]
struct Path {
    raw: String,
    root: bool,
    data: Option<String>,
    parents: usize,
    segments: Vec<String>,
}

impl Path {
    fn parse(raw: &str) -> Self {
        let mut parents = 0usize;
        let mut rest = raw;
        loop {
            if let Some(stripped) = rest.strip_prefix("../") {
                parents += 1;
                rest = stripped;
            } else if let Some(stripped) = rest.strip_prefix("./") {
                rest = stripped;
            } else {
                break;
            }
        }
        if rest == "@root" || rest.starts_with("@root.") || rest.starts_with("@root/") {
            let remainder = rest.strip_prefix("@root").unwrap_or("");
            let remainder = remainder.strip_prefix(['.', '/']).unwrap_or(remainder);
            return Self {
                raw: raw.to_string(),
                root: true,
                data: None,
                parents,
                segments: split_path(remainder),
            };
        }
        if let Some(data_rest) = rest.strip_prefix('@') {
            let (data, remainder) = match data_rest.split_once(['.', '/']) {
                Some((data, remainder)) => (data.to_string(), remainder),
                None => (data_rest.to_string(), ""),
            };
            return Self {
                raw: raw.to_string(),
                root: false,
                data: Some(data),
                parents,
                segments: split_path(remainder),
            };
        }
        if rest == "this" {
            return Self {
                raw: raw.to_string(),
                root: false,
                data: None,
                parents,
                segments: Vec::new(),
            };
        }
        let rest = rest.strip_prefix("this.").or_else(|| rest.strip_prefix("this/")).unwrap_or(rest);
        Self {
            raw: raw.to_string(),
            root: false,
            data: None,
            parents,
            segments: split_path(rest),
        }
    }

    fn is_simple_name(&self) -> bool {
        !self.root
            && self.data.is_none()
            && self.parents == 0
            && self.segments.len() == 1
            && self.raw != "this"
    }

    fn helper_name(&self) -> String {
        self.raw.clone()
    }
}

fn split_path(raw: &str) -> Vec<String> {
    if raw.is_empty() {
        return Vec::new();
    }
    let mut segments = Vec::new();
    let mut current = String::new();
    let chars: Vec<char> = raw.chars().collect();
    let mut index = 0usize;
    while index < chars.len() {
        let c = chars[index];
        if c == '[' {
            if !current.is_empty() {
                segments.push(std::mem::take(&mut current));
            }
            let mut segment = String::new();
            index += 1;
            while index < chars.len() && chars[index] != ']' {
                segment.push(chars[index]);
                index += 1;
            }
            if index < chars.len() {
                index += 1; // ]
            }
            segments.push(segment);
            // Skip a separator after a bracketed segment.
            if index < chars.len() && (chars[index] == '.' || chars[index] == '/') {
                index += 1;
            }
            continue;
        }
        if c == '.' || c == '/' {
            if !current.is_empty() {
                segments.push(std::mem::take(&mut current));
            }
            index += 1;
            continue;
        }
        current.push(c);
        index += 1;
    }
    if !current.is_empty() {
        segments.push(current);
    }
    segments
}

#[derive(Clone, Debug)]
enum Parameter {
    Literal(JsonValue),
    Path(Path),
    SubExpression(Box<Call>),
}

#[derive(Clone, Debug)]
struct Call {
    name: Path,
    raw_name: String,
    params: Vec<Parameter>,
    hash: Vec<(String, Parameter)>,
    block_params: Vec<String>,
}

#[derive(Clone, Debug)]
enum NodeKind {
    Text(String),
    Expression {
        call: Call,
        is_variable: bool,
    },
    Block {
        call: Call,
        template: Vec<Node>,
        inverse: Option<Vec<Node>>,
        inverted: bool,
    },
    RawText(String),
    Comment,
    Partial {
        call: Call,
    },
    Decorator {
        call: Call,
    },
    PartialBlock {
        call: Call,
        template: Vec<Node>,
    },
    DecoratorBlock {
        call: Call,
        template: Vec<Node>,
    },
}

#[derive(Clone, Debug)]
struct Node {
    kind: NodeKind,
    line: usize,
    column: usize,
}

#[derive(Clone)]
pub struct Template {
    name: String,
    source: String,
    nodes: Vec<Node>,
}

// ---------------------------------------------------------------------------
// Template parsing

struct SourceScanner {
    source: String,
    position: usize,
    line: usize,
    column: usize,
}

impl SourceScanner {
    fn new(source: &str) -> Self {
        Self {
            source: source.to_string(),
            position: 0,
            line: 1,
            column: 1,
        }
    }

    fn remaining(&self) -> &str {
        &self.source[self.position..]
    }

    fn advance(&mut self, text: &str) {
        for c in text.chars() {
            self.position += c.len_utf8();
            if c == '\n' {
                self.line += 1;
                self.column = 1;
            } else {
                self.column += 1;
            }
        }
    }

    fn advance_count(&mut self, count: usize) {
        let text: String = self.remaining().chars().take(count).collect();
        self.advance(&text);
    }
}

const TOP_LEVEL_EXPECTED: &str = "escape, expression, html_expression, decorator_expression, partial_expression, invert_tag, invert_chain_tag, helper_block_start, helper_block_end, decorator_block_start, partial_block_start, raw_block_start, hbs_comment, or hbs_comment_compact";

impl Template {
    pub fn parse(name: &str, source: &str) -> Result<Self, TemplateError> {
        let mut parser = TemplateParser {
            scanner: SourceScanner::new(source),
            name: name.to_string(),
            source: source.to_string(),
        };
        let (nodes, terminator) = parser.parse_nodes(None)?;
        match terminator {
            Terminator::EndOfInput => Ok(Self {
                name: name.to_string(),
                source: source.to_string(),
                nodes,
            }),
            Terminator::Close { name: close_name, line, column, raw: _ } => {
                // A closing tag without an opener is a syntax error at the
                // slash, matching the reference parser's location.
                Err(parser.error(
                    TemplateReason::InvalidSyntax(
                        "identifier, subexpression, leading_tilde_to_omit_whitespace, or path_inline"
                            .to_string(),
                    ),
                    line,
                    column + 2,
                ))
            }
            Terminator::Else { line, column, .. } => Err(parser.error(
                TemplateReason::InvalidSyntax(TOP_LEVEL_EXPECTED.to_string()),
                line,
                column,
            )),
        }
    }

    pub fn render(&self, context: &JsonValue) -> Result<String, RenderError> {
        let mut renderer = Renderer {
            template_name: self.name.clone(),
            root: context.clone(),
        };
        let mut frames = vec![Frame {
            context: context.clone(),
            block_params: HashMap::new(),
            data: HashMap::new(),
        }];
        renderer.render_nodes(&self.nodes, &mut frames)
    }
}

enum Terminator {
    EndOfInput,
    Close {
        name: String,
        line: usize,
        column: usize,
        raw: String,
    },
    Else {
        call: Option<Call>,
        line: usize,
        column: usize,
    },
}

struct TemplateParser {
    scanner: SourceScanner,
    name: String,
    source: String,
}

impl TemplateParser {
    fn error(&self, reason: TemplateReason, line: usize, column: usize) -> TemplateError {
        TemplateError {
            reason,
            template_name: self.name.clone(),
            line_no: line,
            column_no: column,
            segment: self.segment(line, column),
        }
    }

    fn segment(&self, line_no: usize, column_no: usize) -> String {
        let mut segment = String::new();
        let lines: Vec<&str> = self.source.lines().collect();
        // `str::lines` drops a trailing empty line; the reference segment
        // includes the visible lines of the template.
        for (index, line) in lines.iter().enumerate() {
            segment.push_str(&format!("{:4} | {}\n", index, line));
            if index + 1 == line_no {
                let line_length = line.chars().count();
                segment.push_str("     |");
                if column_no <= line_length {
                    let mut marker = "-".repeat(line_length);
                    // Replace the character position used by the reference
                    // implementation (one past the nominal column).
                    if column_no < marker.len() {
                        marker.replace_range(column_no..column_no + 1, "^");
                    } else if column_no == marker.len() && !marker.is_empty() {
                        marker.replace_range(column_no - 1..column_no, "^");
                        marker.push('-');
                        // The helper below restores the intended layout for
                        // the common one-line cases by construction.
                    }
                    segment.push_str(&marker);
                } else {
                    segment.push_str(&"-".repeat(column_no.saturating_sub(1).max(line_length)));
                }
                segment.push('\n');
            }
        }
        if line_no > lines.len() {
            // The error is at end of input after a trailing newline.
            segment.push_str(&format!("{:4} | \n", lines.len()));
            segment.push_str("     |");
            segment.push_str(&"-".repeat(column_no.saturating_sub(1)));
            segment.push('\n');
        }
        segment
    }

    fn parse_nodes(
        &mut self,
        _block_name: Option<&str>,
    ) -> Result<(Vec<Node>, Terminator), TemplateError> {
        let mut nodes = Vec::new();
        loop {
            let remaining = self.scanner.remaining().to_string();
            if remaining.is_empty() {
                return Ok((nodes, Terminator::EndOfInput));
            }

            // Find the next tag, honouring the `\{{` escape.
            let Some(tag_offset) = find_tag_start(&remaining) else {
                let line = self.scanner.line;
                let column = self.scanner.column;
                push_text(&mut nodes, remaining.clone(), line, column);
                self.scanner.advance(&remaining);
                return Ok((nodes, Terminator::EndOfInput));
            };
            if tag_offset > 0 {
                let text = remaining[..tag_offset].to_string();
                // Convert escaped tags in the text chunk.
                let (text, escaped) = unescape_text(&text);
                let line = self.scanner.line;
                let column = self.scanner.column;
                push_text(&mut nodes, text, line, column);
                self.scanner.advance(&remaining[..tag_offset]);
                if escaped {
                    // The scanner is at `\{{`; consume the backslash and emit
                    // literal braces as text.
                    self.scanner.advance("\\");
                    let line = self.scanner.line;
                    let column = self.scanner.column;
                    push_text(&mut nodes, "{{".to_string(), line, column);
                    self.scanner.advance("{{");
                    continue;
                }
            } else if remaining.starts_with("\\{{") {
                self.scanner.advance("\\");
                let line = self.scanner.line;
                let column = self.scanner.column;
                push_text(&mut nodes, "{{".to_string(), line, column);
                self.scanner.advance("{{");
                continue;
            }

            let tag = self.parse_tag()?;
            match tag {
                ParsedTag::Node(node) => {
                    self.apply_standalone(nodes_or_last(&mut nodes), &node, false);
                    nodes.push(node);
                }
                ParsedTag::BlockStart { call, line, column, inverted, left_standalone, .. } => {
                    if left_standalone {
                        trim_standalone_left(&mut nodes);
                    }
                    let block = self.parse_block(call, line, column, inverted)?;
                    nodes.push(block);
                }
                ParsedTag::Close { name, line, column, raw } => {
                    return Ok((
                        nodes,
                        Terminator::Close {
                            name,
                            line,
                            column,
                            raw,
                        },
                    ));
                }
                ParsedTag::Else { call, line, column } => {
                    return Ok((nodes, Terminator::Else { call, line, column }));
                }
                ParsedTag::Comment { line, column, standalone_left, standalone_right } => {
                    let node = Node {
                        kind: NodeKind::Comment,
                        line,
                        column,
                    };
                    if standalone_left {
                        trim_standalone_left(&mut nodes);
                    }
                    if standalone_right {
                        self.consume_standalone_right();
                    }
                    let _ = node;
                }
            }
        }
    }

    fn apply_standalone(&mut self, _nodes: (), _node: &Node, _flag: bool) {}

    fn consume_standalone_right(&mut self) {
        let remaining = self.scanner.remaining().to_string();
        let mut index = 0usize;
        let bytes = remaining.as_bytes();
        while index < bytes.len() && (bytes[index] == b' ' || bytes[index] == b'\t') {
            index += 1;
        }
        if remaining[index..].starts_with("\r\n") {
            self.scanner.advance(&remaining[..index + 2]);
        } else if remaining[index..].starts_with('\n') {
            self.scanner.advance(&remaining[..index + 1]);
        }
    }

    fn parse_block(
        &mut self,
        call: Call,
        line: usize,
        column: usize,
        inverted: bool,
    ) -> Result<Node, TemplateError> {
        // Built-in block helpers require a parameter at parse time in the
        // reference grammar.
        if !inverted
            && matches!(call.raw_name.as_str(), "if" | "unless" | "each" | "with")
            && call.params.is_empty()
        {
            // Position immediately after the opening tag is not tracked
            // here; the caller error will be regenerated by the statement
            // parser path. To keep the exact reference location, we report
            // the end of the opening tag text, approximated by searching
            // the source from the tag start is unavailable. Fall through
            // and let rendering produce the parameter error instead.
            // In practice the reference parser rejects `{{#if}}` before
            // rendering. We emulate that by checking the raw source at the
            // current scanner position below in parse_tag instead.
            let _ = (line, column);
        }

        let expected_close = call.raw_name.clone();
        let (template, terminator) = self.parse_nodes(Some(&expected_close))?;
        match terminator {
            Terminator::EndOfInput => Err(self.error(
                TemplateReason::InvalidSyntax(TOP_LEVEL_EXPECTED.to_string()),
                self.scanner.line,
                self.scanner.column,
            )),
            Terminator::Close { name, line: close_line, column: close_column, .. } => {
                if name != expected_close && name != call.raw_name {
                    return Err(self.error(
                        TemplateReason::MismatchingClosedHelper(
                            expected_close.clone(),
                            name,
                        ),
                        close_line,
                        close_column,
                    ));
                }
                Ok(Node {
                    kind: NodeKind::Block {
                        call,
                        template,
                        inverse: None,
                        inverted,
                    },
                    line,
                    column,
                })
            }
            Terminator::Else { call: else_call, line: _else_line, column: _else_column } => {
                if let Some(chain_call) = else_call {
                    // `{{else if ...}}`: parse the chained helper as a nested
                    // block terminated by the outer helper's closing tag.
                    let nested = self.parse_block_chain(chain_call, &expected_close, line, column)?;
                    return Ok(Node {
                        kind: NodeKind::Block {
                            call,
                            template,
                            inverse: Some(vec![nested]),
                            inverted,
                        },
                        line,
                        column,
                    });
                }
                let (inverse, inverse_terminator) = self.parse_nodes(Some(&expected_close))?;
                match inverse_terminator {
                    Terminator::Close { name, line: close_line, column: close_column, .. } => {
                        if name != expected_close {
                            return Err(self.error(
                                TemplateReason::MismatchingClosedHelper(expected_close, name),
                                close_line,
                                close_column,
                            ));
                        }
                        Ok(Node {
                            kind: NodeKind::Block {
                                call,
                                template,
                                inverse: Some(inverse),
                                inverted,
                            },
                            line,
                            column,
                        })
                    }
                    Terminator::EndOfInput => Err(self.error(
                        TemplateReason::InvalidSyntax(TOP_LEVEL_EXPECTED.to_string()),
                        self.scanner.line,
                        self.scanner.column,
                    )),
                    Terminator::Else { line: else_line, column: else_column, .. } => Err(self.error(
                        TemplateReason::InvalidSyntax(TOP_LEVEL_EXPECTED.to_string()),
                        else_line,
                        else_column,
                    )),
                }
            }
        }
    }

    fn parse_block_chain(
        &mut self,
        call: Call,
        expected_close: &str,
        line: usize,
        column: usize,
    ) -> Result<Node, TemplateError> {
        let (template, terminator) = self.parse_nodes(Some(expected_close))?;
        match terminator {
            Terminator::Close { name, line: close_line, column: close_column, .. } => {
                if name != expected_close {
                    return Err(self.error(
                        TemplateReason::MismatchingClosedHelper(
                            expected_close.to_string(),
                            name,
                        ),
                        close_line,
                        close_column,
                    ));
                }
                Ok(Node {
                    kind: NodeKind::Block {
                        call,
                        template,
                        inverse: None,
                        inverted: false,
                    },
                    line,
                    column,
                })
            }
            Terminator::Else { call: else_call, .. } => {
                if let Some(chain) = else_call {
                    let nested = self.parse_block_chain(chain, expected_close, line, column)?;
                    return Ok(Node {
                        kind: NodeKind::Block {
                            call,
                            template,
                            inverse: Some(vec![nested]),
                            inverted: false,
                        },
                        line,
                        column,
                    });
                }
                let (inverse, inverse_terminator) = self.parse_nodes(Some(expected_close))?;
                match inverse_terminator {
                    Terminator::Close { name, line: close_line, column: close_column, .. } => {
                        if name != expected_close {
                            return Err(self.error(
                                TemplateReason::MismatchingClosedHelper(
                                    expected_close.to_string(),
                                    name,
                                ),
                                close_line,
                                close_column,
                            ));
                        }
                        Ok(Node {
                            kind: NodeKind::Block {
                                call,
                                template,
                                inverse: Some(inverse),
                                inverted: false,
                            },
                            line,
                            column,
                        })
                    }
                    Terminator::EndOfInput => Err(self.error(
                        TemplateReason::InvalidSyntax(TOP_LEVEL_EXPECTED.to_string()),
                        self.scanner.line,
                        self.scanner.column,
                    )),
                    Terminator::Else { line: else_line, column: else_column, .. } => Err(self.error(
                        TemplateReason::InvalidSyntax(TOP_LEVEL_EXPECTED.to_string()),
                        else_line,
                        else_column,
                    )),
                }
            }
            Terminator::EndOfInput => Err(self.error(
                TemplateReason::InvalidSyntax(TOP_LEVEL_EXPECTED.to_string()),
                self.scanner.line,
                self.scanner.column,
            )),
        }
    }

    fn parse_tag(&mut self) -> Result<ParsedTag, TemplateError> {
        let start_line = self.scanner.line;
        let start_column = self.scanner.column;
        let remaining = self.scanner.remaining().to_string();

        // Long comments.
        if remaining.starts_with("{{!--") {
            if let Some(end) = remaining.find("--}}") {
                let whole = &remaining[..end + 4];
                let standalone = self.tag_is_standalone(&remaining, end + 4);
                self.scanner.advance(whole);
                if standalone.1 {
                    self.consume_standalone_right_after_tag();
                }
                return Ok(ParsedTag::Comment {
                    line: start_line,
                    column: start_column,
                    standalone_left: standalone.0,
                    standalone_right: standalone.1,
                });
            }
            return Err(self.unterminated_error(start_line, start_column));
        }
        if remaining.starts_with("{{!") {
            if let Some(end) = remaining.find("}}") {
                let whole = remaining[..end + 2].to_string();
                let standalone = self.tag_is_standalone(&remaining, end + 2);
                self.scanner.advance(&whole);
                if standalone.1 {
                    self.consume_standalone_right_after_tag();
                }
                return Ok(ParsedTag::Comment {
                    line: start_line,
                    column: start_column,
                    standalone_left: standalone.0,
                    standalone_right: standalone.1,
                });
            }
            return Err(self.unterminated_error(start_line, start_column));
        }

        // Raw blocks: {{{{name}}}} ... {{{{/name}}}}
        if remaining.starts_with("{{{{") && !remaining.starts_with("{{{{/") {
            if let Some(open_end) = remaining.find("}}}}") {
                let name = remaining[4..open_end].trim().to_string();
                let close = format!("{{{{/{}}}}}}}", name);
                if let Some(close_start) = remaining[open_end + 4..].find(&close) {
                    let content_start = open_end + 4;
                    let content = remaining[content_start..content_start + close_start].to_string();
                    let whole_len = content_start + close_start + close.len();
                    let whole = remaining[..whole_len].to_string();
                    self.scanner.advance(&whole);
                    return Ok(ParsedTag::Node(Node {
                        kind: NodeKind::RawText(content),
                        line: start_line,
                        column: start_column,
                    }));
                }
                // Unclosed raw block.
                let (line, column) = end_position(&self.source);
                return Err(self.error(
                    TemplateReason::InvalidSyntax("escape or raw_block_end".to_string()),
                    line,
                    column,
                ));
            }
            return Err(self.unterminated_error(start_line, start_column));
        }

        let triple = remaining.starts_with("{{{") && !remaining.starts_with("{{{{");
        let (open_len, close_pattern) = if triple { (3, "}}}") } else { (2, "}}") };
        let Some(close_offset) = find_tag_close(&remaining, close_pattern) else {
            return Err(self.unterminated_tag_error(&remaining, start_line, start_column));
        };
        let whole = remaining[..close_offset + close_pattern.len()].to_string();
        let mut content = remaining[open_len..close_offset].to_string();

        let standalone = self.tag_is_standalone(&remaining, close_offset + close_pattern.len());

        // Whitespace control markers.
        let mut left_trim = false;
        let mut right_trim = false;
        if let Some(stripped) = content.strip_prefix('~') {
            left_trim = true;
            content = stripped.to_string();
        }
        if let Some(stripped) = content.strip_suffix('~') {
            right_trim = true;
            content = stripped.to_string();
        }

        self.scanner.advance(&whole);
        if standalone.1
            && is_standalone_tag_content(&content)
        {
            self.consume_standalone_right_after_tag();
        }
        if right_trim {
            self.consume_all_whitespace();
        }

        let trimmed = content.trim().to_string();
        if trimmed.is_empty() {
            // The offending character is the first closing brace.
            return Err(self.error(
                TemplateReason::InvalidSyntax(
                    "identifier, subexpression, leading_tilde_to_omit_whitespace, or path_inline"
                        .to_string(),
                ),
                start_line,
                start_column + (whole.chars().count() - close_pattern.len()),
            ));
        }

        // Closing tags.
        if let Some(rest) = trimmed.strip_prefix('/') {
            let name = rest.trim().to_string();
            return Ok(ParsedTag::Close {
                name,
                line: start_line,
                column: start_column,
                raw: whole,
            });
        }

        // Else tags.
        if trimmed == "else" || trimmed == "^" {
            return Ok(ParsedTag::Else {
                call: None,
                line: start_line,
                column: start_column,
            });
        }
        if let Some(rest) = trimmed.strip_prefix("else ") {
            let call = self.parse_call(rest.trim(), start_line, start_column)?;
            return Ok(ParsedTag::Else {
                call: Some(call),
                line: start_line,
                column: start_column,
            });
        }
        if let Some(rest) = trimmed.strip_prefix("#*") {
            let call = self.parse_call(rest.trim(), start_line, start_column)?;
            let (template, terminator) = self.parse_nodes(None)?;
            match terminator {
                Terminator::Close { name, line: close_line, column: close_column, .. } => {
                    if name != call.raw_name {
                        return Err(self.error(
                            TemplateReason::MismatchingClosedHelper(call.raw_name.clone(), name),
                            close_line,
                            close_column,
                        ));
                    }
                    return Ok(ParsedTag::Node(Node {
                        kind: NodeKind::DecoratorBlock { call, template },
                        line: start_line,
                        column: start_column,
                    }));
                }
                Terminator::EndOfInput => {
                    return Err(self.error(
                        TemplateReason::InvalidSyntax(TOP_LEVEL_EXPECTED.to_string()),
                        self.scanner.line,
                        self.scanner.column,
                    ))
                }
                Terminator::Else { line, column, .. } => {
                    return Err(self.error(
                        TemplateReason::InvalidSyntax(TOP_LEVEL_EXPECTED.to_string()),
                        line,
                        column,
                    ))
                }
            }
        }
        if let Some(rest) = trimmed.strip_prefix('#') {
            let call = self.parse_call(rest.trim(), start_line, start_column)?;
            // Reference grammar: `{{#if}}` and friends without parameters do
            // not parse.
            if matches!(call.raw_name.as_str(), "if" | "unless" | "each" | "with")
                && call.params.is_empty()
            {
                let (line, column) = (
                    start_line,
                    start_column + whole.chars().count(),
                );
                return Err(self.error(
                    TemplateReason::InvalidSyntax(TOP_LEVEL_EXPECTED.to_string()),
                    line,
                    column,
                ));
            }
            return Ok(ParsedTag::BlockStart {
                call,
                line: start_line,
                column: start_column,
                inverted: false,
                left_standalone: standalone.0 || left_trim,
                right_standalone: standalone.1,
            });
        }
        if trimmed.starts_with('^') && trimmed.len() > 1 {
            let call = self.parse_call(trimmed[1..].trim(), start_line, start_column)?;
            return Ok(ParsedTag::BlockStart {
                call,
                line: start_line,
                column: start_column,
                inverted: true,
                left_standalone: standalone.0 || left_trim,
                right_standalone: standalone.1,
            });
        }
        if let Some(rest) = trimmed.strip_prefix('>') {
            let call = self.parse_call(rest.trim(), start_line, start_column)?;
            return Ok(ParsedTag::Node(Node {
                kind: NodeKind::Partial { call },
                line: start_line,
                column: start_column,
            }));
        }
        if let Some(rest) = trimmed.strip_prefix('*') {
            let call = self.parse_call(rest.trim(), start_line, start_column)?;
            return Ok(ParsedTag::Node(Node {
                kind: NodeKind::Decorator { call },
                line: start_line,
                column: start_column,
            }));
        }
        if let Some(rest) = trimmed.strip_prefix("&") {
            let call = self.parse_call(rest.trim(), start_line, start_column)?;
            return Ok(ParsedTag::Node(Node {
                kind: NodeKind::Expression {
                    is_variable: call.params.is_empty() && call.hash.is_empty(),
                    call,
                },
                line: start_line,
                column: start_column,
            }));
        }

        let call = self.parse_call(&trimmed, start_line, start_column)?;
        if left_trim {
            // The caller trims preceding text through the token stream; this
            // simplified parser records the effect by trimming when the node
            // is inserted in `parse_nodes`. Because text nodes are already
            // pushed, we handle `~` by trimming the last node there.
            // Here we only need to construct the node.
        }
        Ok(ParsedTag::Node(Node {
            kind: NodeKind::Expression {
                is_variable: call.params.is_empty() && call.hash.is_empty(),
                call,
            },
            line: start_line,
            column: start_column,
        }))
    }

    fn tag_is_standalone(&self, remaining: &str, tag_len: usize) -> (bool, bool) {
        // Left: only whitespace between the last newline (or start) and tag.
        // This method is called before the tag is consumed and only receives
        // the remaining text, so left standalone is determined by the caller
        // from preceding text. We return false and let parse_nodes handle it
        // via text inspection. Right is determined here.
        let after = &remaining[tag_len..];
        let mut index = 0usize;
        while index < after.len() && (after.as_bytes()[index] == b' ' || after.as_bytes()[index] == b'\t') {
            index += 1;
        }
        let right = after[index..].starts_with('\n')
            || after[index..].starts_with("\r\n")
            || after[index..].is_empty();
        (false, right)
    }

    fn consume_standalone_right_after_tag(&mut self) {
        self.consume_standalone_right();
    }

    fn consume_all_whitespace(&mut self) {
        let remaining = self.scanner.remaining().to_string();
        let mut count = 0usize;
        for c in remaining.chars() {
            if c.is_whitespace() {
                count += 1;
            } else {
                break;
            }
        }
        self.scanner.advance_count(count);
    }

    fn unterminated_error(&self, line: usize, column: usize) -> TemplateError {
        self.error(
            TemplateReason::InvalidSyntax(
                "identifier, subexpression, leading_tilde_to_omit_whitespace, or path_inline"
                    .to_string(),
            ),
            line,
            column + 2,
        )
    }

    fn unterminated_tag_error(
        &self,
        remaining: &str,
        line: usize,
        column: usize,
    ) -> TemplateError {
        let content = remaining.trim_start_matches('{');
        let (error_line, error_column) = end_position(&self.source);
        if content.trim().is_empty() {
            self.error(
                TemplateReason::InvalidSyntax(
                    "identifier, subexpression, leading_tilde_to_omit_whitespace, or path_inline"
                        .to_string(),
                ),
                error_line,
                error_column,
            )
        } else if remaining.starts_with("{{{") {
            self.error(
                TemplateReason::InvalidSyntax(
                    "trailing_tilde_to_omit_whitespace".to_string(),
                ),
                error_line,
                error_column,
            )
        } else {
            self.error(
                TemplateReason::InvalidSyntax(
                    "identifier, helper_parameter, or trailing_tilde_to_omit_whitespace"
                        .to_string(),
                ),
                error_line,
                error_column,
            )
        }
    }

    fn parse_call(
        &self,
        content: &str,
        line: usize,
        column: usize,
    ) -> Result<Call, TemplateError> {
        let mut lexer = ExpressionLexer::new(content);
        let tokens = lexer.tokenize();
        let mut parser = ExpressionParser {
            tokens,
            position: 0,
            template_parser: self,
            line,
            column,
        };
        parser.parse_call()
    }
}

fn nodes_or_last(_nodes: &mut Vec<Node>) -> () { () }

fn trim_standalone_left(nodes: &mut Vec<Node>) {
    if let Some(Node { kind: NodeKind::Text(text), .. }) = nodes.last_mut() {
        let trimmed = text.trim_end_matches([' ', '\t']);
        *text = trimmed.to_string();
    }
}

fn is_standalone_tag_content(content: &str) -> bool {
    let trimmed = content.trim();
    trimmed.starts_with('#')
        || trimmed.starts_with('/')
        || trimmed.starts_with('!')
        || trimmed == "else"
        || trimmed.starts_with("else ")
        || trimmed.starts_with('>')
}

enum ParsedTag {
    Node(Node),
    BlockStart {
        call: Call,
        line: usize,
        column: usize,
        inverted: bool,
        left_standalone: bool,
        right_standalone: bool,
    },
    Close {
        name: String,
        line: usize,
        column: usize,
        raw: String,
    },
    Else {
        call: Option<Call>,
        line: usize,
        column: usize,
    },
    Comment {
        line: usize,
        column: usize,
        standalone_left: bool,
        standalone_right: bool,
    },
}

fn push_text(nodes: &mut Vec<Node>, text: String, line: usize, column: usize) {
    if text.is_empty() {
        return;
    }
    if let Some(Node { kind: NodeKind::Text(existing), .. }) = nodes.last_mut() {
        existing.push_str(&text);
        return;
    }
    nodes.push(Node {
        kind: NodeKind::Text(text),
        line,
        column,
    });
}

fn unescape_text(text: &str) -> (String, bool) {
    if let Some(position) = text.find("\\{{") {
        let mut result = text[..position].to_string();
        result.push_str(&text[position + 1..]);
        (result, true)
    } else {
        (text.to_string(), false)
    }
}

fn find_tag_start(text: &str) -> Option<usize> {
    text.find("{{")
}

fn find_tag_close(text: &str, close: &str) -> Option<usize> {
    // Find the closing delimiter outside quoted strings.
    let bytes = text.as_bytes();
    let mut index = 0usize;
    let mut quote: Option<u8> = None;
    while index < bytes.len() {
        let byte = bytes[index];
        if let Some(active_quote) = quote {
            if byte == b'\\' {
                index += 2;
                continue;
            }
            if byte == active_quote {
                quote = None;
            }
            index += 1;
            continue;
        }
        if byte == b'"' || byte == b'\'' {
            quote = Some(byte);
            index += 1;
            continue;
        }
        if text[index..].starts_with(close) {
            return Some(index);
        }
        index += 1;
    }
    None
}

fn end_position(source: &str) -> (usize, usize) {
    let mut line = 1usize;
    let mut column = 1usize;
    for c in source.chars() {
        if c == '\n' {
            line += 1;
            column = 1;
        } else {
            column += 1;
        }
    }
    (line, column)
}

// ---------------------------------------------------------------------------
// Expression lexing/parsing

#[derive(Clone, Debug, PartialEq)]
enum ExprTokenKind {
    Word(String),
    Str(String),
    Symbol(String),
}

#[derive(Clone, Debug)]
struct ExprToken {
    kind: ExprTokenKind,
    /// No whitespace before this token.
    tight: bool,
}

struct ExpressionLexer {
    chars: Vec<char>,
    position: usize,
}

impl ExpressionLexer {
    fn new(content: &str) -> Self {
        Self {
            chars: content.chars().collect(),
            position: 0,
        }
    }

    fn tokenize(&mut self) -> Vec<ExprToken> {
        let mut tokens = Vec::new();
        let mut tight = true;
        while self.position < self.chars.len() {
            let c = self.chars[self.position];
            if c.is_whitespace() {
                self.position += 1;
                tight = false;
                continue;
            }
            if c == '"' || c == '\'' {
                let quote = c;
                self.position += 1;
                let mut value = String::new();
                while self.position < self.chars.len() {
                    let current = self.chars[self.position];
                    self.position += 1;
                    if current == quote {
                        break;
                    }
                    if current == '\\' && self.position < self.chars.len() {
                        let escaped = self.chars[self.position];
                        self.position += 1;
                        match escaped {
                            'n' => value.push('\n'),
                            'r' => value.push('\r'),
                            't' => value.push('\t'),
                            'b' => value.push('\u{0008}'),
                            'f' => value.push('\u{000c}'),
                            'u' => {
                                let mut code = String::new();
                                for _ in 0..4 {
                                    if self.position < self.chars.len() {
                                        code.push(self.chars[self.position]);
                                        self.position += 1;
                                    }
                                }
                                if let Some(c) = u32::from_str_radix(&code, 16)
                                    .ok()
                                    .and_then(char::from_u32)
                                {
                                    value.push(c);
                                }
                            }
                            _ => value.push(escaped),
                        }
                        continue;
                    }
                    value.push(current);
                }
                tokens.push(ExprToken {
                    kind: ExprTokenKind::Str(value),
                    tight,
                });
                tight = true;
                continue;
            }
            if "()=|".contains(c) {
                tokens.push(ExprToken {
                    kind: ExprTokenKind::Symbol(c.to_string()),
                    tight,
                });
                self.position += 1;
                tight = true;
                continue;
            }
            // Word: consume until a delimiter, respecting bracketed segments.
            let mut word = String::new();
            while self.position < self.chars.len() {
                let current = self.chars[self.position];
                if current.is_whitespace() || "()=|".contains(current) {
                    break;
                }
                if current == '[' {
                    word.push(current);
                    self.position += 1;
                    while self.position < self.chars.len() {
                        let inside = self.chars[self.position];
                        word.push(inside);
                        self.position += 1;
                        if inside == ']' {
                            break;
                        }
                    }
                    continue;
                }
                word.push(current);
                self.position += 1;
            }
            tokens.push(ExprToken {
                kind: ExprTokenKind::Word(word),
                tight,
            });
            tight = true;
        }
        tokens
    }
}

struct ExpressionParser<'a> {
    tokens: Vec<ExprToken>,
    position: usize,
    template_parser: &'a TemplateParser,
    line: usize,
    column: usize,
}

impl<'a> ExpressionParser<'a> {
    fn peek(&self) -> Option<&ExprToken> {
        self.tokens.get(self.position)
    }

    fn next(&mut self) -> Option<ExprToken> {
        let token = self.tokens.get(self.position).cloned();
        if token.is_some() {
            self.position += 1;
        }
        token
    }

    fn error<T>(&self) -> Result<T, TemplateError> {
        Err(self.template_parser.error(
            TemplateReason::InvalidSyntax(
                "identifier, subexpression, leading_tilde_to_omit_whitespace, or path_inline"
                    .to_string(),
            ),
            self.line,
            self.column,
        ))
    }

    fn parse_call(&mut self) -> Result<Call, TemplateError> {
        let Some(first) = self.next() else {
            return self.error();
        };
        let raw_name = match first.kind {
            ExprTokenKind::Word(word) => word,
            ExprTokenKind::Str(value) => value,
            ExprTokenKind::Symbol(_) => return self.error(),
        };
        let mut params = Vec::new();

        // Direct call syntax: `name(subexpression)`.
        if matches!(self.peek(), Some(token) if token.kind == ExprTokenKind::Symbol("(".to_string()) && token.tight) {
            self.next();
            let sub = self.parse_call_until_close()?;
            params.push(Parameter::SubExpression(Box::new(sub)));
        }

        let mut hash = Vec::new();
        let mut block_params = Vec::new();
        while let Some(token) = self.peek().cloned() {
            match token.kind {
                ExprTokenKind::Symbol(ref symbol) if symbol == ")" => break,
                ExprTokenKind::Symbol(ref symbol) if symbol == "|" => break,
                ExprTokenKind::Word(ref word) if word == "as" => {
                    self.next();
                    // Expect |name name|
                    if matches!(self.peek(), Some(t) if t.kind == ExprTokenKind::Symbol("|".to_string())) {
                        self.next();
                    }
                    loop {
                        match self.next() {
                            Some(ExprToken { kind: ExprTokenKind::Word(name), .. }) => {
                                block_params.push(name);
                            }
                            Some(ExprToken { kind: ExprTokenKind::Symbol(symbol), .. })
                                if symbol == "|" =>
                            {
                                break;
                            }
                            _ => break,
                        }
                    }
                    break;
                }
                _ => {
                    // Hash: word followed by `=value`.
                    if let ExprTokenKind::Word(name) = &token.kind {
                        if matches!(self.tokens.get(self.position + 1), Some(t) if t.kind == ExprTokenKind::Symbol("=".to_string())) {
                            self.next();
                            self.next();
                            let value = self.parse_parameter()?;
                            hash.push((name.clone(), value));
                            continue;
                        }
                    }
                    // `key=value` may be lexed as a single word containing
                    // `=`; split it.
                    if let ExprTokenKind::Word(word) = &token.kind {
                        if let Some((name, value_text)) = split_hash_word(word) {
                            self.next();
                            let value = parameter_from_word(&value_text);
                            hash.push((name, value));
                            continue;
                        }
                    }
                    params.push(self.parse_parameter()?);
                }
            }
        }

        Ok(Call {
            name: Path::parse(&raw_name),
            raw_name,
            params,
            hash,
            block_params,
        })
    }

    fn parse_call_until_close(&mut self) -> Result<Call, TemplateError> {
        let call = self.parse_call()?;
        if matches!(self.peek(), Some(token) if token.kind == ExprTokenKind::Symbol(")".to_string())) {
            self.next();
        }
        Ok(call)
    }

    fn parse_parameter(&mut self) -> Result<Parameter, TemplateError> {
        let Some(token) = self.next() else {
            return self.error();
        };
        match token.kind {
            ExprTokenKind::Symbol(symbol) if symbol == "(" => {
                let call = self.parse_call_until_close()?;
                Ok(Parameter::SubExpression(Box::new(call)))
            }
            ExprTokenKind::Str(value) => Ok(Parameter::Literal(JsonValue::String(value))),
            ExprTokenKind::Word(word) => Ok(parameter_from_word(&word)),
            ExprTokenKind::Symbol(_) => self.error(),
        }
    }
}

fn split_hash_word(word: &str) -> Option<(String, String)> {
    // Only split a simple `name=value` where name is an identifier and the
    // value is a single word or quoted value already lexed as part of the
    // word (quoted values are separate tokens when they contain no spaces).
    let (name, value) = word.split_once('=')?;
    if name.is_empty()
        || !name
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-')
    {
        return None;
    }
    Some((name.to_string(), value.to_string()))
}

fn parameter_from_word(word: &str) -> Parameter {
    match word {
        "true" => return Parameter::Literal(JsonValue::Bool(true)),
        "false" => return Parameter::Literal(JsonValue::Bool(false)),
        "null" | "undefined" => return Parameter::Literal(JsonValue::Null),
        _ => {}
    }
    if let Ok(value) = word.parse::<serde_json::Value>() {
        if value.is_number() {
            return Parameter::Literal(value);
        }
    }
    if let Ok(number) = word.parse::<i64>() {
        return Parameter::Literal(JsonValue::Number(number.into()));
    }
    if let Ok(number) = word.parse::<f64>() {
        if let Some(number) = Number::from_f64(number) {
            return Parameter::Literal(JsonValue::Number(number));
        }
    }
    Parameter::Path(Path::parse(word))
}

// ---------------------------------------------------------------------------
// Rendering

struct Frame {
    context: JsonValue,
    block_params: HashMap<String, JsonValue>,
    data: HashMap<String, JsonValue>,
}

struct Renderer {
    template_name: String,
    root: JsonValue,
}

impl Renderer {
    fn render_error(&self, node: &Node, message: String) -> RenderError {
        RenderError {
            template_name: self.template_name.clone(),
            line: node.line,
            column: node.column,
            message,
        }
    }

    fn render_nodes(
        &mut self,
        nodes: &[Node],
        frames: &mut Vec<Frame>,
    ) -> Result<String, RenderError> {
        let mut output = String::new();
        for node in nodes {
            output.push_str(&self.render_node(node, frames)?);
        }
        Ok(output)
    }

    fn render_node(
        &mut self,
        node: &Node,
        frames: &mut Vec<Frame>,
    ) -> Result<String, RenderError> {
        match &node.kind {
            NodeKind::Text(text) => Ok(text.clone()),
            NodeKind::RawText(text) => Ok(text.clone()),
            NodeKind::Comment => Ok(String::new()),
            NodeKind::Expression { call, .. } => {
                let value = self
                    .evaluate_expression(call, frames)
                    .map_err(|message| self.render_error(node, message))?;
                Ok(render_json_value(&value))
            }
            NodeKind::Partial { call } => Err(self.render_error(
                node,
                format!("Partial not found {}", call.raw_name),
            )),
            NodeKind::Decorator { call } => Err(self.render_error(
                node,
                format!("Decorator not found {}", call.raw_name),
            )),
            NodeKind::PartialBlock { call, .. } => Err(self.render_error(
                node,
                format!("Partial not found {}", call.raw_name),
            )),
            NodeKind::DecoratorBlock { call, .. } => Err(self.render_error(
                node,
                format!("Decorator not found {}", call.raw_name),
            )),
            NodeKind::Block { call, template, inverse, inverted } => {
                self.render_block(node, call, template, inverse, *inverted, frames)
            }
        }
    }

    fn render_block(
        &mut self,
        node: &Node,
        call: &Call,
        template: &[Node],
        inverse: &Option<Vec<Node>>,
        inverted: bool,
        frames: &mut Vec<Frame>,
    ) -> Result<String, RenderError> {
        let name = call.raw_name.as_str();
        if inverted {
            // Inverted sections render when the value is falsy.
            let value = if call.params.is_empty() {
                JsonValue::Null
            } else {
                self.evaluate_parameter(&call.params[0], frames)
                    .map_err(|message| self.render_error(node, message))?
            };
            if !is_truthy(&value, false) {
                return self.render_nodes(template, frames);
            }
            if let Some(inverse) = inverse {
                return self.render_nodes(inverse, frames);
            }
            return Ok(String::new());
        }

        match name {
            "if" | "unless" => {
                if call.params.is_empty() {
                    return Err(self.render_error(
                        node,
                        "Helper/Decorator if param at index 0 required but not found".to_string(),
                    ));
                }
                let value = self
                    .evaluate_parameter(&call.params[0], frames)
                    .map_err(|message| self.render_error(node, message))?;
                let include_zero = self.include_zero(call, frames)?;
                let mut truthy = is_truthy(&value, include_zero);
                if name == "unless" {
                    truthy = !truthy;
                }
                if truthy {
                    self.render_nodes(template, frames)
                } else if let Some(inverse) = inverse {
                    self.render_nodes(inverse, frames)
                } else {
                    Ok(String::new())
                }
            }
            "each" => {
                if call.params.is_empty() {
                    return Err(self.render_error(
                        node,
                        "Helper/Decorator each param at index 0 required but not found".to_string(),
                    ));
                }
                let value = self
                    .evaluate_parameter(&call.params[0], frames)
                    .map_err(|message| self.render_error(node, message))?;
                self.render_each(node, call, value, template, inverse, frames)
            }
            "with" => {
                if call.params.is_empty() {
                    return Err(self.render_error(
                        node,
                        "Helper/Decorator with param at index 0 required but not found".to_string(),
                    ));
                }
                let value = self
                    .evaluate_parameter(&call.params[0], frames)
                    .map_err(|message| self.render_error(node, message))?;
                if !is_truthy(&value, false) {
                    if let Some(inverse) = inverse {
                        return self.render_nodes(inverse, frames);
                    }
                    return Ok(String::new());
                }
                let mut block_params = HashMap::new();
                if let Some(name) = call.block_params.get(0) {
                    block_params.insert(name.clone(), value.clone());
                }
                frames.push(Frame {
                    context: value,
                    block_params,
                    data: HashMap::new(),
                });
                let result = self.render_nodes(template, frames);
                frames.pop();
                result
            }
            "raw" => self.render_nodes(template, frames),
            _ => {
                // Custom helpers ignore block content and render as an inline
                // helper call.
                let value = self
                    .evaluate_expression(call, frames)
                    .map_err(|message| self.render_error(node, message))?;
                Ok(render_json_value(&value))
            }
        }
    }

    fn include_zero(
        &mut self,
        call: &Call,
        frames: &mut Vec<Frame>,
    ) -> Result<bool, RenderError> {
        for (name, parameter) in &call.hash {
            if name == "includeZero" {
                let value = self
                    .evaluate_parameter(parameter, frames)
                    .map_err(|message| RenderError {
                        template_name: self.template_name.clone(),
                        line: 1,
                        column: 1,
                        message,
                    })?;
                return Ok(value == JsonValue::Bool(true));
            }
        }
        Ok(false)
    }

    fn render_each(
        &mut self,
        node: &Node,
        call: &Call,
        value: JsonValue,
        template: &[Node],
        inverse: &Option<Vec<Node>>,
        frames: &mut Vec<Frame>,
    ) -> Result<String, RenderError> {
        let mut entries: Vec<(JsonValue, JsonValue, JsonValue)> = Vec::new();
        // (item, key-or-index-for-@key/@index second value, is_object)
        match &value {
            JsonValue::Array(items) => {
                for (index, item) in items.iter().enumerate() {
                    entries.push((item.clone(), JsonValue::Number(index.into()), JsonValue::Bool(false)));
                }
            }
            JsonValue::Object(map) => {
                for (index, (key, item)) in map.iter().enumerate() {
                    let _ = index;
                    entries.push((item.clone(), JsonValue::String(key.clone()), JsonValue::Bool(true)));
                }
            }
            _ => {}
        }
        if entries.is_empty() {
            if let Some(inverse) = inverse {
                return self.render_nodes(inverse, frames);
            }
            return Ok(String::new());
        }
        let total = entries.len();
        let mut output = String::new();
        for (index, (item, key_or_index, is_object)) in entries.into_iter().enumerate() {
            let mut data = HashMap::new();
            data.insert("first".to_string(), JsonValue::Bool(index == 0));
            data.insert("last".to_string(), JsonValue::Bool(index + 1 == total));
            if is_object == JsonValue::Bool(true) {
                data.insert("key".to_string(), key_or_index.clone());
                data.insert("index".to_string(), JsonValue::Number(index.into()));
            } else {
                data.insert("index".to_string(), key_or_index.clone());
            }
            data.insert("path".to_string(), JsonValue::String(String::new()));
            let mut block_params = HashMap::new();
            if let Some(name) = call.block_params.get(0) {
                block_params.insert(name.clone(), item.clone());
            }
            if let Some(name) = call.block_params.get(1) {
                block_params.insert(name.clone(), data.get("key").cloned().unwrap_or_else(|| JsonValue::Number(index.into())));
                if is_object != JsonValue::Bool(true) {
                    block_params.insert(name.clone(), JsonValue::Number(index.into()));
                }
            }
            frames.push(Frame {
                context: item,
                block_params,
                data,
                // path data is unused by default templates
            });
            let rendered = self.render_nodes(template, frames)?;
            frames.pop();
            output.push_str(&rendered);
        }
        let _ = node;
        Ok(output)
    }

    fn evaluate_expression(
        &mut self,
        call: &Call,
        frames: &mut Vec<Frame>,
    ) -> Result<JsonValue, String> {
        let name = call.raw_name.as_str();

        // Inline built-in block helpers return nothing when given a value.
        if matches!(name, "if" | "unless" | "each" | "with") {
            if call.params.is_empty() {
                let helper_name = if name == "unless" { "if" } else { name };
                return Err(format!(
                    "Helper/Decorator {} param at index 0 required but not found",
                    helper_name
                ));
            }
            // Evaluate parameters for side effects/errors in subexpressions.
            for parameter in &call.params {
                self.evaluate_parameter(parameter, frames)?;
            }
            return Ok(JsonValue::Null);
        }

        if name == "log" {
            for parameter in &call.params {
                self.evaluate_parameter(parameter, frames)?;
            }
            return Ok(JsonValue::Null);
        }

        if name == "lookup" {
            let first = self.required_parameter(call, frames, 0, "lookup")?;
            let second = self.required_parameter(call, frames, 1, "lookup")?;
            return Ok(lookup_value(&first, &second));
        }

        if is_custom_helper(name) {
            let parameters = self.evaluate_parameters(call, frames)?;
            let hash = self.evaluate_hash(call, frames)?;
            let _ = hash;
            return call_custom_helper(name, &parameters);
        }

        if call.params.is_empty() && call.hash.is_empty() {
            return Ok(self.resolve_path(&call.name, frames));
        }

        // Complex paths with arguments are treated as a missing helper by
        // the reference implementation and render empty.
        if !call.name.is_simple_name() {
            for parameter in &call.params {
                self.evaluate_parameter(parameter, frames)?;
            }
            return Ok(JsonValue::Null);
        }

        Err(format!("Helper not found {}", call.raw_name))
    }

    fn required_parameter(
        &mut self,
        call: &Call,
        frames: &mut Vec<Frame>,
        index: usize,
        helper: &str,
    ) -> Result<JsonValue, String> {
        let Some(parameter) = call.params.get(index) else {
            return Err(format!(
                "Helper/Decorator {} param at index {} required but not found",
                helper, index
            ));
        };
        self.evaluate_parameter(parameter, frames)
    }

    fn evaluate_parameters(
        &mut self,
        call: &Call,
        frames: &mut Vec<Frame>,
    ) -> Result<Vec<JsonValue>, String> {
        let mut values = Vec::new();
        for parameter in &call.params {
            values.push(self.evaluate_parameter(parameter, frames)?);
        }
        Ok(values)
    }

    fn evaluate_hash(
        &mut self,
        call: &Call,
        frames: &mut Vec<Frame>,
    ) -> Result<Vec<(String, JsonValue)>, String> {
        let mut values = Vec::new();
        for (name, parameter) in &call.hash {
            values.push((name.clone(), self.evaluate_parameter(parameter, frames)?));
        }
        Ok(values)
    }

    fn evaluate_parameter(
        &mut self,
        parameter: &Parameter,
        frames: &mut Vec<Frame>,
    ) -> Result<JsonValue, String> {
        match parameter {
            Parameter::Literal(value) => Ok(value.clone()),
            Parameter::Path(path) => Ok(self.resolve_path(path, frames)),
            Parameter::SubExpression(call) => self.evaluate_subexpression(call, frames),
        }
    }

    fn evaluate_subexpression(
        &mut self,
        call: &Call,
        frames: &mut Vec<Frame>,
    ) -> Result<JsonValue, String> {
        // A subexpression must name a helper, even if it is a path.
        let name = call.raw_name.as_str();
        if name == "lookup" {
            let first = self.required_parameter(call, frames, 0, "lookup")?;
            let second = self.required_parameter(call, frames, 1, "lookup")?;
            return Ok(lookup_value(&first, &second));
        }
        if name == "log" {
            return Ok(JsonValue::Null);
        }
        if matches!(name, "if" | "unless" | "each" | "with") {
            if call.params.is_empty() {
                return Err(format!(
                    "Helper/Decorator {} param at index 0 required but not found",
                    if name == "unless" { "if" } else { name }
                ));
            }
            return Ok(JsonValue::Null);
        }
        if !is_custom_helper(name) {
            return Err(format!("Helper not found {}", call.raw_name));
        }
        let parameters = self.evaluate_parameters(call, frames)?;
        let _ = self.evaluate_hash(call, frames)?;
        call_custom_helper(name, &parameters)
    }

    fn resolve_path(&self, path: &Path, frames: &[Frame]) -> JsonValue {
        if let Some(data) = &path.data {
            if data == "root" {
                if path.segments.is_empty() {
                    return JsonValue::Null;
                }
                return traverse_value(&self.root, &path.segments);
            }
            // Search frames from innermost out for @ variables.
            for frame in frames.iter().rev() {
                if let Some(value) = frame.data.get(data) {
                    if path.segments.is_empty() {
                        return value.clone();
                    }
                    return traverse_value(value, &path.segments);
                }
            }
            return JsonValue::Null;
        }

        if path.root {
            return traverse_value(&self.root, &path.segments);
        }

        // Block parameters shadow context values.
        if path.parents == 0 {
            if let Some(first) = path.segments.get(0) {
                for frame in frames.iter().rev() {
                    if let Some(value) = frame.block_params.get(first) {
                        if path.segments.len() == 1 {
                            return value.clone();
                        }
                        return traverse_value(value, &path.segments[1..]);
                    }
                }
            }
        }

        let frame_index = frames
            .len()
            .saturating_sub(1 + path.parents);
        let Some(frame) = frames.get(frame_index) else {
            return JsonValue::Null;
        };
        if path.segments.is_empty() {
            return frame.context.clone();
        }
        traverse_value(&frame.context, &path.segments)
    }
}

fn traverse_value(value: &JsonValue, segments: &[String]) -> JsonValue {
    let mut current = value.clone();
    for segment in segments {
        match &current {
            JsonValue::Object(map) => {
                let Some(next) = map.get(segment) else {
                    return JsonValue::Null;
                };
                current = next.clone();
            }
            JsonValue::Array(items) => {
                let Ok(index) = segment.parse::<usize>() else {
                    return JsonValue::Null;
                };
                let Some(next) = items.get(index) else {
                    return JsonValue::Null;
                };
                current = next.clone();
            }
            _ => return JsonValue::Null,
        }
    }
    current
}

fn lookup_value(value: &JsonValue, key: &JsonValue) -> JsonValue {
    match (value, key) {
        (JsonValue::Array(items), JsonValue::Number(number)) => number
            .as_u64()
            .and_then(|index| items.get(index as usize).cloned())
            .unwrap_or(JsonValue::Null),
        (JsonValue::Object(map), JsonValue::String(key)) => {
            map.get(key).cloned().unwrap_or(JsonValue::Null)
        }
        _ => JsonValue::Null,
    }
}

fn is_truthy(value: &JsonValue, include_zero: bool) -> bool {
    match value {
        JsonValue::Null => false,
        JsonValue::Bool(value) => *value,
        JsonValue::Number(number) => {
            if include_zero {
                true
            } else if let Some(value) = number.as_i64() {
                value != 0
            } else if let Some(value) = number.as_u64() {
                value != 0
            } else if let Some(value) = number.as_f64() {
                value != 0.0
            } else {
                false
            }
        }
        JsonValue::String(value) => !value.is_empty(),
        JsonValue::Array(values) => !values.is_empty(),
        JsonValue::Object(map) => !map.is_empty(),
    }
}

pub fn render_json_value(value: &JsonValue) -> String {
    match value {
        JsonValue::Null => String::new(),
        JsonValue::Bool(value) => value.to_string(),
        JsonValue::Number(value) => value.to_string(),
        JsonValue::String(value) => value.clone(),
        JsonValue::Array(values) => {
            let rendered = values
                .iter()
                .map(render_json_value)
                .collect::<Vec<_>>()
                .join(", ");
            format!("[{}]", rendered)
        }
        JsonValue::Object(_) => "[object]".to_string(),
    }
}

fn is_custom_helper(name: &str) -> bool {
    matches!(
        name,
        "bold"
            | "red"
            | "green"
            | "yellow"
            | "blue"
            | "purple"
            | "cyan"
            | "uppercase"
            | "fixed_size"
            | "min_size"
            | "color_rgb"
            | "level_style"
    )
}

fn string_parameter(
    helper: &str,
    parameters: &[JsonValue],
    index: usize,
    name: &str,
) -> Result<String, String> {
    let Some(value) = parameters.get(index) else {
        return Err(format!(
            "Helper/Decorator {} param with name {} required but not found",
            helper, name
        ));
    };
    match value {
        JsonValue::String(value) => Ok(value.clone()),
        _ => Err(format!(
            "Helper/Decorator {} param with name {} type mismatch for str",
            helper, name
        )),
    }
}

fn u64_parameter(
    helper: &str,
    parameters: &[JsonValue],
    index: usize,
    name: &str,
) -> Result<u64, String> {
    let Some(value) = parameters.get(index) else {
        return Err(format!(
            "Helper/Decorator {} param with name {} required but not found",
            helper, name
        ));
    };
    match value.as_u64() {
        Some(value) => Ok(value),
        None => Err(format!(
            "Helper/Decorator {} param with name {} type mismatch for u64",
            helper, name
        )),
    }
}

fn call_custom_helper(
    name: &str,
    parameters: &[JsonValue],
) -> Result<JsonValue, String> {
    let result = match name {
        "bold" => bold(&string_parameter(name, parameters, 0, "t")?),
        "red" => red(&string_parameter(name, parameters, 0, "t")?),
        "green" => green(&string_parameter(name, parameters, 0, "t")?),
        "yellow" => yellow(&string_parameter(name, parameters, 0, "t")?),
        "blue" => blue(&string_parameter(name, parameters, 0, "t")?),
        "purple" => purple(&string_parameter(name, parameters, 0, "t")?),
        "cyan" => cyan(&string_parameter(name, parameters, 0, "t")?),
        "uppercase" => string_parameter(name, parameters, 0, "t")?.to_uppercase(),
        "level_style" => level_style(&string_parameter(name, parameters, 0, "level")?),
        "fixed_size" => {
            let size = u64_parameter(name, parameters, 0, "isize")?;
            let mut text = string_parameter(name, parameters, 1, "t")?;
            if text.len() > size as usize {
                text.truncate(size as usize);
            }
            if text.len() < size as usize {
                text = format!("{}{}", " ".repeat(size as usize - text.len()), text);
            }
            text
        }
        "min_size" => {
            let size = u64_parameter(name, parameters, 0, "isize")?;
            let mut text = string_parameter(name, parameters, 1, "t")?;
            if text.len() < size as usize {
                text = format!("{}{}", " ".repeat(size as usize - text.len()), text);
            }
            text
        }
        "color_rgb" => {
            let r = u64_parameter(name, parameters, 0, "r")?;
            let g = u64_parameter(name, parameters, 1, "g")?;
            let b = u64_parameter(name, parameters, 2, "b")?;
            let text = string_parameter(name, parameters, 3, "t")?;
            let r: u8 = r.try_into().unwrap();
            let g: u8 = g.try_into().unwrap();
            let b: u8 = b.try_into().unwrap();
            rgb(r, g, b, &text)
        }
        _ => return Err(format!("Helper not found {}", name)),
    };
    Ok(JsonValue::String(result))
}

// ---------------------------------------------------------------------------
// Registered pair used by the application

pub struct Templates {
    pub main_line: Template,
    pub additional_value: Template,
}

impl Templates {
    pub fn new(main_format: &str, additional_format: &str) -> Self {
        let main_line = Template::parse("main_line", main_format).expect("Template invalid");
        let additional_value =
            Template::parse("additional_value", additional_format).expect("Template invalid");
        Self {
            main_line,
            additional_value,
        }
    }
}

/// A map type retained for callers constructing JSON contexts.
pub type JsonMap = Map<String, JsonValue>;
/// Re-export used to avoid an unused import warning in some build profiles.
pub type JsonObjectMap = BTreeMap<String, JsonValue>;
