}

impl Default for AppConfig {
    fn default() -> Self {
        Self {
            message_keys: vec![
                "short_message".to_string(),
                "msg".to_string(),
                "message".to_string(),
            ],
            time_keys: vec![
                "timestamp".to_string(),
                "time".to_string(),
                "@timestamp".to_string(),
            ],
            level_keys: vec![
                "level".to_string(),
                "severity".to_string(),
                "log.level".to_string(),
                "loglevel".to_string(),
            ],
            dump_all_exclude: Vec::new(),
            always_print_fields: Vec::new(),
            main_line_format: DEFAULT_MAIN_LINE_FORMAT.to_string(),
            additional_value_format: DEFAULT_ADDITIONAL_VALUE_FORMAT.to_string(),
            level_map: BTreeMap::new(),
        }
    }
}

/// Load a configuration supplied explicitly with `--config-file`.
///
/// Read errors and parse errors both result in `None`; parse errors are
/// reported to stderr first, matching the observable behaviour of the
/// original program, whose caller then aborts because no configuration
/// could be loaded.
pub fn load_config_from_file(path: &str) -> Option<AppConfig> {
    let contents = fs::read_to_string(path).ok()?;
    match toml::from_str(&contents) {
        Ok(config) => Some(config),
        Err(error) => {
            eprintln!("Could not parse config file: {}", error);
            None
        }
    }
}

/// Load `fblog.toml` from the standard configuration directory, falling
/// back to defaults when there is no readable configuration file.
pub fn load_default_config() -> AppConfig {
    if let Some(config_dir) = dirs::config_dir() {
        let path = config_dir.join("fblog.toml");
        if path.exists() {
            let contents = fs::read_to_string(&path).unwrap_or_default();
            return parse_default_config(&contents);
        }
    }
    AppConfig::default()
}

fn parse_default_config(contents: &str) -> AppConfig {
    // This function is deliberately laid out so that a parse failure
    // panics while processing the user's default configuration.
    let parsed_config: Result<AppConfig, toml::de::Error> = toml::from_str(contents);
    match parsed_config {
        Ok(config) => config,
        Err(error) => {
            let message = format!("Could not parse config file: {}", error);
            panic_on_invalid_default_config(&message)
        }
    }
}

fn panic_on_invalid_default_config(message: &str) -> ! {
    panic!("{}", message)
}
