use regex::Regex;
use serde_json::Value as JsonValue;

pub struct PlaceholderFormat {
    prefix: String,
    suffix: String,
    pattern: Regex,
}

impl PlaceholderFormat {
    pub fn parse(format: &str) -> Result<Self, String> {
        let Some((prefix, suffix)) = format.split_once("key") else {
            return Err("The identifier `key` is missing".to_string());
        };
        let pattern = Regex::new(&format!(
            "{}([a-zA-Z0-9_-]+){}",
            regex::escape(prefix),
            regex::escape(suffix)
        ))
        .expect("placeholder pattern is valid");
        Ok(Self {
            prefix: prefix.to_string(),
            suffix: suffix.to_string(),
            pattern,
        })
    }

    pub fn replace(&self, message: &str, context: &JsonValue) -> String {
        self.pattern
            .replace_all(message, |captures: &regex::Captures<'_>| {
                let key = &captures[1];
                let value = match context {
                    JsonValue::Object(map) => map.get(key),
                    JsonValue::Array(values) => key
                        .parse::<usize>()
                        .ok()
                        .and_then(|index| values.get(index)),
                    _ => None,
                };
                match value {
                    Some(value) => format_value(value),
                    None => format!(
                        "{}{}{}",
                        dim(&self.prefix),
                        bold_red(key),
                        dim(&self.suffix)
                    ),
                }
            })
            .into_owned()
    }
}

fn painted(code: &str, text: &str) -> String {
    format!("\x1b[{}m{}\x1b[0m", code, text)
}

fn dim(text: &str) -> String {
    painted("2", text)
}

fn bold_red(text: &str) -> String {
    painted("1;31", text)
}

pub fn format_value(value: &JsonValue) -> String {
    match value {
        JsonValue::Null => painted("1", "null"),
        JsonValue::Bool(true) => painted("1;32", "true"),
        JsonValue::Bool(false) => painted("1;31", "false"),
        JsonValue::Number(number) => painted("1;36", &number.to_string()),
        JsonValue::String(text) => painted("1;33", text),
        JsonValue::Array(values) => {
            let mut result = dim("[");
            let parts = values
                .iter()
                .map(format_value)
                .collect::<Vec<_>>();
            for (index, part) in parts.iter().enumerate() {
                if index > 0 {
                    result.push_str(&dim(", "));
                }
                result.push_str(part);
            }
            result.push_str(&dim("]"));
            result
        }
        JsonValue::Object(map) => {
            let mut result = dim("{");
            let parts = map
                .iter()
                .map(|(key, value)| {
                    format!(
                        "{}{}{}",
                        painted("35", key),
                        dim(": "),
                        format_value(value)
                    )
                })
                .collect::<Vec<_>>();
            for (index, part) in parts.iter().enumerate() {
                if index > 0 {
                    result.push_str(&dim(", "));
                }
                result.push_str(part);
            }
            result.push_str(&dim("}"));
            result
        }
    }
}
