    let mut message_keys = get_strings(matches, "message-key");
    message_keys.extend(app_config.message_keys.iter().cloned());

    let mut time_keys = get_strings(matches, "time-key");
    time_keys.extend(app_config.time_keys.iter().cloned());

    let mut level_keys = get_strings(matches, "level-key");
    level_keys.extend(app_config.level_keys.iter().cloned());

    let mut always_print_fields = app_config.always_print_fields.clone();
