    let mut excluded_values = app_config.dump_all_exclude.clone();
    excluded_values.extend(get_strings(matches, "excluded-value"));

    let mut level_map = app_config.level_map.clone();
    if let Some(mappings) = matches.get_many::<MapLevel>("map-level") {
        for mapping in mappings {
            level_map.insert(mapping.from.clone(), mapping.to.clone());
