}

// ---------------------------------------------------------------------------
// Flattened log values

#[derive(Default)]
struct FlattenedValues {
    entries: Vec<(String, String)>,
    positions: HashMap<String, usize>,
}

impl FlattenedValues {
    fn insert(&mut self, key: String, value: String) {
        if let Some(position) = self.positions.get(&key) {
            self.entries[*position].1 = value;
        } else {
            self.positions.insert(key.clone(), self.entries.len());
            self.entries.push((key, value));
        }
    }

    fn get(&self, key: &str) -> Option<&str> {
        self.positions
            .get(key)
            .map(|position| self.entries[*position].1.as_str())
    }

    fn first(&self, keys: &[String]) -> Option<&str> {
        keys.iter().find_map(|key| self.get(key))
    }

    fn iter(&self) -> impl Iterator<Item = &(String, String)> {
        self.entries.iter()
    }
}

fn flattened_scalar(value: &JsonValue) -> String {
    match value {
        JsonValue::String(text) => text.clone(),
        _ => value.to_string(),
    }
}

fn flatten_log_entry(object: &Map<String, JsonValue>) -> FlattenedValues {
    let mut flattened = FlattenedValues::default();
    for (key, value) in object {
        flatten_value(value, key.clone(), false, &mut flattened);
    }
    flattened
}

fn flatten_value(
    value: &JsonValue,
    key: String,
    parent_is_array: bool,
    flattened: &mut FlattenedValues,
) {
    match value {
        JsonValue::Object(map) => {
            for (child_key, child_value) in map {
                flatten_value(
                    child_value,
                    format!("{} > {}", key, child_key),
                    false,
                    flattened,
                );
            }
        }
        JsonValue::Array(values) => {
            let offset = if parent_is_array { 1 } else { 0 };
            for (index, child) in values.iter().enumerate() {
                let child_key = format!("{}[{}]", key, index + offset);
                match child {
                    JsonValue::Object(_) | JsonValue::Array(_) => {
                        flatten_value(child, child_key, true, flattened);
                    }
                    _ => {
                        // Values directly inside an array are represented by
                        // their JSON representation.
                        flattened.insert(child_key, child.to_string());
                    }
                }
            }
        }
        JsonValue::Null => {}
        _ => {
            flattened.insert(key, flattened_scalar(value));
        }
    }
}

// ---------------------------------------------------------------------------
// fblog values

fn convert_timestamp(value: &str) -> String {
    let Ok(timestamp) = value.parse::<i64>() else {
        return value.to_string();
    };
    let from_seconds = DateTime::from_timestamp(timestamp, 0);
    let from_millis = DateTime::from_timestamp_millis(timestamp);
    let selected = match (from_seconds, from_millis) {
        (Some(seconds), Some(millis)) => {
            let now = Utc::now().timestamp_millis() as i128;
            let seconds_distance = (timestamp as i128 * 1000 - now).abs();
            let millis_distance = (timestamp as i128 - now).abs();
            if millis_distance < seconds_distance {
                Some(millis)
            } else {
                Some(seconds)
            }
        }
        (Some(seconds), None) => Some(seconds),
        (None, Some(millis)) => Some(millis),
        (None, None) => None,
    };
    match selected {
        Some(datetime) => datetime.to_rfc3339_opts(SecondsFormat::Millis, true),
        None => value.to_string(),
    }
}

fn bold_red_prefix() -> String {
    "\x1b[1;31m??? >\x1b[0m".to_string()
}

fn additional_error_prefix() -> String {
    "\x1b[1;31m   ??? >\x1b[0m".to_string()
}

fn unparsable_prefix() -> String {
    "\x1b[1;38;2;255;135;22m??? >\x1b[0m".to_string()
}

fn parse_log_line(
    line: &str,
    with_prefix: bool,
) -> Option<(Map<String, JsonValue>, String)> {
    if with_prefix {
        let position = line.find('{')?;
        let prefix = line[..position].trim().to_string();
        let parsed: JsonValue = serde_json::from_str(&line[position..]).ok()?;
        match parsed {
            JsonValue::Object(map) => Some((map, prefix)),
            _ => None,
        }
    } else {
        let parsed: JsonValue = serde_json::from_str(line).ok()?;
        match parsed {
            JsonValue::Object(map) => Some((map, String::new())),
            _ => None,
        }
    }
}

fn main() {
    let matches = build_command().get_matches();
    let (settings, placeholder_format) = load_settings(&matches);

    let mut reader: Box<dyn BufRead> = if settings.input == "-" {
        Box::new(BufReader::new(io::stdin()))
    } else {
        let file = open_input_file(&settings.input);
        Box::new(BufReader::new(file))
    };

    let templates = Templates::new(
        &settings.main_line_format,
        &settings.additional_value_format,
    );

    for line_result in reader.lines() {
        let line = match line_result {
            Ok(line) => line,
            Err(error) => {
                println!("{} Could not read line: {}", bold_red_prefix(), error);
                continue;
            }
        };

        let Some((log_entry, prefix)) = parse_log_line(&line, settings.with_prefix)
        else {
            println!("{} {}", unparsable_prefix(), line);
            continue;
        };
        let log_value = JsonValue::Object(log_entry.clone());

        if let Some(filter_expression) = &settings.filter {
            let filter = filter::Filter {
                expression: filter_expression.clone(),
                implicit_return: !settings.no_implicit_filter_return_statement,
                print_lua: settings.print_lua,
            };
            match filter::apply_filter(&filter, &log_value) {
                Ok(true) => {}
                Ok(false) => continue,
                Err(error) => {
                    eprintln!(
                        "\x1b[31mFailed to apply filter expression\x1b[0m: {}",
                        error
                    );
                    continue;
                }
            }
        }

        let flattened = flatten_log_entry(&log_entry);

        let mut fblog_message = flattened
            .first(&settings.message_keys)
            .unwrap_or("")
            .to_string();

        if settings.substitute || settings.context_key.is_some() {
            let context_key = settings
                .context_key
                .clone()
                .unwrap_or_else(|| "context".to_string());
            if let Some(context) = log_entry.get(&context_key) {
                fblog_message = placeholder_format.replace(&fblog_message, context);
            }
        }

        let fblog_timestamp = flattened
            .first(&settings.time_keys)
            .map(convert_timestamp)
            .unwrap_or_default();

        let raw_level = flattened
            .first(&settings.level_keys)
            .unwrap_or("unknown")
            .to_string();
        let fblog_level = settings
            .level_map
            .get(&raw_level)
            .cloned()
            .unwrap_or(raw_level);

        let mut context = log_entry.clone();
        context.insert(
            "fblog_timestamp".to_string(),
            JsonValue::String(fblog_timestamp),
        );
        context.insert(
            "fblog_level".to_string(),
            JsonValue::String(fblog_level),
        );
        context.insert(
            "fblog_message".to_string(),
            JsonValue::String(fblog_message),
        );
        context.insert(
            "fblog_prefix".to_string(),
            JsonValue::String(prefix),
        );
        let context_value = JsonValue::Object(context);

        match templates.main_line.render(&context_value) {
            Ok(rendered) => println!("{}", rendered),
            Err(error) => {
                println!("{} Failed to process line: {}", bold_red_prefix(), error)
            }
        }

        let additional_values: Vec<(String, String)> = if settings.dump_all {
            flattened
                .iter()
                .filter(|(key, _)| !settings.excluded_values.iter().any(|excluded| excluded == key))
                .cloned()
                .collect()
        } else {
            settings
                .always_print_fields
                .iter()
                .flat_map(|requested| {
                    flattened
                        .iter()
                        .filter(|(key, _)| {
                            key == requested
                                || key.starts_with(&format!("{} > ", requested))
                                || key.starts_with(&format!("{}[", requested))
                        })
                        .cloned()
                        .collect::<Vec<_>>()
                })
                .collect()
        };

        for (key, value) in additional_values {
            let mut additional_context = Map::new();
            additional_context.insert("key".to_string(), JsonValue::String(key));
            additional_context.insert("value".to_string(), JsonValue::String(value));
            match templates
                .additional_value
                .render(&JsonValue::Object(additional_context))
            {
                Ok(rendered) => println!("{}", rendered),
                Err(error) => println!(
                    "{} Failed to process additional value: {}",
                    additional_error_prefix(),
                    error
                ),
            }
        }
    }

    filter::flush_deferred_lua_output();
}

fn open_input_file(path: &str) -> File {
    match File::open(path) {
        Ok(file) => file,
        Err(_) => panic!("Can't open file: {}", path),
    }
}
