// ---------------------------------------------------------------------------
// Additional standard library support

fn builtin_collectgarbage(_lua: &mut Lua, args: Vec<LuaValue>, _line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let option = args
        .get(0)
        .and_then(|value| match value {
            LuaValue::Str(bytes) => Some(String::from_utf8_lossy(bytes).into_owned()),
            _ => None,
        })
        .unwrap_or_else(|| "collect".to_string());
    Ok(match option.as_str() {
        "count" => {
            let kib = std::fs::read_to_string("/proc/self/statm")
                .ok()
                .and_then(|text| {
                    text.split_whitespace()
                        .next()
                        .and_then(|value| value.parse::<f64>().ok())
                })
                .map(|pages| pages * 4.0)
                .unwrap_or(0.0);
            vec![LuaValue::Float(kib)]
        }
        "isrunning" => vec![LuaValue::Bool(true)],
        _ => vec![LuaValue::Int(0)],
    })
}

fn builtin_warn(lua: &mut Lua, args: Vec<LuaValue>, _line: usize) -> Result<Vec<LuaValue>, LuaError> {
    if let Some(LuaValue::Str(bytes)) = args.get(0) {
        match &**bytes {
            b"@on" => {
                lua.warnings_on = true;
                return Ok(Vec::new());
            }
            b"@off" => {
                lua.warnings_on = false;
                return Ok(Vec::new());
            }
            b"@normal" | b"@light" => return Ok(Vec::new()),
            _ => {}
        }
    }
    if lua.warnings_on {
        let mut message = Vec::new();
        for value in &args {
            message.extend_from_slice(&value.to_lua_string(lua));
        }
        eprintln!("Lua warning: {}", String::from_utf8_lossy(&message));
    }
    Ok(Vec::new())
}

fn parse_chunk_function(
    lua: &mut Lua,
    source: &[u8],
    chunk_name: &str,
) -> Result<LuaValue, LuaValue> {
    let source_text = String::from_utf8_lossy(source).into_owned();
    let mut parser = match Parser::new(&source_text, chunk_name) {
        Ok(parser) => parser,
        Err(error) => return Err(bytes_value(error.bare_message().into_bytes())),
    };
    match parser.parse_chunk() {
        Ok(statements) => {
            let function = lua.make_function(FunctionKind::User {
                params: Vec::new(),
                vararg: true,
                body: Rc::new(statements),
                env: Scope::new(None, 0),
                chunk: chunk_name.to_string(),
                def_line: 1,
            });
            Ok(function)
        }
        Err(error) => Err(bytes_value(error.bare_message().into_bytes())),
    }
}

fn builtin_load(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let first = require_value(lua, line, "load", &args, 1)?.clone();
    let source = match &first {
        LuaValue::Str(bytes) => (**bytes).clone(),
        LuaValue::Function(_) => {
            // Reader function: call until it returns nil or an empty string.
            let mut source = Vec::new();
            loop {
                let values = lua.call_value(first.clone(), Vec::new(), line, None, &Scope::new(None, 0))?;
                match values.get(0) {
                    Some(LuaValue::Str(bytes)) if !bytes.is_empty() => source.extend_from_slice(bytes),
                    _ => break,
                }
            }
            source
        }
        _ => {
            return Err(bad_argument_type(
                lua,
                line,
                "load",
                1,
                "string",
                Some(&first),
            ))
        }
    };
    let chunk_name = if let Some(value) = args.get(1) {
        String::from_utf8_lossy(&coerce_string(lua, line, "load", &args, 2)?).into_owned()
    } else {
        let preview = String::from_utf8_lossy(&source).into_owned();
        format!("[string \"{}\"]", preview)
    };
    match parse_chunk_function(lua, &source, &chunk_name) {
        Ok(function) => Ok(vec![function]),
        Err(message) => Ok(vec![LuaValue::Nil, message]),
    }
}

fn builtin_loadfile(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    if args.is_empty() {
        return Ok(vec![LuaValue::Nil, str_value("stdin not supported")]);
    }
    let filename = coerce_string(lua, line, "loadfile", &args, 1)?;
    let filename_string = String::from_utf8_lossy(&filename).into_owned();
    match std::fs::read(&filename_string) {
        Ok(source) => match parse_chunk_function(lua, &source, &filename_string) {
            Ok(function) => Ok(vec![function]),
            Err(message) => Ok(vec![LuaValue::Nil, message]),
        },
        Err(error) => Ok(vec![
            LuaValue::Nil,
            str_value(&format!("cannot open {}: {}", filename_string, error)),
        ]),
    }
}

fn builtin_dofile(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    if args.is_empty() {
        return Err(lua.error_at(line, "stdin not supported", vec!["[C]: in ?".to_string()]));
    }
    let filename = coerce_string(lua, line, "dofile", &args, 1)?;
    let filename_string = String::from_utf8_lossy(&filename).into_owned();
    let source = std::fs::read_to_string(&filename_string).map_err(|error| {
        lua.error_at(
            line,
            &format!("cannot open {}: {}", filename_string, error),
            vec!["[C]: in ?".to_string()],
        )
    })?;
    lua.load_and_execute(&source, &filename_string)
}

fn builtin_require(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let name_bytes = coerce_string(lua, line, "require", &args, 1)?;
    let name = String::from_utf8_lossy(&name_bytes).into_owned();

    let package = lua.get_global("package");
    let loaded = if let LuaValue::Table(table) = &package {
        table.borrow().raw_get(&str_value("loaded"))
    } else {
        LuaValue::Nil
    };
    if let LuaValue::Table(loaded_table) = &loaded {
        let existing = loaded_table.borrow().raw_get(&str_value(&name));
        if existing.is_truthy() {
            return Ok(vec![existing]);
        }
    }
    let preload = if let LuaValue::Table(table) = &package {
        table.borrow().raw_get(&str_value("preload"))
    } else {
        LuaValue::Nil
    };
    if let LuaValue::Table(preload_table) = &preload {
        let loader = preload_table.borrow().raw_get(&str_value(&name));
        if matches!(loader, LuaValue::Function(_)) {
            let values = lua.call_value(loader, vec![str_value(&name)], line, None, &Scope::new(None, 0))?;
            let result = values.get(0).cloned().unwrap_or(LuaValue::Bool(true));
            if let LuaValue::Table(loaded_table) = &loaded {
                loaded_table.borrow_mut().raw_set(str_value(&name), result.clone());
            }
            return Ok(vec![result]);
        }
    }

    if let Some(filename) = package_search_file(lua, &name) {
        let source = std::fs::read_to_string(&filename).map_err(|error| {
            lua.error_at(line, &error.to_string(), vec!["[C]: in ?".to_string()])
        })?;
        let values = lua.load_and_execute(&source, &filename)?;
        let result = values.get(0).cloned().unwrap_or(LuaValue::Bool(true));
        if let LuaValue::Table(loaded_table) = &loaded {
            loaded_table.borrow_mut().raw_set(str_value(&name), result.clone());
        }
        return Ok(vec![result]);
    }

    Err(lua.error_at(
        line,
        &format!("module '{}' not found", name),
        vec!["[C]: in ?".to_string()],
    ))
}

fn package_search_file(lua: &Lua, module: &str) -> Option<String> {
    let package = lua.get_global("package");
    let path = if let LuaValue::Table(table) = &package {
        match table.borrow().raw_get(&str_value("path")) {
            LuaValue::Str(bytes) => String::from_utf8_lossy(&bytes).into_owned(),
            _ => String::new(),
        }
    } else {
        String::new()
    };
    let transformed = module.replace('.', "/");
    for pattern in path.split(';') {
        if pattern.is_empty() {
            continue;
        }
        let candidate = pattern.replace('?', &transformed);
        if std::path::Path::new(&candidate).is_file() {
            return Some(candidate);
        }
    }
    None
}

fn install_coroutine_library(lua: &mut Lua) {
    let table = lua.new_table();
    let functions: Vec<(&str, BuiltinFn)> = vec![
        ("create", builtin_coroutine_create),
        ("resume", builtin_coroutine_resume),
        ("yield", builtin_coroutine_yield),
        ("status", builtin_coroutine_status),
        ("wrap", builtin_coroutine_wrap),
        ("running", builtin_coroutine_running),
        ("isyieldable", builtin_coroutine_isyieldable),
        ("close", builtin_coroutine_close),
    ];
    for (name, function) in functions {
        let value = lua.builtin(name, function);
        set_table_field(lua, &table, name, value);
    }
    lua.set_global("coroutine", table);

    let main = lua.new_table();
    if let LuaValue::Table(inner) = &main {
        inner.borrow_mut().raw_set(str_value("__status"), str_value("running"));
        inner.borrow_mut().raw_set(str_value("__main"), LuaValue::Bool(true));
    }
    lua.main_coroutine = Some(main);
}

fn make_coroutine(lua: &mut Lua, function: LuaValue) -> LuaValue {
    let coroutine = lua.new_table();
    if let LuaValue::Table(inner) = &coroutine {
        inner.borrow_mut().raw_set(str_value("__coroutine_function"), function);
        inner.borrow_mut().raw_set(str_value("__status"), str_value("suspended"));
    }
    coroutine
}

fn coroutine_status(coroutine: &LuaValue) -> String {
    if let LuaValue::Table(inner) = coroutine {
        match inner.borrow().raw_get(&str_value("__status")) {
            LuaValue::Str(bytes) => String::from_utf8_lossy(&bytes).into_owned(),
            _ => "dead".to_string(),
        }
    } else {
        "dead".to_string()
    }
}

fn set_coroutine_status(coroutine: &LuaValue, status: &str) {
    if let LuaValue::Table(inner) = coroutine {
        inner.borrow_mut().raw_set(str_value("__status"), str_value(status));
    }
}

fn resume_coroutine(
    lua: &mut Lua,
    coroutine: LuaValue,
    args: Vec<LuaValue>,
    line: usize,
) -> Result<Vec<LuaValue>, LuaError> {
    if coroutine_status(&coroutine) == "dead" {
        return Ok(vec![
            LuaValue::Bool(false),
            str_value("cannot resume dead coroutine"),
        ]);
    }
    let function = if let LuaValue::Table(inner) = &coroutine {
        inner.borrow().raw_get(&str_value("__coroutine_function"))
    } else {
        LuaValue::Nil
    };
    let previous_active = lua.active_coroutine.clone();
    lua.active_coroutine = Some(coroutine.clone());
    lua.coroutine_depth += 1;
    lua.pending_yield = None;
    let result = lua.call_value(function, args, line, None, &Scope::new(None, 0));
    lua.coroutine_depth = lua.coroutine_depth.saturating_sub(1);
    lua.active_coroutine = previous_active;

    if let Some(yielded) = lua.pending_yield.take() {
        set_coroutine_status(&coroutine, "suspended");
        let mut values = vec![LuaValue::Bool(true)];
        values.extend(yielded);
        return Ok(values);
    }
    match result {
        Ok(mut values) => {
            set_coroutine_status(&coroutine, "dead");
            let mut result = vec![LuaValue::Bool(true)];
            result.append(&mut values);
            Ok(result)
        }
        Err(error) => {
            set_coroutine_status(&coroutine, "dead");
            Ok(vec![LuaValue::Bool(false), error_result_value(&error)])
        }
    }
}

