}

fn builtin_package_searchpath(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let name_bytes = coerce_string(lua, line, "searchpath", &args, 1)?;
    let name = String::from_utf8_lossy(&name_bytes).into_owned();
    let path = if args.len() >= 2 {
        String::from_utf8_lossy(&coerce_string(lua, line, "searchpath", &args, 2)?).into_owned()
    } else {
        let package = lua.get_global("package");
        if let LuaValue::Table(table) = package {
            match table.borrow().raw_get(&str_value("path")) {
                LuaValue::Str(bytes) => String::from_utf8_lossy(&bytes).into_owned(),
                _ => String::new(),
            }
        } else {
            String::new()
        }
    };
    let separator = if args.len() >= 3 {
        String::from_utf8_lossy(&coerce_string(lua, line, "searchpath", &args, 3)?).into_owned()
    } else {
        ".".to_string()
    };
    let file_separator = if args.len() >= 4 {
        String::from_utf8_lossy(&coerce_string(lua, line, "searchpath", &args, 4)?).into_owned()
    } else {
        "/".to_string()
    };
    let transformed = name.replace(&separator, &file_separator);
    let mut errors = String::new();
    for pattern in path.split(';') {
        if pattern.is_empty() {
            continue;
        }
        let candidate = pattern.replace('?', &transformed);
        if std::path::Path::new(&candidate).is_file() {
            return Ok(vec![str_value(&candidate)]);
        }
        errors.push_str(&format!("\n\tno file '{}'", candidate));
    }
    Ok(vec![LuaValue::Nil, str_value(&errors)])
}
