    set_file_handle_field(&handle, "__closed", LuaValue::Bool(true));
    Ok(vec![LuaValue::Bool(true)])
}

fn builtin_io_file_lines(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let handle = require_value(lua, line, "lines", &args, 1)?.clone();
    let iterator = lua.make_function(FunctionKind::FileLinesIterator { handle });
    Ok(vec![iterator])
}

fn builtin_io_file_seek(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let handle = require_value(lua, line, "seek", &args, 1)?.clone();
    let content_length = match file_handle_field(&handle, "__content") {
        LuaValue::Str(bytes) => bytes.len() as i64,
        _ => 0,
    };
    let current = int_value(&file_handle_field(&handle, "__pos")).unwrap_or(0);
    if args.len() < 2 {
        return Ok(vec![LuaValue::Int(current)]);
    }
    let whence = String::from_utf8_lossy(&coerce_string(lua, line, "seek", &args, 2)?).into_owned();
    let offset = optional_integer(lua, line, "seek", &args, 3, 0)?;
    let position = match whence.as_str() {
        "set" => offset,
        "end" => content_length + offset,
        _ => current + offset,
    }
    .max(0);
    set_file_handle_field(&handle, "__pos", LuaValue::Int(position));
    Ok(vec![LuaValue::Int(position)])
}

fn builtin_io_lines(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    if args.is_empty() {
        let handle = make_file_handle(lua, "", "r", Vec::new());
        let iterator = lua.make_function(FunctionKind::FileLinesIterator { handle });
        return Ok(vec![iterator]);
    }
    let opened = builtin_io_open(lua, args.clone(), line)?;
    let handle = opened.get(0).cloned().unwrap_or(LuaValue::Nil);
    if matches!(handle, LuaValue::Nil) {
        let message = opened.get(1).cloned().unwrap_or(LuaValue::Nil);
        return Err(lua.error_at(
            line,
            &String::from_utf8_lossy(&message.to_lua_string(lua)),
            vec!["[C]: in ?".to_string()],
        ));
    }
    let iterator = lua.make_function(FunctionKind::FileLinesIterator { handle });
    Ok(vec![iterator])
}

fn builtin_io_flush(_lua: &mut Lua, _args: Vec<LuaValue>, _line: usize) -> Result<Vec<LuaValue>, LuaError> {
    flush_deferred_lua_output();
    Ok(vec![LuaValue::Bool(true)])
}

fn builtin_io_close(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    if args.is_empty() {
        return Ok(vec![LuaValue::Bool(true)]);
    }
    builtin_io_file_close(lua, args, line)
}

fn builtin_io_type(_lua: &mut Lua, args: Vec<LuaValue>, _line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let Some(value) = args.get(0) else {
        return Ok(vec![LuaValue::Nil]);
    };
    if matches!(file_handle_field(value, "__file_handle"), LuaValue::Bool(true)) {
        if matches!(file_handle_field(value, "__closed"), LuaValue::Bool(true)) {
            Ok(vec![str_value("closed file")])
        } else {
            Ok(vec![str_value("file")])
        }
    } else {
        Ok(vec![LuaValue::Nil])
    }
}

fn builtin_io_input(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    if let Some(value) = args.get(0) {
        if matches!(value, LuaValue::Str(_)) {
            let opened = builtin_io_open(lua, vec![value.clone()], line)?;
            return Ok(vec![opened.get(0).cloned().unwrap_or(LuaValue::Nil)]);
        }
        return Ok(vec![value.clone()]);
    }
    let io_table = lua.get_global("io");
    if let LuaValue::Table(table) = io_table {
        Ok(vec![table.borrow().raw_get(&str_value("stdin"))])
    } else {
        Ok(vec![LuaValue::Nil])
    }
}

fn builtin_io_output(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    if let Some(value) = args.get(0) {
        if matches!(value, LuaValue::Str(_)) {
            let opened = builtin_io_open(lua, vec![value.clone(), str_value("w")], line)?;
            return Ok(vec![opened.get(0).cloned().unwrap_or(LuaValue::Nil)]);
        }
        return Ok(vec![value.clone()]);
    }
    let io_table = lua.get_global("io");
    if let LuaValue::Table(table) = io_table {
        Ok(vec![table.borrow().raw_get(&str_value("stdout"))])
    } else {
        Ok(vec![LuaValue::Nil])
    }
}

fn builtin_os_execute(_lua: &mut Lua, args: Vec<LuaValue>, _line: usize) -> Result<Vec<LuaValue>, LuaError> {
    if args.is_empty() || matches!(args[0], LuaValue::Nil) {
        return Ok(vec![LuaValue::Bool(true)]);
    }
    let command = match &args[0] {
        LuaValue::Str(bytes) => String::from_utf8_lossy(bytes).into_owned(),
        _ => return Ok(vec![LuaValue::Nil]),
    };
    match std::process::Command::new("/bin/sh").arg("-c").arg(&command).status() {
        Ok(status) => {
            if status.success() {
                Ok(vec![LuaValue::Bool(true), str_value("exit"), LuaValue::Int(0)])
            } else {
                Ok(vec![
                    LuaValue::Nil,
                    str_value("exit"),
                    LuaValue::Int(status.code().unwrap_or(1) as i64),
                ])
            }
        }
        Err(_) => Ok(vec![LuaValue::Nil, str_value("exit"), LuaValue::Int(1)]),
    }
}

fn builtin_os_remove(_lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let filename = coerce_string(_lua, line, "remove", &args, 1)?;
    let filename = String::from_utf8_lossy(&filename).into_owned();
    let result = if std::path::Path::new(&filename).is_dir() {
        std::fs::remove_dir(&filename)
    } else {
        std::fs::remove_file(&filename)
    };
    match result {
        Ok(()) => Ok(vec![LuaValue::Bool(true)]),
        Err(error) => Ok(vec![
            LuaValue::Nil,
            str_value(&format!("{}: {}", filename, error)),
            LuaValue::Int(error.raw_os_error().unwrap_or(0) as i64),
        ]),
    }
}

fn builtin_os_rename(_lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let old_name = String::from_utf8_lossy(&coerce_string(_lua, line, "rename", &args, 1)?).into_owned();
    let new_name = String::from_utf8_lossy(&coerce_string(_lua, line, "rename", &args, 2)?).into_owned();
    match std::fs::rename(&old_name, &new_name) {
        Ok(()) => Ok(vec![LuaValue::Bool(true)]),
        Err(error) => Ok(vec![
            LuaValue::Nil,
            str_value(&format!("{}: {}", old_name, error)),
            LuaValue::Int(error.raw_os_error().unwrap_or(0) as i64),
        ]),
    }
}

fn builtin_os_tmpname(_lua: &mut Lua, _args: Vec<LuaValue>, _line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let suffix = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_nanos())
        .unwrap_or(0);
    Ok(vec![str_value(&format!("/tmp/lua_{}", suffix))])
}

fn builtin_os_setlocale(_lua: &mut Lua, args: Vec<LuaValue>, _line: usize) -> Result<Vec<LuaValue>, LuaError> {
    if args.is_empty() || matches!(args[0], LuaValue::Nil) {
        return Ok(vec![str_value("C")]);
    }
    let locale = coerce_string(_lua, _line, "setlocale", &args, 1)?;
    if locale.is_empty() || locale == b"C" || locale == b"POSIX" {
        Ok(vec![str_value("C")])
    } else {
        Ok(vec![LuaValue::Nil])
    }
}
