fn install_additional_library_fields(lua: &mut Lua) {
    // String binary helpers.
    let string_table = lua.get_global("string");
    if matches!(string_table, LuaValue::Table(_)) {
        for (name, function) in [
            ("dump", builtin_string_dump as BuiltinFn),
            ("pack", builtin_string_pack as BuiltinFn),
            ("unpack", builtin_string_unpack as BuiltinFn),
            ("packsize", builtin_string_packsize as BuiltinFn),
        ] {
            let value = lua.builtin(name, function);
            set_table_field(lua, &string_table, name, value);
        }
    }

    // IO handles and additional functions.
    let io_table = lua.get_global("io");
    if matches!(io_table, LuaValue::Table(_)) {
        for (name, function) in [
            ("open", builtin_io_open as BuiltinFn),
            ("lines", builtin_io_lines as BuiltinFn),
            ("flush", builtin_io_flush as BuiltinFn),
            ("close", builtin_io_close as BuiltinFn),
            ("type", builtin_io_type as BuiltinFn),
            ("input", builtin_io_input as BuiltinFn),
            ("output", builtin_io_output as BuiltinFn),
            ("read", builtin_io_read as BuiltinFn),
        ] {
            let value = lua.builtin(name, function);
            set_table_field(lua, &io_table, name, value);
        }
        for handle_name in ["stdin", "stderr"] {
            let handle = make_file_handle(lua, "", "w", Vec::new());
            set_table_field(lua, &io_table, handle_name, handle);
        }
    }

    // Additional OS functions.
    let os_table = lua.get_global("os");
    if matches!(os_table, LuaValue::Table(_)) {
        for (name, function) in [
            ("execute", builtin_os_execute as BuiltinFn),
            ("remove", builtin_os_remove as BuiltinFn),
            ("rename", builtin_os_rename as BuiltinFn),
            ("tmpname", builtin_os_tmpname as BuiltinFn),
            ("setlocale", builtin_os_setlocale as BuiltinFn),
        ] {
            let value = lua.builtin(name, function);
            set_table_field(lua, &os_table, name, value);
        }
    }
}

