fn make_file_handle(lua: &mut Lua, path: &str, mode: &str, content: Vec<u8>) -> LuaValue {
    let handle = lua.new_table();
    if let LuaValue::Table(inner) = &handle {
        inner.borrow_mut().raw_set(str_value("__file_handle"), LuaValue::Bool(true));
        inner.borrow_mut().raw_set(str_value("__path"), str_value(path));
        inner.borrow_mut().raw_set(str_value("__mode"), str_value(mode));
        inner.borrow_mut().raw_set(str_value("__content"), bytes_value(content));
        inner.borrow_mut().raw_set(str_value("__pos"), LuaValue::Int(0));
        inner.borrow_mut().raw_set(str_value("__buffer"), bytes_value(Vec::new()));
        inner.borrow_mut().raw_set(str_value("__closed"), LuaValue::Bool(false));
    }
    for (name, function) in [
        ("read", builtin_io_file_read as BuiltinFn),
        ("write", builtin_io_file_write as BuiltinFn),
        ("close", builtin_io_file_close as BuiltinFn),
        ("lines", builtin_io_file_lines as BuiltinFn),
        ("seek", builtin_io_file_seek as BuiltinFn),
        ("setvbuf", builtin_unsupported_nil as BuiltinFn),
    ] {
        let value = lua.builtin(name, function);
        set_table_field(lua, &handle, name, value);
    }
    handle
}

fn file_handle_field(handle: &LuaValue, name: &str) -> LuaValue {
    if let LuaValue::Table(inner) = handle {
        inner.borrow().raw_get(&str_value(name))
    } else {
        LuaValue::Nil
    }
}

fn set_file_handle_field(handle: &LuaValue, name: &str, value: LuaValue) {
    if let LuaValue::Table(inner) = handle {
        inner.borrow_mut().raw_set(str_value(name), value);
    }
}

fn builtin_io_open(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let filename = coerce_string(lua, line, "open", &args, 1)?;
    let filename = String::from_utf8_lossy(&filename).into_owned();
    let mode = if args.len() >= 2 {
        String::from_utf8_lossy(&coerce_string(lua, line, "open", &args, 2)?).into_owned()
    } else {
        "r".to_string()
    };
    let reading = mode.starts_with('r') || mode.contains('+');
    let content = if reading || mode.starts_with('a') {
        match std::fs::read(&filename) {
            Ok(content) => content,
            Err(error) => {
                if mode.starts_with('w') || mode.starts_with('a') {
                    Vec::new()
                } else {
                    return Ok(vec![
                        LuaValue::Nil,
                        str_value(&format!("{}: {}", filename, error)),
                        LuaValue::Int(error.raw_os_error().unwrap_or(0) as i64),
                    ]);
                }
            }
        }
    } else {
        Vec::new()
    };
    let handle = make_file_handle(lua, &filename, &mode, content.clone());
    if mode.starts_with('a') {
        set_file_handle_field(&handle, "__buffer", bytes_value(content));
    }
    Ok(vec![handle])
}

fn builtin_io_file_read(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let handle = require_value(lua, line, "read", &args, 1)?.clone();
    if !matches!(file_handle_field(&handle, "__file_handle"), LuaValue::Bool(true)) {
        return Err(bad_argument_type(lua, line, "read", 1, "FILE*", Some(&handle)));
    }
    if matches!(file_handle_field(&handle, "__closed"), LuaValue::Bool(true)) {
        return Ok(vec![LuaValue::Nil]);
    }
    let content = match file_handle_field(&handle, "__content") {
        LuaValue::Str(bytes) => (*bytes).clone(),
        _ => Vec::new(),
    };
    let mut position = int_value(&file_handle_field(&handle, "__pos")).unwrap_or(0) as usize;
    let mut formats: Vec<LuaValue> = args.iter().skip(1).cloned().collect();
    if formats.is_empty() {
        formats.push(str_value("l"));
    }
    let mut results = Vec::new();
    for format in formats {
        if position >= content.len() {
            results.push(LuaValue::Nil);
            continue;
        }
        match &format {
            LuaValue::Int(count) => {
                let count = (*count).max(0) as usize;
                let end = (position + count).min(content.len());
                results.push(bytes_value(content[position..end].to_vec()));
                position = end;
            }
            LuaValue::Float(count) => {
                let count = (*count).max(0.0) as usize;
                let end = (position + count).min(content.len());
                results.push(bytes_value(content[position..end].to_vec()));
                position = end;
            }
            LuaValue::Str(spec) => {
                let spec_text = String::from_utf8_lossy(spec).into_owned();
                match spec_text.as_str() {
                    "*a" | "a" => {
                        results.push(bytes_value(content[position..].to_vec()));
                        position = content.len();
                    }
                    "*l" | "l" => {
                        let start = position;
                        while position < content.len() && content[position] != b'\n' {
                            position += 1;
                        }
                        let mut line_bytes = content[start..position].to_vec();
                        if position < content.len() {
                            position += 1;
                        }
                        if line_bytes.ends_with(b"\r") {
                            line_bytes.pop();
                        }
                        results.push(bytes_value(line_bytes));
                    }
                    "*L" | "L" => {
                        let start = position;
                        while position < content.len() && content[position] != b'\n' {
                            position += 1;
                        }
                        if position < content.len() {
                            position += 1;
                        }
                        results.push(bytes_value(content[start..position].to_vec()));
                    }
                    "*n" | "n" => {
                        let text = String::from_utf8_lossy(&content[position..]).into_owned();
                        let trimmed = text.trim_start();
                        let offset = text.len() - trimmed.len();
                        let mut end = offset;
                        for c in trimmed.chars() {
                            if c.is_ascii_digit() || matches!(c, '.' | '-' | '+' | 'e' | 'E') {
                                end += c.len_utf8();
                            } else {
                                break;
                            }
                        }
                        let number_text = &text[offset..end];
                        match parse_lua_number_string(number_text.as_bytes()) {
                            Some(number) => results.push(number),
                            None => results.push(LuaValue::Nil),
                        }
                        position += end;
                    }
                    _ => results.push(LuaValue::Nil),
                }
            }
            _ => results.push(LuaValue::Nil),
        }
    }
    set_file_handle_field(&handle, "__pos", LuaValue::Int(position as i64));
    Ok(results)
}

fn builtin_io_file_write(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let handle = require_value(lua, line, "write", &args, 1)?.clone();
    let mode = match file_handle_field(&handle, "__mode") {
        LuaValue::Str(bytes) => String::from_utf8_lossy(&bytes).into_owned(),
        _ => String::new(),
    };
    if mode.starts_with('r') && !mode.contains('+') {
        return Ok(vec![
            LuaValue::Nil,
            str_value("Bad file descriptor"),
        ]);
    }
    let mut buffer = match file_handle_field(&handle, "__buffer") {
        LuaValue::Str(bytes) => (*bytes).clone(),
        _ => Vec::new(),
    };
    for (index, value) in args.iter().skip(1).enumerate() {
        match value {
            LuaValue::Str(bytes) => buffer.extend_from_slice(bytes),
            LuaValue::Int(number) => buffer.extend_from_slice(number.to_string().as_bytes()),
            LuaValue::Float(number) => buffer.extend_from_slice(lua_float_to_string(*number).as_bytes()),
            _ => {
                return Err(bad_argument_type(
                    lua,
                    line,
                    "write",
                    index + 2,
                    "string",
                    Some(value),
                ))
            }
        }
    }
    set_file_handle_field(&handle, "__buffer", bytes_value(buffer));
    Ok(vec![handle])
}

fn builtin_io_file_close(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let handle = require_value(lua, line, "close", &args, 1)?.clone();
    let path = match file_handle_field(&handle, "__path") {
        LuaValue::Str(bytes) => String::from_utf8_lossy(&bytes).into_owned(),
        _ => String::new(),
    };
    let mode = match file_handle_field(&handle, "__mode") {
        LuaValue::Str(bytes) => String::from_utf8_lossy(&bytes).into_owned(),
        _ => String::new(),
    };
    if !path.is_empty() && (mode.contains('w') || mode.contains('a') || mode.contains('+')) {
        let buffer = match file_handle_field(&handle, "__buffer") {
            LuaValue::Str(bytes) => (*bytes).clone(),
            _ => Vec::new(),
        };
        let result = if mode.starts_with('a') {
            std::fs::write(&path, &buffer)
        } else if mode.contains('+') && mode.starts_with('r') {
            // For update modes, only write when data was supplied.
            if buffer.is_empty() {
                Ok(())
            } else {
                std::fs::write(&path, &buffer)
            }
        } else {
            std::fs::write(&path, &buffer)
        };
        if let Err(error) = result {
            return Ok(vec![
                LuaValue::Nil,
                str_value(&error.to_string()),
                LuaValue::Int(error.raw_os_error().unwrap_or(0) as i64),
            ]);
        }
    }
    set_file_handle_field(&handle, "__closed", LuaValue::Bool(true));
    Ok(vec![LuaValue::Bool(true)])
}

fn builtin_io_file_lines(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
