    let data = coerce_string(lua, line, "unpack", &args, 2)?;
    let (items, big_endian, max_align) = parse_pack_format(&format)
        .map_err(|message| lua.error_at(line, &message, vec!["[C]: in ?".to_string()]))?;
    let mut position = optional_integer(lua, line, "unpack", &args, 3, 1)?;
    let mut offset = if position > 0 {
        (position - 1).max(0) as usize
    } else if position < 0 {
        (data.len() as i64 + position).max(0) as usize
    } else {
        0
    };
    let mut results = Vec::new();
    for item in items {
        match item.kind {
            PackKind::Padding => {
                if item.size == 1 {
                    offset += 1;
                }
                continue;
            }
            PackKind::Fixed => {
                if offset + item.size > data.len() {
                    return Err(bad_argument(lua, line, "unpack", 2, "data string too short"));
                }
                results.push(bytes_value(data[offset..offset + item.size].to_vec()));
                offset += item.size;
                continue;
            }
            PackKind::ZeroString => {
                let start = offset;
                while offset < data.len() && data[offset] != 0 {
                    offset += 1;
                }
                results.push(bytes_value(data[start..offset].to_vec()));
                if offset < data.len() {
                    offset += 1;
                }
                continue;
            }
            PackKind::LengthString => {
                offset += pack_alignment(offset, item.size, max_align);
                if offset + item.size > data.len() {
                    return Err(bad_argument(lua, line, "unpack", 2, "data string too short"));
                }
                let length = read_packed_integer(&data[offset..offset + item.size], big_endian) as usize;
                offset += item.size;
                if offset + length > data.len() {
                    return Err(bad_argument(lua, line, "unpack", 2, "data string too short"));
                }
                results.push(bytes_value(data[offset..offset + length].to_vec()));
                offset += length;
                continue;
            }
            PackKind::Signed | PackKind::Unsigned => {
                offset += pack_alignment(offset, item.size, max_align);
                if offset + item.size > data.len() {
                    return Err(bad_argument(lua, line, "unpack", 2, "data string too short"));
                }
                let unsigned = read_packed_integer(&data[offset..offset + item.size], big_endian);
                offset += item.size;
                let value = if item.kind == PackKind::Signed {
                    sign_extend_packed(unsigned, item.size)
                } else {
                    unsigned as i64
                };
                results.push(LuaValue::Int(value));
            }
            PackKind::Float => {
                offset += pack_alignment(offset, item.size, max_align);
                if offset + item.size > data.len() {
                    return Err(bad_argument(lua, line, "unpack", 2, "data string too short"));
                }
                let unsigned = read_packed_integer(&data[offset..offset + item.size], big_endian);
                offset += item.size;
                let value = if item.size == 4 {
                    f32::from_bits(unsigned as u32) as f64
                } else {
                    f64::from_bits(unsigned)
                };
                results.push(LuaValue::Float(value));
            }
        }
    }
    results.push(LuaValue::Int(offset as i64 + 1));
    Ok(results)
}

fn read_packed_integer(bytes: &[u8], big_endian: bool) -> u64 {
    let mut value = 0u64;
    if big_endian {
        for byte in bytes {
            value = (value << 8) | (*byte as u64);
        }
    } else {
        for (index, byte) in bytes.iter().enumerate() {
            value |= (*byte as u64) << (index * 8);
        }
    }
    value
}

fn sign_extend_packed(value: u64, size: usize) -> i64 {
    if size == 0 || size >= 8 {
        return value as i64;
    }
    let shift = 64 - size * 8;
    ((value << shift) as i64) >> shift
}

fn builtin_string_packsize(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let format = coerce_string(lua, line, "packsize", &args, 1)?;
