            b'<' => big_endian = false,
            b'>' => big_endian = true,
            b'=' => big_endian = cfg!(target_endian = "big"),
            b'!' => {
                let mut number = String::new();
                while index < format.len() && format[index].is_ascii_digit() {
                    number.push(format[index] as char);
                    index += 1;
                }
                max_align = if number.is_empty() {
                    8
                } else {
                    number.parse::<usize>().map_err(|_| "bad format".to_string())?
                };
                if max_align == 0 || !max_align.is_power_of_two() {
                    return Err("bad argument #1 to 'pack' (invalid alignment)".to_string());
                }
            }
            b'b' => items.push(PackItem { kind: PackKind::Signed, size: 1 }),
            b'B' => items.push(PackItem { kind: PackKind::Unsigned, size: 1 }),
            b'h' => items.push(PackItem { kind: PackKind::Signed, size: 2 }),
            b'H' => items.push(PackItem { kind: PackKind::Unsigned, size: 2 }),
            b'l' | b'j' => items.push(PackItem { kind: PackKind::Signed, size: 8 }),
            b'L' | b'J' | b'T' => items.push(PackItem { kind: PackKind::Unsigned, size: 8 }),
            b'i' | b'I' => {
                let kind = if byte == b'i' { PackKind::Signed } else { PackKind::Unsigned };
                let mut number = String::new();
                while index < format.len() && format[index].is_ascii_digit() {
                    number.push(format[index] as char);
                    index += 1;
                }
                let size = if number.is_empty() { 4 } else { number.parse::<usize>().map_err(|_| "bad format".to_string())? };
                if size == 0 || size > 8 {
                    return Err("bad argument #1 to 'pack' (integral size out of limits)".to_string());
                }
                items.push(PackItem { kind, size });
            }
            b'f' => items.push(PackItem { kind: PackKind::Float, size: 4 }),
            b'd' | b'n' => items.push(PackItem { kind: PackKind::Float, size: 8 }),
            b'c' => {
                let mut number = String::new();
                while index < format.len() && format[index].is_ascii_digit() {
                    number.push(format[index] as char);
                    index += 1;
                }
                let size = number.parse::<usize>().map_err(|_| "missing size for format option 'c'".to_string())?;
                items.push(PackItem { kind: PackKind::Fixed, size });
            }
            b's' => {
                let mut number = String::new();
                while index < format.len() && format[index].is_ascii_digit() {
                    number.push(format[index] as char);
                    index += 1;
                }
                let size = if number.is_empty() { 8 } else { number.parse::<usize>().map_err(|_| "bad format".to_string())? };
                if size == 0 || size > 8 {
                    return Err("bad argument #1 to 'pack' (integral size out of limits)".to_string());
                }
                items.push(PackItem { kind: PackKind::LengthString, size });
            }
            b'z' => items.push(PackItem { kind: PackKind::ZeroString, size: 0 }),
            b'x' => items.push(PackItem { kind: PackKind::Padding, size: 1 }),
            b'X' => items.push(PackItem { kind: PackKind::Padding, size: 0 }),
            _ => {
                return Err(format!(
