                let mut number = String::new();
                while index < format.len() && format[index].is_ascii_digit() {
                    number.push(format[index] as char);
                    index += 1;
                }
                let size = number.parse::<usize>().map_err(|_| "missing size for format option 'c'".to_string())?;
                items.push(PackItem { kind: PackKind::Fixed, size });
            }
            b's' => {
                let mut number = String::new();
                while index < format.len() && format[index].is_ascii_digit() {
                    number.push(format[index] as char);
                    index += 1;
                }
                let size = if number.is_empty() { 8 } else { number.parse::<usize>().map_err(|_| "bad format".to_string())? };
                if size == 0 || size > 8 {
                    return Err("bad argument #1 to 'pack' (integral size out of limits)".to_string());
                }
                items.push(PackItem { kind: PackKind::LengthString, size });
            }
            b'z' => items.push(PackItem { kind: PackKind::ZeroString, size: 0 }),
            b'x' => items.push(PackItem { kind: PackKind::Padding, size: 1 }),
            b'X' => items.push(PackItem { kind: PackKind::Padding, size: 0 }),
            _ => {
                return Err(format!(
                    "bad argument #1 to 'pack' (invalid format option '{}')",
                    byte as char
                ))
            }
        }
    }
    Ok((items, big_endian, max_align))
}

fn pack_alignment(offset: usize, item_size: usize, max_align: usize) -> usize {
    let alignment = item_size.min(max_align);
    if alignment <= 1 {
        0
    } else {
        (alignment - (offset % alignment)) % alignment
    }
}

fn pack_integer_bytes(value: u64, size: usize, big_endian: bool) -> Vec<u8> {
    let bytes = value.to_ne_bytes();
    let selected: Vec<u8> = if cfg!(target_endian = "big") {
        bytes[8 - size..].to_vec()
    } else {
        bytes[..size].to_vec()
    };
    if (cfg!(target_endian = "big") && !big_endian) || (!cfg!(target_endian = "big") && big_endian) {
        // Convert from native selection to requested by using value shifts
        // directly, which is clearer than byte reversal above.
        let mut result = Vec::new();
        if big_endian {
            for shift in (0..size).rev() {
                result.push(((value >> (shift * 8)) & 0xff) as u8);
            }
        } else {
            for shift in 0..size {
                result.push(((value >> (shift * 8)) & 0xff) as u8);
            }
        }
        result
    } else if big_endian {
        let mut result = Vec::new();
        for shift in (0..size).rev() {
            result.push(((value >> (shift * 8)) & 0xff) as u8);
        }
        result
    } else {
        selected
    }
}

fn builtin_string_pack(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let format = coerce_string(lua, line, "pack", &args, 1)?;
    let (items, big_endian, max_align) = parse_pack_format(&format)
        .map_err(|message| lua.error_at(line, &message, vec!["[C]: in ?".to_string()]))?;
    let mut output = Vec::new();
    let mut argument_index = 2usize;
    for item in items {
        match item.kind {
            PackKind::Padding => {
                if item.size == 1 {
                    output.push(0);
                }
                continue;
            }
            PackKind::Fixed => {
                let value = coerce_string(lua, line, "pack", &args, argument_index)?;
                argument_index += 1;
                let mut bytes = value;
                bytes.resize(item.size, 0);
                bytes.truncate(item.size);
                output.extend_from_slice(&bytes);
                continue;
            }
            PackKind::ZeroString => {
                let value = coerce_string(lua, line, "pack", &args, argument_index)?;
                argument_index += 1;
                output.extend_from_slice(&value);
                output.push(0);
                continue;
            }
            PackKind::LengthString => {
                let value = coerce_string(lua, line, "pack", &args, argument_index)?;
                argument_index += 1;
                output.extend(std::iter::repeat(0).take(pack_alignment(output.len(), item.size, max_align)));
                output.extend_from_slice(&pack_integer_bytes(value.len() as u64, item.size, big_endian));
                output.extend_from_slice(&value);
                continue;
            }
            PackKind::Signed | PackKind::Unsigned => {
                let value = require_value(lua, line, "pack", &args, argument_index)?.clone();
                let number = format_integer_argument(lua, line, &value, argument_index)?;
                argument_index += 1;
                output.extend(std::iter::repeat(0).take(pack_alignment(output.len(), item.size, max_align)));
                output.extend_from_slice(&pack_integer_bytes(number as u64, item.size, big_endian));
            }
            PackKind::Float => {
                let value = require_value(lua, line, "pack", &args, argument_index)?.clone();
                let number = format_number_argument(lua, line, &value, argument_index)?;
                argument_index += 1;
                output.extend(std::iter::repeat(0).take(pack_alignment(output.len(), item.size, max_align)));
                if item.size == 4 {
                    let bytes = (number as f32).to_bits().to_ne_bytes();
                    let value = u32::from_ne_bytes(bytes) as u64;
                    output.extend_from_slice(&pack_integer_bytes(value, 4, big_endian));
                } else {
                    output.extend_from_slice(&pack_integer_bytes(number.to_bits(), 8, big_endian));
                }
            }
        }
    }
    Ok(vec![bytes_value(output)])
}

fn builtin_string_unpack(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let format = coerce_string(lua, line, "unpack", &args, 1)?;
    let data = coerce_string(lua, line, "unpack", &args, 2)?;
    let (items, big_endian, max_align) = parse_pack_format(&format)
        .map_err(|message| lua.error_at(line, &message, vec!["[C]: in ?".to_string()]))?;
    let mut position = optional_integer(lua, line, "unpack", &args, 3, 1)?;
    let mut offset = if position > 0 {
        (position - 1).max(0) as usize
    } else if position < 0 {
        (data.len() as i64 + position).max(0) as usize
    } else {
        0
    };
    let mut results = Vec::new();
    for item in items {
        match item.kind {
            PackKind::Padding => {
                if item.size == 1 {
                    offset += 1;
                }
                continue;
            }
            PackKind::Fixed => {
                if offset + item.size > data.len() {
                    return Err(bad_argument(lua, line, "unpack", 2, "data string too short"));
                }
                results.push(bytes_value(data[offset..offset + item.size].to_vec()));
                offset += item.size;
                continue;
            }
            PackKind::ZeroString => {
                let start = offset;
                while offset < data.len() && data[offset] != 0 {
                    offset += 1;
                }
                results.push(bytes_value(data[start..offset].to_vec()));
                if offset < data.len() {
                    offset += 1;
                }
                continue;
            }
            PackKind::LengthString => {
                offset += pack_alignment(offset, item.size, max_align);
                if offset + item.size > data.len() {
                    return Err(bad_argument(lua, line, "unpack", 2, "data string too short"));
                }
                let length = read_packed_integer(&data[offset..offset + item.size], big_endian) as usize;
                offset += item.size;
                if offset + length > data.len() {
                    return Err(bad_argument(lua, line, "unpack", 2, "data string too short"));
                }
                results.push(bytes_value(data[offset..offset + length].to_vec()));
                offset += length;
                continue;
            }
            PackKind::Signed | PackKind::Unsigned => {
                offset += pack_alignment(offset, item.size, max_align);
                if offset + item.size > data.len() {
                    return Err(bad_argument(lua, line, "unpack", 2, "data string too short"));
                }
                let unsigned = read_packed_integer(&data[offset..offset + item.size], big_endian);
                offset += item.size;
                let value = if item.kind == PackKind::Signed {
                    sign_extend_packed(unsigned, item.size)
                } else {
                    unsigned as i64
                };
                results.push(LuaValue::Int(value));
            }
            PackKind::Float => {
                offset += pack_alignment(offset, item.size, max_align);
                if offset + item.size > data.len() {
                    return Err(bad_argument(lua, line, "unpack", 2, "data string too short"));
                }
                let unsigned = read_packed_integer(&data[offset..offset + item.size], big_endian);
                offset += item.size;
                let value = if item.size == 4 {
                    f32::from_bits(unsigned as u32) as f64
                } else {
                    f64::from_bits(unsigned)
                };
                results.push(LuaValue::Float(value));
            }
        }
    }
    results.push(LuaValue::Int(offset as i64 + 1));
    Ok(results)
}

fn read_packed_integer(bytes: &[u8], big_endian: bool) -> u64 {
    let mut value = 0u64;
    if big_endian {
        for byte in bytes {
            value = (value << 8) | (*byte as u64);
        }
    } else {
        for (index, byte) in bytes.iter().enumerate() {
            value |= (*byte as u64) << (index * 8);
        }
    }
    value
}

fn sign_extend_packed(value: u64, size: usize) -> i64 {
    if size == 0 || size >= 8 {
        return value as i64;
    }
    let shift = 64 - size * 8;
    ((value << shift) as i64) >> shift
}

fn builtin_string_packsize(lua: &mut Lua, args: Vec<LuaValue>, line: usize) -> Result<Vec<LuaValue>, LuaError> {
    let format = coerce_string(lua, line, "packsize", &args, 1)?;
    let (items, _big_endian, max_align) = parse_pack_format(&format)
        .map_err(|message| lua.error_at(line, &message, vec!["[C]: in ?".to_string()]))?;
    let mut size = 0usize;
    for item in items {
        match item.kind {
            PackKind::LengthString | PackKind::ZeroString => {
                return Err(bad_argument(
                    lua,
                    line,
                    "packsize",
                    1,
                    "variable length format",
                ));
            }
            PackKind::Padding => size += item.size,
            _ => {
                size += pack_alignment(size, item.size, max_align);
                size += item.size;
            }
        }
    }
    Ok(vec![LuaValue::Int(size as i64)])
}
